        except (TypeError, ValueError):
            raise TypeError("timeout must be a number or None")
        if _timeout_val < 0:
            raise ValueError("timeout must not be negative")
    def decorator(tx_func):
        def wrapper(*args, **kwargs):
            # Expect the session to be passed as the first positional argument
            if not args:
                raise ValueError("The decorated function must be called with a Session as the first argument.")
            session = args[0]
            tx_options = {}
            # Attach metadata if provided
            if metadata is not None:
                if not isinstance(metadata, dict):
                    raise TypeError("metadata must be a dict")
                tx_options["metadata"] = metadata
            # Attach timeout if provided
            if timeout is not None:
                tx_options["timeout"] = timeout
            # Open a transaction with the specified options and run the wrapped function
            with session.begin_transaction(**tx_options) as tx:
                # The decorated function receives the transaction object as the first argument,
                # followed by the remaining positional and keyword arguments.
                return tx_func(tx, *args[1:], **kwargs)
