        raise TypeError(f"srid_map must be a dict or None, got {type(srid_map).__name__}")

    # Prepare namespace for the new class
    namespace = {
        "_srid_map": srid_map,
    }

    # Define a simple __init__ that forwards arguments to the base Point class
    def __init__(self, *args, **kwargs):
        # The base Point (e.g., from shapely.geometry) expects x, y, (z, m)
        # We forward positional arguments directly; keyword arguments are passed as-is.
        super(cls, self).__init__(*args, **kwargs)

    namespace["__init__"] = __init__

    # Helper to produce a readable representation
    def __repr__(self):
        coord = ", ".join(f"{name}={getattr(self, name)!r}"
                          for name in fields if hasattr(self, name))
        return f"{name}({coord})"

    namespace["__repr__"] = __repr__

    # Add attribute getters for any fields that are not already managed
    for fname in fields:
        if not hasattr(Point, fname):
            namespace[fname] = property(lambda self, n=fname: getattr(self, n))

    # Dynamically create the subclass
    cls = type(name, (Point,), namespace)
