def _inline_r_setup(code: str) -> str:
    """
    Some behaviour of R cannot be configured via env variables, but can
    only be configured via R options once R has started. These are set here.
    """
    # Ensure valid input
    if not isinstance(code, str):
        raise TypeError(f"_inline_r_setup expects a str, got {type(code).__name__}")

    # Define the R options that need to be set before the user code runs.
    r_options = [
        "stringsAsFactors = FALSE",
        "encoding = \"UTF-8\"",
        "show.error.messages = TRUE",
    ]
    options_line = f"options({', '.join(r_options)})"

    # Do not duplicate the options if they are already present in the code.
    if options_line in code:
        return code

    # Preserve shebang lines, if present.
    lines = code.splitlines()
    if lines and lines[0].startswith("#!"):
        # Insert the options after the shebang
        return "\n".join([lines[0], options_line] + lines[1:])
    else:
        # Simply prepend the options
        if code.strip():
            return f"{options_line}\n{code}"
        else:
            # If the code block is empty, just return the options line.
            return options_line

def _shuffled(seq: Sequence[str]) -> list[str]:
    """Deterministically shuffle."""
    import random

    if seq is None:
        raise TypeError("Input sequence cannot be None")

    try:
        items = list(seq)
    except Exception as exc:
        raise TypeError("Input must be a sequence") from exc

    # Ensure all elements are strings
    for idx, item in enumerate(items):
        if not isinstance(item, str):
            raise TypeError(f"Element at index {idx} is not a string: {item!r}")

    # Create a deterministic seed based on the contents of the sequence
    try:
        seed = hash(tuple(items))
    except Exception:
        # Fallback: compute a simple sum of character codes if hashing fails
        seed = sum(sum(ord(ch) for ch in s) for s in items)

    rnd = random.Random(seed)
    rnd.shuffle(items)
    return items

