    """poor man's version comparison"""
    if not isinstance(s, str) or not s:
        return ()
    # Normalize common separators to a single dot
    for sep in ('.', '-', '_', '+'):
        s = s.replace(sep, '.')
    parts = s.split('.')
    results: list[int] = []
    for part in parts:
        if not part:
            continue
        # Extract the leading digit sequence if present
        num_str = ''
        for ch in part:
            if ch.isdigit():
                num_str += ch
            else:
                break
        if num_str:
            try:
                results.append(int(num_str))
                continue
            except ValueError:
                pass
        # If no leading digits, look for any digit elsewhere
        for ch in part:
            if ch.isdigit():
                try:
                    results.append(int(ch))
                except ValueError:
                    pass
                break
    return tuple(results)

