def lfu_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Least Frequently Used (LFU)
    algorithm.
    """
    def decorator(func):
        cache = {}
        usage = {}

        if maxsize <= 0:
            return func

        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            if typed:
                key_args = tuple((x, type(x)) for x in args)
                key_kwargs = tuple(sorted((k, type(v), v) for k, v in kwargs.items()))
            else:
                key_args = args
                key_kwargs = tuple(sorted(kwargs.items()))

            key = (key_args, key_kwargs)

            if key in cache:
                usage[key] = usage[key] + 1
                return cache[key]

            result = func(*args, **kwargs)
            cache[key] = result
            usage[key] = 1

            if len(cache) > maxsize:
                # Evict item with lowest usage count (and one of them if ties)
                min_usage = min(usage.values())
                for k in list(cache):
                    if usage[k] == min_usage:
                        del cache[k]
                        del usage[k]
                        break
            return result

        return wrapper

    return decorator

