@classmethod
    def extostr(cls, e, max_level=30, max_path_level=5):
        """
        Format an exception.
        :param e: Any exception instance.
        :type e: Exception
        :param max_level: Maximum call stack level (default 30)
        :type max_level: int
        :param max_path_level: Maximum path level (default 5)
        :type max_path_level: int
        :return The exception readable string
        :rtype str
        """
        import os
        import traceback

        # If e is not an exception, simply return its string representation
        if not isinstance(e, BaseException):
            return str(e)

        # Ensure bounds for max_level and max_path_level
        try:
            max_level = int(max_level)
            if max_level < 0:
                max_level = 0
        except Exception:
            max_level = 30
        try:
            max_path_level = int(max_path_level)
            if max_path_level < 1:
                max_path_level = 1
        except Exception:
            max_path_level = 5

        # Build the exception message
        result_lines = [f"{type(e).__name__}: {e}"]

        # Extract traceback elements if available
        tb = getattr(e, "__traceback__", None)
        if tb is None:
            return "\n".join(result_lines)

        extracted = traceback.extract_tb(tb)
        # Limit the number of frames according to max_level
        for i, frame in enumerate(extracted):
            if i >= max_level:
                break
            # Shorten file path if it has more than max_path_level components
            file_path = frame.filename
            parts = file_path.split(os.sep)
            if len(parts) > max_path_level:
                # Keep last max_path_level-1 components, prepend ellipsis
                file_path = os.sep.join([ "..." ] + parts[-(max_path_level-1):])
            # Format frame information
            result_lines.append(f'  File "{file_path}", line {frame.lineno}, in {frame.name}')
            if frame.line:
                # Strip leading/trailing whitespace and indent source line
                result_lines.append(f'    {frame.line.strip()}')

        return "\n".join(result_lines)

@classmethod
def extostr(cls, e, max_level=30, max_path_level=5):
    """Format an exception into a readable string.

    Parameters
    ----------
    e : Exception
        Any exception instance.
    max_level : int, optional
        Maximum number of stack trace levels to include (default 30).
    max_path_level : int, optional
        Maximum number of path components to display in file names
        (default 5).

    Returns
    -------
    str
        The formatted exception string.
    """
    # Basic validation and defaults
    try:
        max_level = int(max_level)
        if max_level < 1:
            max_level = 30
    except Exception:
        max_level = 30
    try:
        max_path_level = int(max_path_level)
        if max_path_level < 1:
            max_path_level = 5
    except Exception:
        max_path_level = 5

    # If e is not an exception instance, just return its string
    if not isinstance(e, BaseException):
        try:
            return str(e)
        except Exception:
            return repr(e)

    # Prepare components
    lines = []
    try:
        # Attempt to import modules; rely on the caller to have imported them
        import sys
        import os
        import traceback
    except Exception:
        # Fallback: return simple representation
        return f"{type(e).__name__}: {e}"

    # Get traceback: first check the exception's __traceback__, then sys.exc_info
    tb = getattr(e, "__traceback__", None)
    if tb is None:
        tb = sys.exc_info()[2]

    if tb:
        try:
            stack = traceback.extract_tb(tb)
            # Restrict to the last 'max_level' frames (most recent first)
            stack = stack[-max_level:]
            for frame in stack:
                path = frame.filename or ""
                # Reduce the path to at most max_path_level components
                parts = path.split(os.sep)
                if len(parts) > max_path_level:
                    path = os.sep.join(parts[-max_path_level:])
                lines.append(f'  File "{path}", line {frame.lineno}, in {frame.name}')
                if frame.line:
                    lines.append(f'    {frame.line.strip()}')
        except Exception:
            # If anything goes wrong while extracting the stack, ignore it
            pass

    exc_type = type(e).__name__
    msg = str(e)
    result = ""
    if lines:
        result += "Traceback (most recent call last):\n"
        result += "\n".join(lines)
    result += f"\n{exc_type}: {msg}"
    return result

