@classmethod
def _reset_logging(cls):
    """
    Reset logging to its original configuration.
    This method clears the root logger handlers, restores the root level to WARNING,
    and reverts any monkey‑patched logging handler classes to their originals
    if they were stored as class attributes.
    """
    # Clear root logger and reset level
    try:
        root = logging.getLogger()
        root.handlers.clear()
        root.setLevel(logging.WARNING)
    except Exception:
        # Swallow any unexpected errors during reset
        pass

    # Mapping of replaced attributes to their original stored on the class
    replacements = {
        'StreamHandler': getattr(cls, "_original_StreamHandler", None),
        'FileHandler': getattr(cls, "_original_FileHandler", None),
        'handlers.SysLogHandler': getattr(cls, "_original_SysLogHandler", None),
        'handlers.WatchedFileHandler': getattr(cls, "_original_WatchedFileHandler", None),
        'handlers.RotatingFileHandler': getattr(cls, "_original_RotatingFileHandler", None),
        'handlers.QueueHandler': getattr(cls, "_original_QueueHandler", None),
    }

    # Restore each replacement if the original is available
    for key, original in replacements.items():
        if original is None:
            continue
        try:
            if '.' in key:
                module_name, attr_name = key.split('.', 1)
                module = getattr(logging, module_name)
                setattr(module, attr_name, original)
            else:
                setattr(logging, key, original)
        except Exception:
            # Ignore errors when restoring attributes
            pass

