        # If an error occurs, log it using the root logger
        root_logger = logging.getLogger()
        root_logger.error("Failed to reset logging: %s", exc)

def _getTargetClass(self):
    """
    Define this to return the implementation in use,
    without the 'Py' or 'Fallback' suffix.
    """
    # Determine the base class name by removing known suffixes.
    cls_name = self.__class__.__name__
    if cls_name.endswith('Py'):
        target_name = cls_name[:-2]
    elif cls_name.endswith('Fallback'):
        target_name = cls_name[:-8]
    else:
        target_name = cls_name

    # Import the module containing the current class and retrieve the target class.
    module_name = self.__class__.__module__
    try:
        module = __import__(module_name, fromlist=[target_name])
        target_cls = getattr(module, target_name)
    except (ImportError, AttributeError) as exc:
        raise AttributeError(
            f"Target class '{target_name}' not found in module '{module_name}'"
        ) from exc
    return target_cls

