        # Fallback: use the ``__provides__`` attribute if present
        provides = getattr(object, "__provides__", None)
        if provides is not None:
            return provides
        # For classes, inspect ``__mro__`` for ``__provides__`` on base classes
        obj_type = type(object)
        for base in obj_type.__mro__:
            provides = getattr(base, "__provides__", None)
            if provides is not None:
                return provides
        # If nothing is found, return an empty tuple as a safe default
        return ()

def directlyProvidedBy(object):  # pylint:disable=redefined-builtin
    """Return the interfaces directly provided by the given object

    The value returned is an `~zope.interface.interfaces.IDeclaration`.
    """
    try:
        provides = getattr(object, "__provides__", None)
        if callable(provides):
            result = provides()
        else:
            result = provides
        if result is None:
            return ()
        # Ensure the return is a tuple of interfaces (empty if none)
        return tuple(result)
    except Exception:
        # In case of any failure (attribute missing, call error, etc.)
        return ()

def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    try:
        classes_list = list(classes)
    except TypeError as exc:
        raise TypeError("classes must be an iterable of classes") from exc

    result = []
    seen = set()
    for cls in classes_list:
        if not isinstance(cls, type):
            raise TypeError(f"invalid base class {cls!r}")
        if cls in seen:
            continue

        # Determine if cls is a superclass of any other class in the list
        is_superclass = False
        for other in classes_list:
            if other is cls:
                continue
            try:
                if issubclass(other, cls):
                    is_superclass = True
                    break
            except Exception:
                # If issubclass fails for some reason, ignore that candidate
                continue

        if not is_superclass:
            result.append(cls)
            seen.add(cls)

    return result

def namesAndDescriptions(self, all=False):
    """Return attribute names and descriptions defined by interface.

    Returns:
        list[tuple[str, str]]: A list of (name, description) tuples sorted
        alphabetically by name.  Hidden attributes (starting with an
        underscore) are excluded unless ``all`` is True.  Callable
        attributes are not included.
    """
    result = []

    cls = self.__class__

    # Inspect attributes defined in the class dictionary
    for name, val in vars(cls).items():
        if not all and name.startswith("_"):
            continue
        if callable(val):
            continue

        # Retrieve description
        desc = ""
        if hasattr(val, "description") and isinstance(val.description, str):
            desc = val.description
        elif isinstance(val, property):
            desc = val.fget.__doc__ or ""
        elif hasattr(val, "__doc__") and isinstance(val.__doc__, str):
            desc = val.__doc__

        result.append((name, desc.strip()))

    # Add descriptors defined via __slots__ that may not appear in vars()
    for slot in getattr(cls, "__slots__", []):
        if not all and slot.startswith("_"):
            continue
        if hasattr(cls, slot):
            val = getattr(cls, slot)
            if callable(val):
                continue

            desc = ""
            if hasattr(val, "description") and isinstance(val.description, str):
                desc = val.description
            elif isinstance(val, property):
                desc = val.fget.__doc__ or ""
            elif hasattr(val, "__doc__") and isinstance(val.__doc__, str):
                desc = val.__doc__

            result.append((slot, desc.strip()))

    # Remove duplicates that may arise from slots also being defined in vars()
    seen = set()
    unique_result = []
    for name, desc in result:
        if name not in seen:
            seen.add(name)
            unique_result.append((name, desc))

    unique_result.sort(key=lambda x: x[0])
    return unique_result

def namesAndDescriptions(self, all=False):  # pylint:disable=redefined-builtin
    """Return attribute names and descriptions defined by interface."""
    # collect results in a dict to avoid duplicates
    results = {}
    # if 'all' is True, include attributes from the entire class hierarchy
    classes = [self.__class__] if not all else list(self.__class__.__mro__)[:-1]  # exclude object itself
    for cls in classes:
        for name, value in cls.__dict__.items():
            # skip private and special attributes
            if name.startswith('_'):
                continue
            # skip methods or callables
            if callable(value):
                continue
            # get a human‑readable description; fall back to empty string
            desc = getattr(value, '__doc__', '')
            if desc is None:
                desc = ''
            results[name] = desc
    # also consider attributes set on the instance itself
    for name, value in getattr(self, '__dict__', {}).items():
        if name.startswith('_'):
            continue
        if callable(value):
            continue
        desc = getattr(value, '__doc__', '')
        if desc is None:
            desc = ''
        results[name] = desc
    return results

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean")

    seen = set()
    attribute_names = []

    for cls in self.__class__.__mro__:
        for name, value in cls.__dict__.items():
            if name in seen:
                continue
            seen.add(name)

            if not all and name.startswith('_'):
                continue
            if callable(value):
                continue
            attribute_names.append(name)

    attribute_names.sort()
    return attribute_names

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError('The "all" parameter must be a boolean.')

    names = set()

    # Instance attributes (fallback if __dict__ not available)
    try:
        names.update(self.__dict__.keys())
    except AttributeError:
        pass

    # Class attributes that are not callables
    for name, value in vars(self.__class__).items():
        if callable(value):
            continue
        names.add(name)

    # Annotations provide attribute names in dataclass-like classes
    annotations = getattr(self.__class__, "__annotations__", None)
    if annotations:
        names.update(annotations.keys())

    # __slots__ may define attributes without a __dict__
    slots = getattr(self.__class__, "__slots__", None)
    if slots:
        if isinstance(slots, str):
            names.add(slots)
        else:
            names.update(slots)

    # Filter out private/dunder names when all is False
    if not all:
        names = {
            n for n in names
            if not (n.startswith("_") or (n.startswith("__") and n.endswith("__")))
        }

    return sorted(names)

def names(self, all=False):
    """Return the attribute names defined by the interface."""
    if not isinstance(all, bool):
        raise TypeError("'all' must be a boolean value.")
    try:
        if all:
            return [name for name in dir(self) if not name.startswith('_')]
        return [name for name in self.__dict__ if not name.startswith('_')]
    except Exception:
        return []

def names(self, all=False):  # pylint:disable=redefined-builtin
    """Return the attribute names defined by the interface."""
    # Collect names defined directly on the class
    direct_names = [name for name in vars(self.__class__) if not name.startswith("_")]
    if all:
        # Include names from the entire MRO chain and instance attributes
        mro_names = set(direct_names)
        for cls in self.__class__.__mro__[1:]:
            mro_names.update(name for name in vars(cls) if not name.startswith("_"))
        instance_names = set(name for name in vars(self) if not name.startswith("_"))
        all_names = mro_names.union(instance_names)
        return sorted(all_names)
    return sorted(direct_names)

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    if Broken in getattr(sequence, '__bases__', ()):
        return [sequence]

    cls = sequence.__class__
    if InterfaceClass in cls.__mro__ or zope.interface.declarations.Implements in cls.__mro__:
        output.append(sequence)
    else:
        for v in sequence:
