def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # The function accepts a single argument or a sequence of arguments.
    # We treat strings and bytes as atomic entities, while all other
    # iterable objects are considered containers and are expanded.
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
    elif hasattr(sequence, '__iter__') and not isinstance(sequence, (bytes, bytearray)):
        # Iterate over the container and recursively normalize each item.
        try:
            for item in sequence:
                _normalizeargs(item, output)
        except Exception:
            # In case the object is not truly iterable, use it as a single item.
            output.append(sequence)
    else:
        output.append(sequence)

    return output

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    # If sequence is None or empty, nothing to add
    if sequence is None:
        return output

    # Treat strings/bytes as single items, not iterable containers
    if isinstance(sequence, (str, bytes)):
        output.append(sequence)
        return output

    # If the sequence is iterable (list, tuple, set, etc.), iterate over its elements
    try:
        iterator = iter(sequence)
    except TypeError:
        # Not iterable (likely a single declaration/interface)
        output.append(sequence)
    else:
        # Iterate and recursively normalize each element
        for element in iterator:
            _normalizeargs(element, output)

    return output

def _should_attempt_c_optimizations():
    """
    Return a true value if we should attempt to use the C optimizations.

    This takes into account whether we're on PyPy and the value of the
    ``PURE_PYTHON`` environment variable, as defined in `_use_c_impl`.
    """
    import sys
    # On PyPy we skip C optimizations to avoid compatibility issues.
    try:
        if sys.implementation.name.lower().startswith("pypy"):
            return False
    except Exception:
        # If we cannot determine the implementation we simply proceed.
        pass

    # Delegate the decision about PURE_PYTHON handling to _use_c_impl.
    try:
        return _use_c_impl()
    except

def _c_optimizations_ignored():
    """
    The opposite of `_c_optimizations_required`.
    """
    try:
        return not _c_optimizations_required()
    except Exception:
        return False

def _c_optimizations_ignored():
    """The opposite of `_c_optimizations_required`."""
    try:
        # If `_c_optimizations_required` exists, return its logical negation.
        return not _c_optimizations_required()
    except Exception as exc:
        # In case the required function is missing or raises, raise a clear error.
        raise RuntimeError("Cannot determine optimizations status; required function missing or failed.") from exc

def _c_optimizations_ignored(self):
    """
    The opposite of `_c_optimizations_required`.
    """
    # Determine the required status. It may be a method or a boolean attribute.
    try:
        required = self._c_optimizations_required()
    except TypeError:
        # Treat it as a boolean attribute if callable access fails
        required = getattr(self, "_c_optimizations_required", False)
    # Return the logical opposite, ensuring a boolean result.
    return not bool(required)

def _c_optimizations_required():
    """
    Return a true value if the C optimizations are required.

    This uses the ``PURE_PYTHON`` variable as documented in `_use_c_impl`.
    """
    try:
        return not PURE_PYTHON
    except NameError:
        # If PURE_PYTHON is not defined, default to requiring C optimizations
        return True

