def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the stored context
    self.context = {}

    # Reinitialize the histogram bins
    # Use the existing initial_value if defined, otherwise generate new bins
    try:
        if hasattr(self, "initial_value") and self.initial_value is not None:
            # Ensure that we do not keep a reference to a mutable default
            self.bins = self.initial_value
        else:
            # Fallback to factory method, if available
            if hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # If no method is available, simply set bins to an empty list
                self.bins = []
    except Exception as exc:
        raise RuntimeError(f"Failed to reset histogram bins: {exc}") from exc

    # Optionally reset any aggregate counters or metadata if present
    if hasattr(self, "total_count"):
        self.total_count = 0
    if hasattr(self, "min_value"):
        self.min_value = None
    if hasattr(self, "max_value"):
        self.max_value = None
    # No explicit return value needed; mutation of the instance state is sufficient.

def reset(self):
        """Reset the histogram.

        Current context is reset to an empty dict.
        Bins are reinitialized with the *initial_value*
        or with *make_bins()* (depending on the initialization).
        """
        # Reset context
        try:
            self.context = {}
        except AttributeError:
            # If context attribute does not exist, ignore silently
            pass

        # Reinitialize bins
        try:
            # If an initial value has been provided, use it to reset bins
            if hasattr(self, "initial_value") and self.initial_value is not None:
                # If bins already exist, preserve their length
                if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                    self.bins = [self.initial_value for _ in range(len(self.bins))]
                else:
                    # Fallback: create an empty list or a list of a default length
                    self.bins = []
            # If no initial_value but a make_bins method exists, use it
            elif hasattr(self, "make_bins") and callable(self.make_bins):
                self.bins = self.make_bins()
            else:
                # Final fallback: keep bins unchanged or clear them if possible
                if hasattr(self, "bins") and isinstance(self.bins, (list, tuple)):
                    self.bins = [0 for _ in range(len(self.bins))]
                else:
                    self.bins = []
        except Exception:
            # If something goes wrong during bin reinitialization, keep the existing state
            pass

