    if hasattr(self, 'context'):
        # In case context could be any mapping
        try:
            self.context.clear()
        except AttributeError:
            # If clear method not present, reassign to new dict
            self.context = {}
    else:
        self.context = {}

    # Determine the desired bin contents
    # Store the previous number of bins if present
    old_length = len(self.bins) if hasattr(self, 'bins') else 0

    if hasattr(self, 'make_bins') and callable(self.make_bins):
        try:
            self.bins = self.make_bins()
        except Exception:
            # Fallback: keep current or empty
            self.bins = [None] * old_length
    elif hasattr(self, 'initial_value'):
        # Reinitialize all bins to the initial value
        self.bins = [self.initial_value] * old_length
    else:
        # No method to reinitialize, set to empty list
        self.bins = []

    # Optional: reset common histogram attributes if present
    for attr in ('count', 'total', 'min', 'max'):
        if hasattr(self, attr):
            try:
                setattr(self, attr, 0 if attr in ('count', 'total') else None)
            except Exception:
                pass

def reset(self):
    """Reset the histogram.

    Current context is reset to an empty dict.
    Bins are reinitialized with the *initial_value*
    or with *make_bins()* (depending on the initialization).
    """
    # Reset the histogram context
    if hasattr(self, "context"):
        self.context = {}
    else:
        # Create context attribute if it doesn't exist
        self.context = {}

    # Reinitialize the bins
    # If the histogram provides a make_bins method, use that to create fresh bins
    if hasattr(self, "make_bins") and callable(self.make_bins):
        try:
            self.bins = self.make_bins()
        except Exception:
            # If make_bins fails, fall back to an empty list so the state is consistent
            self.bins = []
    else:
        # If no make_bins, try to use an initial_value if available
        if hasattr(self, "initial_value"):
            try:
                # Preserve the current bin count if bins already exist, otherwise create a single bin
                bin_count = len(self.bins) if hasattr(self, "bins") and hasattr(self.bins, "__len__") else 1
                self.bins = [self.initial_value] * bin_count
            except Exception:
                # In any error case, fallback to a single bin with the initial value
                self.bins = [self.initial_value]
        else:
            # If neither make_bins nor initial_value are defined, simply clear bins
            self.bins = []

    # Reset any related counters or timestamps that the histogram tracks
    for attr in ("total_count", "min_value", "max_value", "start_time_stamp_msec", "end_time_stamp_msec"):
        if hasattr(self, attr):
            try:
                if attr in ("total_count", "max_value", "end_time_stamp_msec"):
                    setattr(self, attr, 0)
                elif attr == "min_value":
                    setattr(self, attr, sys.maxsize)  # Ensure sys is imported if used
                elif attr == "start_time_stamp_msec":
                    setattr(self, attr, sys.maxsize)
            except Exception:
                # Silently ignore any attribute get/set errors
                pass

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.
    """
    lines = []
    if header is not None:
        lines.append(str(header))
    try:
        for point, value in self:
            # Convert point coordinates to string
            if isinstance(point, (list, tuple)):
                coord_str = separator.join(str(p) for p in point)
            else:
                coord_str = str(point)
            # Convert value parts to string
            if isinstance(value, (list, tuple)):
                value_str = separator.join(str(v) for v in value)
            else:
                value_str = str(value)
            line = separator.join([coord_str, value_str])
            lines.append(line)
    except Exception:
        # If the graph is not iterable in (point, value) form, try to iterate over
        # points only and treat values as None.
        for point in self:
            if isinstance(point, (list, tuple)):
                coord_str = separator.join(str(p) for p in point)
            else:
                coord_str = str(point)
            lines.append(coord_str)
    return "\n".join(lines) + ("\n" if lines else "")

def to_csv(self, separator=",", header=None):
    """.. deprecated:: 0.5 in Lena 0.5 to_csv is not used.
          Iterables are converted to tables.

    Convert graph's points to CSV.

    *separator* delimits values, the default is comma.

    *header*, if not ``None``, is the first string of the output
    (new line is added automatically).

    Since a graph can be multidimensional,
    for each point first its coordinate is converted to string
    (separated by *separator*), then each part of its value.

    To convert :class:`Graph` to CSV inside a Lena sequence,
    use :class:`lena.output.ToCSV`.
    """
    # Prepare output lines
    lines = []

    # Add header if requested
    if header is not None:
        # Ensure that the header is a single line string
        if isinstance(header, (list, tuple)):
            header = separator.join(map(str, header))
        lines.append(str(header))

    # Ensure the graph is iterable
    try:
        iterator = iter(self)
    except TypeError:
        raise TypeError("The graph object is not iterable, cannot convert to CSV")

    for point in iterator:
        # Expecting a point as (coordinates, value) or a single value
        if isinstance(point, tuple) and len(point) == 2:
            coords, value = point
        else:
            # If the point is not a tuple of length 2, treat whole point as value
            coords = ()
            value = point

        # Convert coordinate part
        try:
            coord_iter = iter(coords)
        except TypeError:
            # If coordinates is not iterable, treat as a single coordinate
            coord_iter = (coords,) if coords != () else ()

        coord_str = separator.join(str(c) for c in coord_iter)

        # Convert value part
        try:
            value_iter = iter(value)
            # Avoid treating strings as iterable of chars
            if isinstance(value, str):
                value_iter = None
        except TypeError:
            value_iter = None

        if value_iter is not None:
            value_str = separator.join(str(v) for v in value_iter)
        else:
            value_str = str(value) if value is not None else ""

        # Join coordinate and value parts
        if coord_str and value_str:
            line = f"{coord_str}{separator}{value_str}"
        elif coord_str:
            line = coord_str
        else:
            line = value_str

        lines.append(line)

    return "\n".join(lines)

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    if not isinstance(coord_name, str):
        raise TypeError("coord_name must be a string")
    # The class should hold an error index mapping in an attribute
    # named `_error_indices`.  If it is absent, we assume no errors.
    error_mapping = getattr(self, "_error_indices", None)
    if not isinstance(error_mapping, dict):
        return []
    indices = error_mapping.get(coord_name)
    if indices is None:
        # No indices recorded for this coordinate
        return []
    # Accept any iterable of indices and normalise to a list
    try:
        return list(indices)
    except TypeError:
        # Not iterable; return single-element list for safety
        return [indices]

def _get_err_indices(self, coord_name):
    """Get error indices corresponding to a coordinate."""
    # Retrieve error array/dict for the coordinate if it exists
    error_array = None
    # Common attribute names that might store coordinate errors
    attr_candidates = ["errors", "_errors", "error_map", "coord_errors", "_coord_errors"]
    for attr in attr_candidates:
        if hasattr(self, attr) and isinstance(getattr(self, attr), (dict, dict)):
            if coord_name in getattr(self, attr):
                error_array = getattr(self, attr)[coord_name]
                break
    # If still not found, try to look for attribute directly on the object
    if error_array is None and hasattr(self, coord_name + "_error"):
        error_array = getattr(self, coord_name + "_error")

    # If no error information, return empty list
    if error_array is None:
        return []

    # Convert to a NumPy array, handling possible DataArray or other iterable
    try:
        if hasattr(error_array, "values"):
            arr = np.array(error_array.values)
        else:
            arr = np.array(error_array)
    except Exception:
        return []

    # If the array is empty, nothing to return
    if arr.size == 0:
        return []

    # If boolean mask, return indices where True
    if arr.dtype == bool:
        indices = np.where(arr)[0]
