    if err_obj is None and hasattr(self, "errors") and isinstance(self.errors, dict):
        err_obj = self.errors.get(coord_name)
    # 3. If the instance itself is a mapping (e.g., a dataframe or dict)
    if err_obj is None and isinstance(self, dict) and coord_name in self:
        err_obj = self[coord_name]
    # 4. Try to find the coordinate in `self.Data` (common in data‑handling libraries)
    if err_obj is None and hasattr(self, "Data") and isinstance(self.Data, dict):
        if isinstance(self.Data.get(coord_name), dict):
            err_obj = self.Data[coord_name].get("err") or self.Data[coord_name].get("error")
        else:
