    try:
        import numpy as _np
        arr = _np.asarray(err_obj)
        # Use NumPy to find indices of finite error values
        valid_mask = ~_np.isnan(arr)
        indices = _np.nonzero(valid_mask)[0]
    except Exception:
        # Pure Python fallback
        try:
            arr = list(err_obj)
        except Exception as exc:
            raise TypeError(f"Cannot interpret error data for '{coord_name}' as a sequence") from exc
        indices = []
        for i, val in enumerate(arr):
            # handle float types and non‑float contexts
            try:
                if not (isinstance(val, float) and (val != val)):  # NaN check
                    indices.append(i)
            except Exception:
                # If value cannot be compared, assume valid
                indices.append(i)
    # Return a Python list of integer indices
    return list(indices)

