                coord_name = name.lower()
            else:
                coord_name = name
            context["error"].setdefault(coord_name, {})
            context["error"][coord_name]["index"] = idx

    # --------- Merge remaining graph properties into context['value'] ----
    # Prefer a dedicated properties mapping if available
    prop_mapping = {}
    if hasattr(self, "_properties") and isinstance(getattr(self, "_properties"), dict):
        prop_mapping = getattr(self, "_properties")
    else:
        # Fallback to public attributes
        prop_mapping = {k: v for k, v in getattr(self, "__dict__", {}).items()
                         if not k.startswith("_")}

    if prop_mapping:
        context.setdefault("value", {})
        context["value"].update(prop_mapping)

    # --------- Optional: Handle coordinate fields 'x', 'y', 'z' ----------
    # Map first three coordinates from the graph if present
    coord_fields = ["x", "y", "z"]
