    in :class:`.ToCSV`). By destruction we mean conversion
    to another structure (like text) in the flow.
    The graph object is not really destroyed in this process.
    """
    # Determine number of rows in the graph (used as index for errors)
    try:
        # If the graph stores data in a DataFrame or similar with a length
        row_count = len(self.data)
    except Exception:
        try:
            row_count = len(self)
        except Exception:
            row_count = 0

    # Retrieve the current error mapping from the context
    if hasattr(context, "error"):
        error_map = context.error
    else:
        error_map = context.get("error", {})

    # Find error columns in the graph's data
    # Assume the graph has an attribute 'data' that is mapping or DataFrame
    cols = []
    if hasattr(self, "data"):
        try:
            if isinstance(self.data, dict):
                cols = list(self.data.keys())
            else:
                # Pandas-like object
                cols = getattr(self.data, "columns", [])
            if not isinstance(cols, (list, tuple)):
                cols = list(cols)
        except Exception:
            cols = []

    # Helper to map a coordinate symbol to 'x', 'y', or 'z'
    def coord_from_sym(symbol):
        s = symbol[0].lower()
        if s == "x":
            return "x"
        if s == "t" or s == "y":
            return "y"
        return "z"

    # Append error information
    for col in cols:
        if isinstance(col, str) and col.startswith("error_"):
            suffix = col[len("error_") :]
            parts = suffix.split("_", 1)
            coord_sym = parts[0]
            rest = parts[1] if len(parts) > 1 else ""

            coord = coord_from_sym(coord_sym)
            key = f"{coord}_{rest}" if rest else coord

            error_map[key] = {"index": row_count - 1}

    # Store the updated error map back into the context
    if hasattr(context, "error"):
        context.error = error_map
    else:
        context["error"] = error_map
    # No return value; context mutated in place.

def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    import numpy as np

    # Convert inputs to numpy arrays for reliable operations
    bins_arr = np.asarray(bins)

    # Determine whether edges is a sequence of 1‑D arrays or a single 1‑D array
    if isinstance(edges, (list, tuple)):
        # Sequence of arrays – multi‑dimensional histogram
        widths = []
        for e in edges:
            e_arr = np.asarray(e)
            if e_arr.ndim != 1:
                raise ValueError("Each element of 'edges' must be a 1‑D array.")
            if e_arr.size < 2:
                raise ValueError("Each edge array must contain at least two points.")
            widths.append(np.diff(e_arr))

        if not widths:
            raise ValueError("'edges' sequence is empty.")

        # Compute the volume (product of widths) for each histogram bin
        vol = widths[0]
        for w in widths[1:]:
            vol = np.multiply.outer(vol, w)

        # Verify the shapes are compatible
        if vol.shape != bins_arr.shape:
            # Try broadcasting – this will either succeed or raise a ValueError later
            try:
                vol = np.broadcast_to(vol, bins_arr.shape)
            except ValueError:
                raise ValueError("Shape mismatch: product of edge widths must match shape of 'bins'.")

        return float(np.sum(bins_arr * vol))

    else:
        # Single array – 1‑D histogram
        e_arr = np.asarray(edges)
        if e_arr.ndim != 1:
            raise ValueError("'edges' must be a 1‑D array or a sequence of 1‑D arrays.")
        if e_arr.size < 2:
            raise ValueError("'edges' must contain at least two points.")
        width = np.diff(e_arr)

        if width.size != bins_arr.size:
            # Try broadcasting
            try:
                width = np.broadcast_to(width, bins_arr.shape)
            except ValueError:
                raise ValueError("Shape mismatch: length of edge differences must match size of 'bins'.")

        return float(np.sum(bins_arr * width))

