            raise ValueError(f"Edges must be strictly increasing, got width {w} at index {i}")
        widths.append(w)

    # Compute integral as sum of bin value times width
    integral_val = 0.0
    for b, w in zip(bins, widths):
        try:
            integral_val += float(b) * float(w)
        except TypeError:
            raise TypeError(f"Bin value must be numeric: {b}")

    return integral_val

