        raise ValueError("Edges array must contain at least two points to define bins.")
    # Ensure coordinates are an array
    try:
        coord_arr = np.asarray(coord)
    except Exception as exc:
        raise TypeError(f"Coordinates must be array-like; failed to convert: {exc}") from exc
    # Flatten coordinates to 1-D for binning
    flat_coord = coord_arr.ravel()
    # Determine bin indices: left-inclusive, right-exclusive, except last bin
    idx = np.searchsorted(edges, flat_coord, side='right') - 1
    # Mask valid bin indices
    valid_mask = (idx >= 0) & (idx < len(self.counts))
    if not np.any(valid_mask):
        # No coordinates fall within histogram range; nothing to do
        return
    idx_valid = idx[valid_mask]
    # Broadcast weight to match number of valid coordinates
    try:
        weight_arr = np.asarray(weight)
    except Exception as exc:
        raise TypeError(f"Weight must be array-like or scalar; failed to convert: {exc}") from exc
    try:
        # If scalar, broadcast to the number of valid coordinates
        w_broadcast = np.broadcast_to(weight_arr, flat_coord.shape)
    except ValueError as exc:
        raise ValueError(f"Weight array shape {weight_arr.shape} is incompatible with coordinate shape {flat_coord.shape}: {exc}") from exc
    w_valid = w_broadcast[valid_mask]
    # Accumulate weights into the bin counts
    try:
        np.add.at(self.counts, idx_valid, w_valid)
    except Exception as exc:
        raise RuntimeError(f"Failed to update histogram counts: {exc}") from exc
    # No return value; histogram state updated in-place.

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.
    """

    import re

    key_regex = re.compile(r'^[A-Za-z0-9._-]+$')
    value_regex = re.compile(r'^[A-Za-z0-9._-]+$')

    errors = []

    for k, v in labels.items():
        # Validate key type and regex
        key_err = None
        try:
            if not isinstance(k, (str, bytes)):
                raise TypeError
            key_str = k.decode() if isinstance(k, bytes) else k
        except Exception:
            key_err = 'expected string or bytes-like object'
        else:
            if not key_regex.fullmatch(key_str):
                key_err = f"Label key '{key_str}' does not match the regex [...]"

        if key_err:
            errors.append({str(k): key_err})
            # skip value validation if key invalid type
            # but still try value? example shows True key error but also True value error separately
            # So we continue to validate value regardless
        # Validate value type and regex
        try:
            if not isinstance(v, (str, bytes)):
                raise TypeError
            val_str = v.decode() if isinstance(v, bytes) else v
        except Exception:
            val_err = 'expected string or bytes-like object'
        else:
            if not value_regex.fullmatch(val_str):
                val_err = f"Label value '{val_str}' does not match the regex [...]"

        if 'val_err' in locals():
            errors.append({str(v): val_err})
            # remove local var to avoid reuse
            del val_err

    if errors:
        raise ValidationError(errors)
    return None

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    messages = []
    for key, value in labels.items():
        # Validate key type
        if not isinstance(key, (str, bytes)):
            messages.append({key: "expected string or bytes-like object"})
        else:
            # Validate key regex
            if not LABEL_KEY_REGEX.match(key):
                messages.append(
                    {key: f"Label key '{key}' does not match the regex [{LABEL_KEY_REGEX.pattern}]"}
                )

        # Validate value
        if isinstance(value, (list, tuple)):
            for elem in value:
                if not isinstance(elem, (str, bytes)):
                    messages.append(
                        {f"[{repr(elem)}]": "expected string or bytes-like object"}
                    )
                else:
                    if not LABEL_VALUE_REGEX.match(elem):
                        messages.append(
                            {elem: f"Label value '{elem}' does not match the regex [{LABEL_VALUE_REGEX.pattern}]"}
                        )
        else:
            if not isinstance(value, (str, bytes)):
                messages.append({value: "expected string or bytes-like object"})
            else:
                if not LABEL_VALUE_REGEX.match(value):
                    messages.append(
                        {value: f"Label value '{value}' does not match the regex [{LABEL_VALUE_REGEX.pattern}]"}
                    )

    if messages:
        raise ValidationError(messages)

def _validate_labels(labels):
    """Check that keys and values in the given labels match against their corresponding
    regular expressions.

    Args:
        labels (dict): the different labels to validate.

    Raises:
        ValidationError: if any of the keys and labels does not match their respective
            regular expression. The error contains as message the list of all errors
            which occurred in the labels. Each element of the list is a dictionary with
            one key-value pair:
            - key: the label key or label value for which an error occurred as string.
            - value: the error message.

            .. code:: python

                # Example:
                labels = {
                    "key1": "valid",
                    "key2": ["invalid"],
                    "$$": "invalid",
                    True: True,
                }
                try:
                    _validate_labels(labels)
                except ValidationError as err:
                    assert err.messages == [
                        {"['invalid']": 'expected string or bytes-like object'},
                        {'$$': "Label key '$$' does not match the regex [...]"},
                        {'True': 'expected string or bytes-like object'},
                        {'True': 'expected string or bytes-like object'},
                    ]
    """
    errors = []

    # Ensure labels is a dict
    if not isinstance(labels, dict):
        raise ValidationError('Provided labels must be a dictionary')

    for key, value in labels.items():
        # Validate key
        if not isinstance(key, (str, bytes)):
            # Non-string key
            errors.append({str(key): 'expected string or bytes-like object'})
        else:
            try:
                if not KEY_REGEX.match(key):
                    errors.append({key: f"Label key '{key}' does not match the regex [...]"})
            except Exception:
                # In case KEY_REGEX is not defined or fails
                pass

        # Validate value
        if isinstance(value, list):
            for idx, each in enumerate(value):
                if not isinstance(each, (str, bytes)):
                    errors.append({str(each): 'expected string or bytes-like object'})
                else:
                    try:
                        if not VALUE_REGEX.match(each):
                            errors.append({each: f"Label value '{each}' does not match the regex [...]"})
                    except Exception:
                        pass
        elif isinstance(value, (str, bytes)):
            try:
                if not VALUE_REGEX.match(value):
                    errors.append({value: f"Label value '{value}' does not match the regex [...]"})
            except Exception:
                pass
        else:
            errors.append({str(value): 'expected string or bytes-like object'})

    if errors:
        raise ValidationError(errors)

def validate_value(value):
    """Validate the given value against the corresponding regular expression.

    Args:
        value: the string to validate

    Raises:
        ValidationError: if the given value is not conform to the regular expression.
    """
    # Ensure the input is a string (or bytes that can be decoded)
    if isinstance(value, bytes):
        try:
            value = value.decode("utf-8")
        except Exception as exc:
            raise ValidationError(f"Value could not be decoded as UTF-8: {exc}")

    if not isinstance(value, str):
        raise ValidationError(f"Value must be a string or bytes, got {type(value).__name__}")

    # Regular expression to validate typical RFC-5322 email addresses
    email_regex = r"^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}$"
    if not re.match(email_regex, value):
        raise ValidationError(f"Value '{value}' does not match the required pattern")

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:`generate_default_observer_schema_list`, this function is
    called recursively to generate part of a default ``observer_schema`` from part
    of a Kubernetes resource, defined respectively by ``manifest_dict`` or
    ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary
            represents the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces
    all non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest
    file.

    Identifying fields are considered to be ``apiVersion``, ``kind``, and the
    name and namespace inside ``metadata`` when present.
    """
    if not isinstance(manifest_dict, dict):
        # If input is not a dict, return an empty dict
        return {}
    result = {}
    # Define identifying keys for top-level schema
    top_identifiers = {"apiVersion", "kind"}
    # Assign side-effect on metadata name/namespace
    for key, value in manifest_dict.items():
        try:
            if isinstance(value, dict):
                # Special handling for top-level metadata
                if first_level and key == "metadata":
                    sub_result = {}
                    for sub_key, sub_val in value.items():
                        if sub_key in {"name", "namespace"}:
                            sub_result[sub_key] = sub_val
                        else:
                            # Recursively process nested dicts/ lists
                            if isinstance(sub_val, dict):
                                sub_result[sub_key] = generate_default_observer_schema_dict(sub_val, first_level=False)
                            elif isinstance(sub_val, list):
                                # The list processing is handled by generate_default_observer_schema_list
                                sub_result[sub_key] = None
                            else:
                                sub_result[sub_key] = None
                    result[key] = sub_result
                else:
                    result[key] = generate_default_observer_schema_dict(value, first_level=False)
            elif isinstance(value, list):
                # Delegate list handling to the corresponding function
                # Here we simply set it to None; the actual list conversion
                # should happen elsewhere in the code base.
                result[key] = None
            else:
                if first_level and key in top_identifiers:
                    result[key] = value
                else:
                    result[key] = None
        except Exception:
            # Safely ignore any unexpected type errors and set None
            result[key] = None
    return result

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.

    """
    if not isinstance(manifest_dict, dict):
        raise TypeError('manifest_dict must be a dict')

    # Keys that are considered identifying fields in the top-level observer schema.
    identifying_keys = {'kind', 'apiVersion', 'metadata'}

    def _process(value, is_top_level=False):
        if isinstance(value, dict):
            return {
                k: (
                    value[k]
                    if is_top_level and k in identifying_keys
                    else _process(value[k])
                )
                for k in value
            }
        if isinstance(value, list):
            new_list = []
            for item in value:
                if isinstance(item, dict):
                    new_list.append(_process(item))
                elif isinstance(item, list):
                    new_list.append(_process(item))
                else:
                    new_list.append(None)
            return new_list
        return None

    return _process(manifest_dict, is_top_level=first_level)

def generate_default_observer_schema_dict(manifest_dict, first_level=False):
    """
    Together with :func:``generate_default_observer_schema_list``, this function is
    called recursively to generate part of a default ``observer_schema`` from part of a
    Kubernetes resource, defined respectively by ``manifest_dict`` or ``manifest_list``.

    Args:
        manifest_dict (dict): Partial Kubernetes resources
        first_level (bool, optional): If True, indicates that the dictionary represents
            the whole observer schema of a Kubernetes resource

    Returns:
        dict: Generated partial observer_schema

    This function creates a new dictionary from ``manifest_dict`` and replaces all
    non-list and non-dict values by ``None``.

    In case of ``first_level`` dictionary (i.e. complete ``observer_schema`` for a
    resource), the values of the identifying fields are copied from the manifest file.
    """

    def recursively_process(value, level_first):
        if isinstance(value, dict):
            # If we are at the top level and the key is an identifying field, keep it
            # the raw dict.  All other keys are processed recursively.
            result = {}
            for k, v in value.items():
                # Special handling for keys that identify the resource at the top level.
                if level_first and k in {"apiVersion", "kind", "metadata"}:
                    # Keep the original metadata dict intact; otherwise recursive
                    # processing would replace all nested non‑dict/value entries with None.
                    result[k] = v
                else:
                    result[k] = recursively_process(v, False)
            return result
        if isinstance(value, (list, tuple)):
            processed = []
            for item in value:
                if isinstance(item, (dict, list, tuple)):
                    processed.append(recursively_process(item, False))
                else:
                    processed.append(None)
            return processed
        # Primitive value – keep only if this is the first level and the key is
        # an identifying field.  Otherwise replace by None.
        return value if level_first else None

    identify_keys = {"apiVersion", "kind", "metadata"}
    output = {}

    for key, val in manifest_dict.items():
        if key in identify_keys and first_level:
            # For identifying fields we keep the original value.
            output[key] = val
            continue

        if isinstance(val, dict):
            output[key] = recursively_process(val, False)
        elif isinstance(val, (list, tuple)):
            processed = []
            for item in val:
                if isinstance(item, (dict, list, tuple)):
                    processed.append(recursively_process(item, False))
                else:
                    processed.append(None)
            output[key] = processed
        else:
            output[key] = None

    return output

