def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    # Iterate over each observed field specified in the schema
    for key, schema_val in observer_schema.items():
        # Ensure the key exists in the response
        if key not in response:
            raise KeyError(f"Field {key!r} not found in response")

        # If the field is missing from the last applied manifest, initialise it
        if key not in last_applied_manifest:
            # For nested objects, create a new dict and recurse
            if isinstance(schema_val, dict):
                if not isinstance(response[key], dict):
                    raise KeyError(
                        f"Expected dict for field {key!r} but got {type(response[key])}"
                    )
                # initialise nested dict and recurse
                last_applied_manifest[key] = {}
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], schema_val, response[key]
                )
            else:
                # For scalars or lists, simply copy the value
                last_applied_manifest[key] = response[key]
        else:
            # Key already exists: ensure substructure is also initialised
            if isinstance(schema_val, dict) and isinstance(
                last_applied_manifest[key], dict
            ):
                if not isinstance(response[key], dict):
                    raise KeyError(
                        f"Expected dict for field {key!r} but got {type(response[key])}"
                    )
                update_last_applied_manifest_dict_from_resp(
                    last_applied_manifest[key], schema_val, response[key]
                )
    return last_applied_manifest

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function goes through all observed fields, and initializes their value in
    ``last_applied_manifest`` if they are not yet present.  Nested dictionaries
    are processed recursively.

    Returns:
        dict: The updated ``last_applied_manifest``.
    """
    if not isinstance(observer_schema, dict):
        raise ValueError("observer_schema must be a dict")
    if not isinstance(response, dict):
        raise ValueError("response must be a dict")
    if not isinstance(last_applied_manifest, dict):
        raise ValueError("last_applied_manifest must be a dict")

    for key, schema in observer_schema.items():
        # Ensure the key is present in the response
        if key not in response:
            raise KeyError(f"Field {key} missing from response")

        # schema may be a dict indicating nested structure, or any other
        if isinstance(schema, dict):
            # Nested dictionary
            if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
                # Initialize with empty dict if missing or not a dict
                last_applied_manifest[key] = {}
            if not isinstance(response[key], dict):
                raise KeyError(f"Expected dict for nested field {key} in response")
            # Recurse into nested
            update_last_applied_manifest_dict_from_resp(
                last_applied_manifest[key], schema, response[key]
            )
        else:
            # Leaf field – initialize only if not already present
            if key not in last_applied_manifest:
                last_applied_manifest[key] = response[key]

    return last_applied_manifest

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate that the application object has the expected attributes
    if not hasattr(app, "spec"):
        raise AttributeError("The provided application object lacks a 'spec' attribute.")
    if not hasattr(app.spec, "manifest"):
        raise AttributeError("The application's spec lacks a 'manifest' attribute.")

    manifest = app.spec.manifest

    # Ensure the manifest is an iterable of resources
    if not isinstance(manifest, (list, tuple)):
        raise TypeError("app.spec.manifest must be a list or tuple of resources.")

    for resource in manifest:
        # Skip non-dict items
        if not isinstance(resource, dict):
            continue

        # Skip resources that already have a custom observer schema defined
        if resource.get("observer_schema") is not None:
            continue

        # Construct a very simple default observer schema
        #  - Reflect the resource's kind and name
        #  - Assume the resource is considered ready when its status field is present
        default_schema = {
            "kind": resource.get("kind"),
            "metadata": {
                "name": resource.get("metadata", {}).get("name")
            },
            "status": {
                "ready": True
            }
        }

        # Attach the default schema to the resource
        resource["observer_schema"] = default_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate input
    if app is None:
        raise ValueError("The 'app' argument must not be None.")
    spec = getattr(app, "spec", None)
    if not hasattr(spec, "manifest"):
        raise AttributeError("The application spec must contain a 'manifest' attribute.")
    manifest = spec.manifest
    if not isinstance(manifest, dict):
        raise TypeError("`app.spec.manifest` must be a dictionary.")

    # Ensure observer_schema dict exists
    observer_schema = getattr(spec, "observer_schema", None)
    if observer_schema is None:
        observer_schema = {}
        setattr(spec, "observer_schema", observer_schema)
    elif not isinstance(observer_schema, dict):
        raise TypeError("`app.spec.observer_schema` must be a dictionary if it exists.")

    # Build default schema for each resource that lacks a custom one
    for key, resource in manifest.items():
        # Skip if a custom observer schema is already defined
        if key in observer_schema and observer_schema[key]:
            continue
        # Basic default schema: enable the observer for this resource
        default_schema = {"enabled": True}
        # Optionally copy some identifying fields from the resource definition
        if isinstance(resource, dict):
            kind = resource.get("kind")
            api_version = resource.get("apiVersion")
            if kind:
                default_schema["kind"] = kind
            if api_version:
                default_schema["apiVersion"] = api_version
        observer_schema[key] = default_schema

    # Return the updated observer_schema for convenience
    return observer_schema

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    default_schemas = {}
    try:
        # Try to retrieve the list of Kubernetes resource manifests
        spec = getattr(app, 'spec', None)
        if spec is None:
            return default_schemas

        # The manifest can be a list or a dict containing a list under 'items'
        manifest_items = None
        if isinstance(spec, dict):
            # Look for a direct list under 'manifest' key
            if 'manifest' in spec and isinstance(spec['manifest'], list):
                manifest_items = spec['manifest']
            # Look for 'items' key which may contain the resources
            elif 'items' in spec and isinstance(spec['items'], list):
                manifest_items = spec['items']
        elif isinstance(spec, list):
            manifest_items = spec

        if not manifest_items:
            return default_schemas

        # Retrieve any user‑defined observer schemas so we can skip those resources
        custom_schema_map = {}
        if hasattr(app, 'custom_observer_schemas'):
            custom_schema_map = getattr(app, 'custom_observer_schemas', {})
        elif hasattr(app, 'observer_schema'):
            custom_schema_map = getattr(app, 'observer_schema', {})

        for resource in manifest_items:
            if not isinstance(resource, dict):
                continue
            kind = resource.get('kind')
            if not kind:
                continue

            # Skip if a custom schema exists for this kind
            if kind in custom_schema_map:
                continue

            # Build a very simple default schema that only observes the top‑level
            # status field of the resource.  This can be refined later as needed.
            default_schema = {
                "type": "object",
                "properties": {
                    "status": {"type": "object"}
                },
                "required": ["status"]
            }
            # Use a composite key if the application might contain multiple resources
            # of the same kind.  The key convention is <kind>_<name> if a name exists,
            # otherwise just <kind>.
            name = resource.get('metadata', {}).get('name')
            key = f"{kind}_{name}" if name else kind

            default_schemas[key] = default_schema
    except Exception:
        # In case of any unexpected error (e.g. attributes missing), quietly
        # return the schemas collected so far.  Logging should be done by the caller
        # if needed.
        pass
    return default_schemas

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema

    Returns:
        dict: A dictionary mapping each resource identifier to its default observer schema.
              The identifier is constructed as ``<kind>/<namespace>/<name>``.  Resources
              that already have a custom observer schema specified in ``app.spec.observer_schema``
              are omitted.
    """
    if app is None:
        raise ValueError("app must not be None")

    try:
        # The manifest may be a single resource dict or a list/tuple of resources
        manifest = getattr(getattr(app, "spec", None), "manifest", None)
    except AttributeError:
        raise ValueError("app does not have a spec.manifest attribute")

    if not manifest:
        return {}

    # Normalize the manifest to an iterable of resources
    if isinstance(manifest, (list, tuple)):
        resources = manifest
    else:
        # Treat a single dict as a single resource
        resources = [manifest]

    # Grab existing observer schema mapping if present
    try:
        custom_schema = getattr(getattr(app, "spec", None), "observer_schema", {})
        if custom_schema is None:
            custom_schema = {}
    except AttributeError:
        custom_schema = {}

    defaults = {}
    for resource in resources:
        if not isinstance(resource, dict):
            # Skip non‑dict entries
            continue
        kind = resource.get("kind")
        if not kind:
            continue
        metadata = resource.get("metadata", {})
        name = metadata.get("name", "unknown")
        namespace = metadata.get("namespace", "default")
        key = f"{kind}/{namespace}/{name}"

        # Skip resources that already have custom schema
        if key in custom_schema:
            continue

        # Default observer schema: an empty object schema
        defaults[key] = {"type": "object", "properties": {}}

    return defaults

