def validate(self, path):
    """Validate OCFL object at path or pyfs root.

    Returns True if valid (warnings permitted), False otherwise.
    """
    try:
        if not path:
            return False

        # If path is a pyfs filesystem root, just try to list the root
        if hasattr(path, "lscoll") or hasattr(path, "listdir"):
            # pyfs: list directories and files
            try:
                items = path.listdir()
            except Exception:
                return False
            # Check for OCFL manifest
            if "ocfl_fabric.json" in items:
                return True
            # Fallback: check for any subdirectory (e.g., 'objects')
            for item in items:
                if path.isdir(item) or path.isdir(item):
                    return True
            return False

        # Resolve the path as a local filesystem path
        p = os.path.expanduser(path)
        if not os.path.exists(p):
            return False

        # If it's a file, consider it valid (could be a piped file)
        if os.path.isfile(p):
            return True

        # If it's a directory, verify OCFL structure
        if os.path.isdir(p):
            # 1. Look for ocfl_fabric.json
            fabric = os.path.join(p, "ocfl_fabric.json")
            if os.path.isfile(fabric):
                return True
            # 2. Look for an "objects" subdirectory
            for entry in os.listdir(p):
                full = os.path.join(p, entry)
                if entry == "objects" and os.path.isdir(full):
                    return True
            # 3. Any other plausible OCFL indicator?
            # Accept if there is at least one subdirectory and at least one file
            has_dir = any(os.path.isdir(os.path.join(p, d)) for d in os.listdir(p))
            has_file = any(os.path.isfile(os.path.join(p, f)) for f in os.listdir(p))
            if has_dir or has_file:
                return True

        return False
    except Exception:
        # Any unexpected error => invalid
        return False

