            except Exception as exc:
                raise ValueError(f"Invalid type for field '{field_name}': {exc}") from exc

    # If the inventory defines its own type that differs from the resolved spec_version,
    # raise a warning but continue with validation using the resolved version
    if extract_spec_version and inv_type not in getattr(self, 'supported_versions', []):
        # The spec_version was not recognized; we rely on the class's predefined spec_version
        if self.spec_version not in getattr(self, 'supported_versions', []):
