            iter(manifest_files)
            manifest_digests = list(manifest_files)
        except TypeError:
            raise TypeError("manifest_files must be a mapping or iterable of digests")

    # Ensure digests_used can be used for membership testing
    if isinstance(digests_used, (list, set, tuple)):
        used_set = set(digests_used)
    else:
        # Treat a single value as a one‑element set
        used_set = {digests_used}

