def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Normalise input types
    if manifest_files is None or digests_used is None:
        raise ValueError("Both manifest_files and digests_used must be provided")

    # Extract digests from the manifest.  The signature does not specify
    # the exact format, so we tolerate a few common representations:
    #   * a mapping of digest -> filename (digests are the keys)
    #   * a mapping of filename -> digest (digests are the values)
    #   * an iterable of digests (list/set/tuple)
    if isinstance(manifest_files, dict):
        # Detect whether the keys look like SHA‑256 digests (64 hex chars)
        def is_hex_digest(x):
            if not isinstance(x, str) or len(x) != 64:
                return False
            try:
                int(x, 16)
                return True
            except ValueError:
                return False

        if all(is_hex_digest(k) for k in manifest_files.keys()):
            digests_in_manifest = {k.lower() for k in manifest_files}
        elif all(is_hex_digest(v) for v in manifest_files.values()):
            digests_in_manifest = {v.lower() for v in manifest_files.values()}
        else:
            # Fall back: assume the keys are the digests and silently accept
            digests_in_manifest = {str(k).lower() for k in manifest_files.keys()}
    elif isinstance(manifest_files, (list, set, tuple)):
        digests_in_manifest = {str(d).lower() for d in manifest_files}
    else:
        raise TypeError("manifest_files must be a dict or an iterable of digests")

    # Normalise the used digests
    if not isinstance(digests_used, (list, set, tuple)):
        raise TypeError("digests_used must be an iterable")
    used_digests = {str(d).lower() for d in digests_used}

    # Any digest that is required but not used is an error
    missing_used = digests_in_manifest.difference(used_digests)
    if missing_used:
        raise ValueError(
            f"The following digests are present in the manifest but were "
            f"not used: {', '.join(sorted(missing_used))}"
        )

    # If you also want to warn about digests that were used but not listed
    # in the manifest, you could add:
    # unused = used_digests.difference(digests_in_manifest)
    # if unused:
    #     self.logger.warn(
    #         f"Digests {', '.join(sorted(unused))} were used but are not "
    #         f"present in the manifest."
    #     )
    return True

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # If there is nothing to check, simply return
    if not manifest_files:
        return

    # Normalise digests_used to a set for efficient lookup
    try:
        digests_used_set = set(digests_used)
    except TypeError:
        # digests_used could be a single digest string
        digests_used_set = {digests_used}

    missing_digests = []
    for digest in manifest_files:
        # Allow manifest_files to be an iterable of digests or a mapping
        if isinstance(manifest_files, dict):
            # `digest` is the key; check if the key exists
            if digest not in digests_used_set:
                missing_digests.append(digest)
        else:
            # treat each item directly as a digest
            if digest not in digests_used_set:
                missing_digests.append(digest)

    if missing_digests:
        raise ValueError(
            "The following digests required by the manifest are not used: "
            + ", ".join(missing_digests)
        )

def validate_as_prior_version(self, prior):
    """Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type check
    if not isinstance(prior, type(self)):
        raise TypeError(f"prior must be an instance of {type(self).__name__}, got {type(prior).__name__}")

    # Helper to compare two collections
    def _compare_set(name, a_attr, b_attr):
        if not hasattr(self, a_attr):
            raise AttributeError(f"Current inventory is missing attribute '{a_attr}'")
        if not hasattr(prior, b_attr):
            raise AttributeError(f"Prior inventory is missing attribute '{b_attr}'")
        a_set = set(getattr(self, a_attr))
        b_set = set(getattr(prior, b_attr))
        if a_set != b_set:
            raise ValueError(f"Mismatch in '{name}':\n  Current:  {sorted(a_set)}\n  Prior:    {sorted(b_set)}")

    # Check species and parameters for set equality
    _compare_set('species', 'species', 'species')
    _compare_set('parameters', 'parameters', 'parameters')

    # If mapping dicts exist, verify their keys and ordering
    for attr in ('name_to_index', 'index_to_name'):
        if hasattr(self, attr) and hasattr(prior, attr):
            self_map = getattr(self, attr)
            prior_map = getattr(prior, attr)
            if set(self_map.keys()) != set(prior_map.keys()):
                raise ValueError(f"Mismatch in map keys for '{attr}':\n  Current keys: {sorted(self_map.keys())}\n  Prior keys:   {sorted(prior_map.keys())}")
            # Ensure order correspondence if mapping values are indices
            if all(isinstance(v, int) for v in self_map.values()) and all(isinstance(v, int) for v in prior_map.values()):
                # sort by keys and compare lists
                self_order = [self_map[k] for k in sorted(self_map)]
                prior_order = [prior_map[k] for k in sorted(prior_map)]
                if self_order != prior_order:
                    raise ValueError(f"Ordering mismatch in '{attr}' between current and prior inventory")
        else:
            # If an attribute exists only in one side, consider it a mismatch
            missing_curr = not hasattr(self, attr)
            missing_prior = not hasattr(prior, attr)
            if missing_curr != missing_prior:
                side = "current" if missing_curr else "prior"
                raise ValueError(f"Attribute '{attr}' missing in {side} inventory")

    # Check consistency of additional dicts if present
    for dict_attr in ('constraints', 'priors'):
        if hasattr(self, dict_attr) and hasattr(prior, dict_attr):
            self_dict = getattr(self, dict_attr)
            prior_dict = getattr(prior, dict_attr)
            if set(self_dict.keys()) != set(prior_dict.keys()):
                raise ValueError(f"Mismatch in keys for '{dict_attr}':\n  Current: {sorted(self_dict.keys())}\n  Prior:   {sorted(prior_dict.keys())}")
        else:
            missing_curr = not hasattr(self, dict_attr)
            missing_prior = not hasattr(prior, dict_attr)
            if missing_curr != missing_prior:
                side = "current" if missing_curr else "prior"
                raise ValueError(f"Attribute '{dict_attr}' missing in {side} inventory")

    # All checks passed – no explicit return needed (None indicates success)

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type checking
    if prior is None:
        raise ValueError("Prior inventory validator cannot be None.")
    try:
        validator_cls = type(self)
    except Exception:
        validator_cls = None
    if validator_cls is None or not isinstance(prior, validator_cls):
        raise TypeError("Prior must be an instance of the same InventoryValidator class as self.")

    # Helper to convert attribute to set
    def _to_set(attr_name):
        attr = getattr(self, attr_name, None)
        if attr is None:
            return None
        try:
            return set(attr)
        except Exception:
            return None

    # Attributes that should be subsets in the prior
    attrs_to_check = ['species', 'parameters', 'variables', 'constraints']
    for attr in attrs_to_check:
        self_set = _to_set(attr)
        prior_set = None
        # For constraints, we may want keys instead of values
        if attr == 'constraints':
            self_set = set(getattr(self, attr, {}).keys())
            prior_set = set(getattr(prior, attr, {}).keys())
        else:
            prior_set = _to_set(attr)
        # If the attribute exists in prior but not in self, invalid
        if prior_set is not None:
            if self_set is None:
                raise ValueError(f"Prior contains '{attr}' but current inventory does not.")
            # ensure prior's set is a subset of self's set
            if not prior_set.issubset(self_set):
                missing = prior_set - self_set
                raise ValueError(f"Prior contains {attr} items not present in current inventory: {missing}")

    # Optional: check that any transformation mappings in prior also exist in self
    prior_transforms = getattr(prior, 'transformations', None)
    self_transforms = getattr(self, 'transformations', None)
    if prior_transforms is not None:
        if self_transforms is None:
            raise ValueError("Prior has transformations but current inventory does not.")
        for key, trans in prior_transforms.items():
            if key not in self_transforms:
                raise ValueError(f"Transformation key '{key}' from prior not present in current inventory.")
            # Basic type check: ensure same type
            if type(trans) != type(self_transforms[key]):
                raise ValueError(f"Transformation type mismatch for key '{key}': prior has {type(trans).__name__}, "
                                 f"current has {type(self_transforms[key]).__name__}")

    # If we reach here, prior passes all sanity checks
    return None

def validate_as_prior_version(self, prior):
    """
    Check that prior is a valid prior version of the current inventory object.

    The input variable prior is also expected to be an InventoryValidator object
    and both self and prior inventories are assumed to have been checked for
    internal consistency.
    """
    # Basic type compatibility check
    if not isinstance(prior, type(self)):
        raise TypeError("prior must be an instance of the same validator type as self")

    error_messages = []

    # Parameters should be a subset of the current inventory's parameters
    for param_attr in ("parameters", "params", "parameter_list"):
        if hasattr(self, param_attr) and hasattr(prior, param_attr):
            try:
                self_params = set(getattr(self, param_attr))
                prior_params = set(getattr(prior, param_attr))
            except Exception as exc:
                error_messages.append(f"Failed to compare parameters from '{param_attr}': {exc!s}")
            else:
                if not prior_params.issubset(self_params):
                    error_messages.append(
                        f"Prior's {param_attr} {prior_params} is not a subset of current's {param_attr} {self_params}"
                    )

    # Constraints should match exactly
    for const_attr in ("constraints", "constraint_dict", "constraints_def"):
        if hasattr(self, const_attr) and hasattr(prior, const_attr):
            self_constraints = getattr(self, const_attr)
            prior_constraints = getattr(prior, const_attr)
            try:
                if isinstance(self_constraints, dict) and isinstance(prior_constraints, dict):
                    if self_constraints != prior_constraints:
                        error_messages.append(
                            f"Constraints differ: prior {prior_constraints} != current {self_constraints}"
                        )
                else:
                    if self_constraints != prior_constraints:
                        error_messages.append(
                            f"Constraints differ: prior {prior_constraints} != current {self_constraints}"
                        )
            except Exception as exc:
                error_messages.append(f"Failed to compare constraints from '{const_attr}': {exc!s}")

    # Versioning / timestamp should not be newer in the prior
    for time_attr in ("created_at", "timestamp", "version"):
        if hasattr(self, time_attr) and hasattr(prior, time_attr):
            try:
                self_time = getattr(self, time_attr)
                prior_time = getattr(prior, time_attr)
            except Exception as exc:
                error_messages.append(f"Failed to compare time attribute '{time_attr}': {exc!s}")
            else:
                try:
                    # If comparable (e.g., datetime, int, float)
                    if prior_time > self_time:
                        error_messages.append(
                            f"Prior's {time_attr} ({prior_time}) is newer than current's ({self_time})"
                        )
                except TypeError:
                    # If they are not directly comparable, skip comparison
                    pass

    if error_messages:
        raise ValueError("Invalid prior version: " + "; ".join(error_messages))

def validate_as_prior_version(self, prior):
        """Check that prior is a valid prior version of the current inventory object.

        The input variable prior is also expected to be an InventoryValidator object
        and both self and prior inventories are assumed to have been checked for
        internal consistency.
        """
        # Basic type guard
        if not isinstance(prior, type(self)):
            raise TypeError(
                f'`prior` must be an instance of the same class as the current inventory '
                f'({type(self).__name__}), got {type(prior).__name__}'
            )

        # Ensure all parameters and species of the current inventory exist in the prior
        current_params = set(self.parameters)
        prior_params = set(prior.parameters)
        missing_params = current_params - prior_params
        if missing_params:
            raise ValueError(
                f'Current inventory references parameters not present in the prior inventory: '
                f'{sorted(missing_params)}'
            )

        current_species = set(self.species)
        prior_species = set(prior.species)
        missing_species = current_species - prior_species
        if missing_species:
            raise ValueError(
                f'Current inventory references species not present in the prior inventory: '
                f'{sorted(missing_species)}'
            )

        # Verify that matrix dimensions are compatible if the attributes exist
        if hasattr(self, 'stoichiometry_matrix') and hasattr(prior, 'stoichiometry_matrix'):
            err_msg = (
                'Stoichiometry matrix shape mismatch between current and prior inventories: '
                f'{self.stoichiometry_matrix.shape} vs {prior.stoichiometry_matrix.shape}'
            )
            if self.stoichiometry_matrix.shape != prior.stoichiometry_matrix.shape:
                raise ValueError(err_msg)

        if hasattr(self, 'propensities') and hasattr(prior, 'propensities'):
            err_msg = (
                'Propensities matrix shape mismatch between current and prior inventories: '
                f'{self.propensities.shape} vs {prior.propensities.shape}'
            )
            if self.propensities.shape != prior.propensities.shape:
                raise ValueError(err_msg)

        # Optionally check constraints if attributes are present
        if hasattr(self, 'constraints') and hasattr(prior, 'constraints'):
            # Missing constraints in prior
            missing_constraints = set(self.constraints) - set(prior.constraints)
            if missing_constraints:
                raise ValueError(
                    f'Current inventory contains constraints not present in the prior inventory: '
                    f'{sorted(missing_constraints)}'
                )

            # Compare each shared constraint for equality
            for key in self.constraints:
                if key in prior.constraints and self.constraints[key] != prior.constraints[key]:
                    raise ValueError(
                        f'Constraint `{key}` differs between current and prior inventories.'
                    )

        # All checks passed; the prior is considered a valid prior version

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    if inventory is None:
        raise ValueError("inventory must not be None")
    if not isinstance(inventory, (dict, list, tuple)):
        raise TypeError(f"inventory must be a dict or list, got {type(inventory)}")
    if not isinstance(version, str):
        raise TypeError(f"version must be a string, got {type(version)}")

    # We assume ``inventory`` is an iterable of entries (dicts or namedtuples)
    # where each entry may have the keys ``logical_path``, ``content_files``
    # and ``version``.  If ``inventory`` is a mapping from logical paths to
    # content, we handle that case as well.
    result = {}

    # Helper to add content files for a logical path
    def _add_entry(logical_path, files):
        if logical_path not in result:
            result[logical_path] = set()
        result[logical_path].update(files)

    if isinstance(inventory, dict):
        # Mapping from logical_path -> list[content_file] or list[tuple]
        for logical_path, entry in inventory.items():
            # ``entry`` may be a list of content file paths or a dict with
            # version information etc.  We try to extract file names.
            try:
                files = set(entry) if isinstance(entry, (list, tuple)) else {entry}
            except Exception:
                continue
            _add_entry(logical_path, files)
        return result

    # Iterate over iterable entries
    for entry in inventory:
        if not isinstance(entry, (dict,)):
            # skip unknown format
            continue
        try:
            entry_version = entry.get("version")
            logical_path = entry["logical_path"]
            files = entry.get("content_files", [])
        except KeyError:
            # skip entries that don't have required keys
            continue
        # If the entry's version matches the requested version, include it.
        # Also include entries from later versions (duplicates in later
        # versions) as requested in the docstring.
        if entry_version == version or entry_version > version:
            _add_entry(logical_path, files)
    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic validation of arguments
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary")
    if version is None:
        raise ValueError("version must be specified")

    result = {}
    for logical_path, data in inventory.items():
        # Expect each entry to be a mapping from version to file(s)
        if isinstance(data, dict):
            files = data.get(version)
            if files is None:
                # No entry for this version – skip
                continue
            # Normalize into a set of strings
            if isinstance(files, (list, tuple, set)):
                result[logical_path] = {str(f) for f in files}
            else:
                # Assume a single file path
                result[logical_path] = {str(files)}
        else:
            # Unexpected entry type – ignore
            continue

    return result

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # Basic type check for inventory
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a dictionary mapping versions to path mappings")

    # Helper to generate a sortable key for a version string
    def _vers_key(v):
        try:
            # Try numeric split (e.g., '1.2.10' -> (1,2,10))
            parts = []
            for part in v.replace('-', '.').split('.'):
                if part.isdigit():
                    parts.append(int(part))
                else:
                    # If part contains non-digit, keep as string to preserve order
                    parts.append(part)
            return tuple(parts)
        except Exception:
            return v

    # Compute targeted key
    try:
        target_key = _vers_key(version)
    except Exception:
        target_key = version

    # Sort all available version keys
    try:
        sorted_keys = sorted(inventory.keys(), key=_vers_key)
    except Exception:
        sorted_keys = list(inventory.keys())

    # Determine relevant keys (>= target) in sorted order
    relevant_keys = [k for k in sorted_keys if _vers_key(k) >= target_key]
    if not relevant_keys:
        return {}

    result = {}
    for ver in relevant_keys:
        mapping = inventory.get(ver, {})
        if not isinstance(mapping, dict):
            # Skip malformed entries
            continue
        for logical_path, files in mapping.items():
            if logical_path is None:
                continue
            try:
                # Normalize to a set
                file_set = set(files)
            except TypeError:
                # If files is a single element (not iterable) wrap it
                file_set = {files}
            result.setdefault(logical_path, set()).update(file_set)

    return result

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity block must be a dictionary")
    if 'files' not in fixity:
        raise ValueError("Fixity block missing 'files' key")
    files = fixity['files']
    if not isinstance(files, list):
        raise ValueError("'files' in fixity block must be a list")
    for entry in files:
        if not isinstance(entry, dict):
            raise ValueError("Each file entry must be a dictionary")
        if 'filename' not in entry:
            raise ValueError("File entry missing 'filename'")
        filename = entry['filename']
        if not isinstance(filename, str):
            raise ValueError("Filename must be a string")
        if filename not in manifest_files:
            raise ValueError(f"Fixity block references unknown file: {filename}")
    return True

def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    # Ensure manifest_files is a set for efficient lookup
    if not isinstance(manifest_files, (list, set, tuple)):
        raise ValueError("manifest_files must be an iterable of file identifiers")
    manifest_set = set(manifest_files)

    # ----- Determine the structure of the fixity block -----
    # Accept either a dict with a 'checksums' key or a list directly
    if isinstance(fixity, dict):
        if 'checksums' not in fixity:
            raise ValueError("Fixity block missing required 'checksums' key")
        entries = fixity['checksums']
    elif isinstance(fixity, list):
        entries = fixity
    else:
        raise ValueError("Fixity block must be a dict or a list")

    if not isinstance(entries, list):
        raise ValueError("'checksums' must be a list")

    if not entries:
        raise ValueError("Empty fixity list")

    # ----- Validate each entry -----
    for idx, entry in enumerate(entries):
        if not isinstance(entry, dict):
            raise ValueError(f"Fixity entry at index {idx} is not a dict")
        if 'path' not in entry or 'hash' not in entry:
            missing = []
            if 'path' not in entry:
                missing.append("'path'")
            if 'hash' not in entry:
                missing.append("'hash'")
            raise ValueError(f"Fixity entry at index {idx} missing {', '.join(missing)}")

        path = entry['path']
        if path not in manifest_set:
            raise ValueError(f"Fixity entry refers to file '{path}' not present in manifest")

        # Optional: basic sanity on hash value (hex string length 32 or 64)
        h = entry['hash']
        if not isinstance(h, str) or not all(c in '0123456789abcdefABCDEF' for c in h):
            raise ValueError(f"Hash value for path '{path}' is not a valid hexadecimal string")
        if len(h) not in (32, 64):
            raise ValueError(f"Hash length for path '{path}' is unexpected (got {len(h)})")
    # If all checks pass, the fixity block is considered valid
    return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")
        if not isinstance(manifest_files, (list, set, tuple)):
            raise ValueError("Manifest files should be a list, set or tuple")

        manifest_set = set(manifest_files)

        if not fixity:
            raise ValueError("Fixity block cannot be empty")

        required_keys = {"checksum", "algorithm"}

        for file_ref, entry in fixity.items():
            if not isinstance(file_ref, str):
                raise ValueError(f"File reference must be a string, got {type(file_ref).__name__}")
            if file_ref not in manifest_set:
                raise ValueError(f"Fixity references unknown file: {file_ref}")
            if not isinstance(entry, dict):
                raise ValueError(f"Fixity entry for {file_ref} must be a dictionary")
            missing = required_keys - entry.keys()
            if missing:
                raise ValueError(f"Fixity entry for {file_ref} is missing keys: {', '.join(missing)}")
            # Basic type checks for the required values
            if not isinstance(entry["checksum"], str) or not entry["checksum"]:
                raise ValueError(f"Invalid checksum for {file_ref}")
            if not isinstance(entry["algorithm"], str) or not entry["algorithm"]:
                raise ValueError(f"Invalid algorithm for {file_ref}")

        # Ensure that all files in the manifest appear in the fixity block
        # (optional, but commonly expected)
        missing_in_fixity = manifest_set - set(fixity.keys())
        if missing_in_fixity:
            raise ValueError(f"Manifest contains files not present in fixity: {', '.join(missing_in_fixity)}")

        return True

def validate_fixity(self, fixity, manifest_files):
        """Validate fixity block in inventory.

        Check the structure of the fixity block and makes sure that only files
        listed in the manifest are referenced.
        """
        # Ensure the fixity block is a dictionary
        if not isinstance(fixity, dict):
            raise ValueError("Fixity block must be a dictionary")

        # Expected top-level keys
        required_keys = {'files'}
        missing = required_keys - fixity.keys()
        if missing:
            raise ValueError(f"Missing required key(s) in fixity block: {', '.join(sorted(missing))}")

        files = fixity['files']
        if not isinstance(files, list):
            raise ValueError("'files' entry must be a list")

        # Normalize the manifest for quick lookup
        manifest_set = set(manifest_files)

        seen_paths = set()
        for idx, entry in enumerate(files):
            if not isinstance(entry, dict):
                raise ValueError(f"Entry {idx} in 'files' list must be a dictionary")

            if 'path' not in entry:
                raise ValueError(f"Entry {idx} missing required 'path' field")

            path = entry['path']
            if not isinstance(path, str):
                raise ValueError(f"'path' in entry {idx} must be a string")

            if path not in manifest_set:
                raise ValueError(f"Path '{path}' referenced in fixity block is not present in the manifest")

            if path in seen_paths:
                raise ValueError(f"Duplicate path '{path}' found in fixity block")
            seen_paths.add(path)

            # Optional: ensure that checksum or algorithm fields are present
            # If present, they must be string values
            checksum_fields = ('checksum', 'algorithm', 'sha256', 'md5')
            for cf in checksum_fields:
                if cf in entry and not isinstance(entry[cf], str):
                    raise ValueError(f"'{cf}' in entry {idx} must be a string")

            # Reject any unexpected keys
            allowed_keys = set(['path', 'checksum', 'algorithm', 'sha256', 'md5'])
            unexpected = set(entry.keys()) - allowed_keys
            if unexpected:
                raise ValueError(f"Unexpected key(s) {', '.join(sorted(unexpected))} in entry {idx}")

        # If all checks pass, return True (no explicit return otherwise)
        return True

def files_list(path):
    """
    Return the files in `path`
    """
    import os
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path does not exist: {path}")
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    files = []
    for root, _, filenames in os.walk(path):
        for name in filenames:
            files.append(os.path.abspath(os.path.join(root, name)))
    return sorted(files)

def files_list(path):
    """
    Return the files in `path`
    """
    if not os.path.exists(path):
        raise FileNotFoundError(path)
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    files = []
    try:
        for entry in os.listdir(path):
            full_path = os.path.join(path, entry)
            if os.path.isfile(full_path):
                files.append(os.path.abspath(full_path))
    except OSError as exc:
        raise
    return sorted(files)

def files_list(path):
    """
    Return the files in `path`.

    - If `path` is a file, returns a list containing its absolute path.
    - If `path` is a directory, returns a sorted list of absolute paths
      of all files in that directory and its subdirectories (recursively).
    - Raises FileNotFoundError if `path` does not exist.
    """
    abs_path = os.path.abspath(path)
    if not os.path.exists(abs_path):
        raise FileNotFoundError(f"No such file or directory: '{path}'")
    if os.path.isfile(abs_path):
        return [abs_path]
    if os.path.isdir(abs_path):
        files = []
        for root, _, filenames in os.walk(abs_path):
            for fname in filenames:
                files.append(os.path.join(root, fname))
        return sorted(files)
    # If the path exists but is neither a file nor a directory (rare case)
    return []

def files_list(path):
    """Return the files in `path`."""
    # Verify the path exists
    if not os.path.exists(path):
        raise FileNotFoundError(f"Path '{path}' does not exist.")
    # If it's a file, return it
    if os.path.isfile(path):
        return [os.path.abspath(path)]
    # If it's a directory, return all files in it (recursively)
    if os.path.isdir(path):
        files = []
        try:
            for root, dirs, filenames in os.walk(path):
                for fname in filenames:
                    files.append(os.path.abspath(os.path.join(root, fname)))
        except Exception as e:
            # Propagate unexpected errors (such as permission issues)
            raise e
        return sorted(files)
    # For any other type of path, return an empty list
    return []

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
    """
    import os

    if not isinstance(folder, str):
        raise TypeError("folder must be a string representing a directory path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder '{folder}' does not exist or is not a directory")

    # Find all XML files and collect their basenames
    xml_basenames = set()
    try:
        for root, dirs, files in os.walk(folder):
            for filename in files:
                base, ext = os.path.splitext(filename)
                if ext.lower() == ".xml":
                    xml_basenames.add(base)
    except OSError as e:
        raise RuntimeError(f"Error while scanning the folder '{folder}': {e}") from e

    # Group all files whose basename matches an XML basename
    packages = {}
    try:
        for root, dirs, files in os.walk(folder):
            for filename in files:
                base, _ = os.path.splitext(filename)
                if base in xml_basenames:
                    packages.setdefault(base, []).append(os.path.join(root, filename))
    except OSError as e:
        raise RuntimeError(f"Error while collecting package files in '{folder}': {e}") from e

    return packages

def _explore_folder(folder):
    """Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping of XML basename to list of file paths belonging to the same package.
    """
    import os
    result = {}
    if not os.path.isdir(folder):
        # If the folder doesn't exist, return an empty dict
        return result

    # First pass: identify all XML files and collect their basenames
    xml_basenames = set()
    try:
        for root, _, files in os.walk(folder):
            for name in files:
                if name.lower().endswith('.xml'):
                    basename = os.path.splitext(name)[0]
                    xml_basenames.add(basename)
    except Exception:
        # Any error while walking the directory results in an empty result
        return result

    # Second pass: group every file that shares a basename with an XML file
    try:
        for root, _, files in os.walk(folder):
            for name in files:
                basename = os.path.splitext(name)[0]
                if basename in xml_basenames:
                    full_path = os.path.join(root, name)
                    result.setdefault(basename, []).append(full_path)
    except Exception:
        # If something goes wrong while grouping, return whatever has been collected
        return result

    return result

def _explore_folder(folder):
    """
    Get packages' data from folder

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    folder : str
        Folder of the package
    Returns
    -------
    dict
        Mapping from the XML base name to a list of absolute file paths that share
        that base name. Only base names that have at least one .xml file are
        included.
    """
    import os
    if not isinstance(folder, str):
        raise TypeError("folder must be a string path")
    if not os.path.isdir(folder):
        raise FileNotFoundError(f"Folder {folder!r} does not exist or is not a directory")

    # Identify all XML basenames first
    xml_basenames = set()
    for root, _, files in os.walk(folder):
        for filename in files:
            if filename.lower().endswith(".xml"):
                base = os.path.splitext(filename)[0]
                xml_basenames.add(base)

    if not xml_basenames:
        return {}

    # Gather all files that match these basenames
    packages = {}
    for root, _, files in os.walk(folder):
        for filename in files:
            base, _ = os.path.splitext(filename)
            if base in xml_basenames:
                full_path = os.path.join(root, filename)
                packages.setdefault(base, []).append(full_path)

    return packages

def _eval_file(prefix, file_path):
    """Identifica o tipo de arquivo do pacote: `asset` ou `rendition`.

    Identifica o tipo de arquivo do pacote e atualiza `packages` com o tipo e
    o endereço do arquivo em análise.

    Parameters
    ----------
    prefix : str
        nome do arquivo XML sem extensão
    file_path : str
        full path to the file

    Returns
    -------
    dict
        {'type': <asset|rendition|unknown>, 'path': <file_path>}
    """
    import os

    # Validate input
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")
    if not isinstance(file_path, str):
        raise TypeError("file_path must be a string")

    # Normalise file name and extension
    try:
        base_name = os.path.basename(file_path)
        name_part, ext = os.path.splitext(base_name)
    except Exception as e:
        raise ValueError(f"Could not parse file path '{file_path}': {e}")

    # Default type is unknown
    file_type = "unknown"

    # Basic heuristics based on naming patterns
    lname = base_name.lower()
    lprefix = prefix.lower()
    if ("asset" in lname or "asset" in lprefix) or ext.lower() in {".asset", ".a"}:
        file_type = "asset"
    elif ("rendition" in lname or "rendition" in lprefix) or ext.lower() in {".rendition", ".r"}:
        file_type = "rendition"
    else:
        # Extend heuristics to common media type extensions
        audio_exts = {".mp3", ".wav", ".aac", ".flac", ".ogg"}
        video_exts = {".mp4", ".mkv", ".mov", ".avi", ".flv"}
        if ext.lower() in audio_exts:
            file_type = "asset"
        elif ext.lower() in video_exts:
            file_type = "rendition"

    result = {"type": file_type, "path": file_path}
    return result

def add_rendition(self, lang, file_path):
    """
    Registers a language-specific rendition of a document.

    The method determines the original document path by stripping the
    language suffix from the supplied file_path.  It then stores the
    mapping of original → {lang: rendition_path} in an internal
    dictionary (self.renditions).  A simple mapping dictionary is also
    returned for convenience.

    Example mapping after adding the rendition:
        {
            "original": "artigo02.pdf",
            "en": "artigo02-en.pdf",
        }

    Arguments:
        lang:  ISO language code for the rendition (e.g., 'en', 'fr').
        file_path: Absolute or relative path to the language-specific
                   rendition file.

    Returns:
        A dictionary describing the rendition mapping.
    """
    # Validate arguments
    if not isinstance(lang, str) or not isinstance(file_path, str):
        return {}

    # Split directory and filename
    try:
        dirname, filename = os.path.split(file_path)
    except Exception:
        return {}

    # Determine the original filename by removing a trailing "-<lang>"
    # before the extension.  If the pattern is not found, fall back
    # to the provided filename unchanged.
    lang_suffix = f'-{lang}'
    if lang_suffix in filename:
        # Remove the last occurrence of the language suffix
        base, ext = os.path.splitext(filename)
        parts = base.rsplit(lang_suffix, 1)
        if len(parts) == 2:
            original_base, _ = parts
        else:
            original_base = base
        original_name = original_base + ext
    else:
        original_name = filename  # cannot infer, leave unchanged

    original_path = os.path.join(dirname, original_name)

    # Initialize storage if necessary
    if not hasattr(self, 'renditions') or not isinstance(self.renditions, dict):
        self.renditions = {}

    # Use absolute paths to avoid duplicate keys from relative references
    abs_original = os.path.abspath(original_path)
    abs_rendition = os.path.abspath(file_path)

    # Register mapping
    if abs_original not in self.renditions:
        self.renditions[abs_original] = {}
    self.renditions[abs_original][lang] = abs_rendition

    # Return a simple mapping dictionary
    return {"original": original_path, lang: file_path}

