    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    result = {}
    try:
        with zipfile.ZipFile(zip_path, 'r') as zf:
            # First pass: map each directory to its package XML base name
            dir_xml = {}
            for zinfo in zf.infolist():
                if zinfo.is_dir():
                    continue
                name = zinfo.filename
                if name.lower().endswith('.xml'):
                    base_name = os.path.splitext(os.path.basename(name))[0]
                    dir_xml[os.path.dirname(name)] = base_name

            # Second pass: collect all files under the same directory as the package XML
            for zinfo in zf.infolist():
                if zinfo.is_dir():
                    continue
                name = zinfo.filename
                try:
                    content = zf.read(zinfo)
                except Exception:
                    continue
                dir_path = os.path.dirname(name)
                key = dir_xml.get(dir_path)
                if key is None:
                    continue
                if key not in result:
