def _explore_zipfile(zip_path):
    """Get packages' data from zip_path

    Groups files by their XML basename and returns data in dict format.

    Parameters
    ----------
    zip_path : str
        zip file path
    Returns
    -------
    dict
    """
    # Basic validation of input
    if not isinstance(zip_path, str) or not zip_path:
        return {}

    try:
        zf = zipfile.ZipFile(zip_path)
    except FileNotFoundError:
        # Zip file does not exist
        return {}
    except zipfile.BadZipFile:
        # Corrupt or invalid zip file
        return {}

    packages = {}
    for info in zf.infolist():
        # Skip directories
        if info.is_dir():
            continue
        filename = info.filename

        # Extract the base name (without directories)
        if '/' in filename:
            parts = filename.split('/')
        elif '\\' in filename:
            parts = filename.split('\\')
        else:
            parts = [filename]
        basename = parts[-1]

        # Remove file extension to get the group key
        if '.' in basename:
            group_key, _ = basename.rsplit('.', 1)
        else:
            group_key = basename

        try:
            data = zf.read(info)
        except Exception:
            # If reading a file fails, skip it
            continue

        # Initialize package entry if needed
        if group_key not in packages:
            packages[group_key] = {}
        # Store the full path and its binary content
        packages[group_key][filename] = data

    zf.close()
    return packages

