def _extract_number_and_supplment_from_issue_element(issue):
    """
    Extrai do conteúdo de <issue>xxxx</issue>, os valores number e suppl.
    Valores possíveis
    5 (suppl), 5 Suppl, 5 Suppl 1, 5 spe, 5 suppl, 5 suppl 1, 5 suppl. 1,
    25 Suppl 1, 2-5 suppl 1, 2spe, Spe, Supl. 1, Suppl, Suppl 12,
    s2, spe, spe 1, spe pr, spe2, spe.2, spepr, supp 1, supp5 1, suppl,
    suppl 1, suppl 5 pr, suppl 12, suppl 1-2, suppl. 1
    """
    import re

    if issue is None:
        return None, None

    # obter texto, caso seja um elemento XML/BeautifulSoup
    try:
        text = issue.text
    except AttributeError:
        try:
            text = str(issue)
        except Exception:
            return None, None

    text = text.strip()
    if not text:
        return None, None

    tokens = [t for t in re.split(r'\s+', text) if t]
    number = None
    sup_tokens = []

    # palavras que indicam suplemento
    sup_keywords = {"suppl", "supp", "sup", "spe", "supl", "pr"}

    for i, tok in enumerate(tokens):
        clean = tok.replace(".", "").lower()
        # Detectar número (ou intervalo de números)
        if re.fullmatch(r'\d+', clean) or re.fullmatch(r'\d+-\d+', clean):
            number = clean
        # Detectar tokens de suplemento
        if any(k in clean for k in sup_keywords):
            sup_tokens.append(tok)
        elif re.fullmatch(r's\d+', clean):
            sup_tokens.append(tok)

    # Se não houver número mas o primeiro token for numérico, usá‑lo
    if number is None:
        for tok in tokens:
            if re.fullmatch(r'\d+', tok) or re.fullmatch(r'\d+-\d+', tok):
                number = tok
                break

    sup = " ".join(sup_tokens).strip() or None
    num = number or None

    return num, sup

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    # Validate indent
    if not isinstance(indent, int) or indent < 0:
        indent = 0
    # Build representation
    try:
        import json
        rep = json.dumps(
            self,
            default=lambda o: getattr(o, '__dict__', str(o)),
            indent=indent,
            sort_keys=True,
        )
    except Exception:
        try:
            import pprint
            rep = pprint.pformat(self, indent=indent)
        except Exception:
            rep = repr(self)
    if debug:
        debug_info = (
            f"\nDebug: type={type(self).__name__}, "
            f"id={id(self)}, "
            f"repr={repr(self)}"
        )
        rep += debug_info
    return rep

def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    indent_str = '  ' * indent
    lines = [f"{indent_str}{self.__class__.__name__}:"]
    if debug:
        lines[-1] += f" (id={id(self)!r})"

    try:
        attrs = vars(self)
    except Exception:
        attrs = {}

    if not attrs:
        return '\n'.join(lines)

    for key in sorted(attrs):
        val = attrs[key]
        # Try to use a custom pretty method if available
        pretty_val = None
        if hasattr(val, 'pretty') and callable(val.pretty):
            try:
                pretty_val = val.pretty(indent=indent + 1, debug=debug)
            except Exception:
                pretty_val = None

        if pretty_val is not None:
            lines.append(f"{indent_str}  {key}:\n{pretty_val}")
        else:
            lines.append(f"{indent_str}  {key}: {repr(val)}")

    return '\n'.join(lines)

def pretty(self, indent=0, debug=False):
    """
