def get_versions():
    """Get version information or return default if unable to do so."""
    default = "unknown"
    # 1. Try importlib.metadata (Python 3.8+)
    try:
        from importlib.metadata import version as _ver, PackageNotFoundError
        pkg = __name__.split('.')[0]
        if pkg and pkg != "__main__":
            try:
                return _ver(pkg)
            except PackageNotFoundError:
                pass
    except Exception:
        pass

    # 2. Try a version.py module in the same directory
    try:
        import os
        path = os.path.join(os.path.dirname(__file__), "version.py")
        if os.path.isfile(path):
            ns = {}
            with open(path, "r", encoding="utf-8") as f:
                exec(f.read(), ns)
            if "VERSION" in ns:
                return str(ns["VERSION"]).strip()
            if "__version__" in ns:
                return str(ns["__version__"]).strip()
    except Exception:
        pass

    # 3. Try a plain VERSION file in the same directory
    try:
        import os
        path = os.path.join(os.path.dirname(__file__), "VERSION")
        if os.path.isfile(path):
            with open(path, "r", encoding="utf-8") as f:
                return f.read().strip()
    except Exception:
        pass

    return default

def get_versions():
