    try:
        # Try to import importlib.metadata for Python 3.8+
        from importlib.metadata import version, PackageNotFoundError
        # Attempt to determine the package name from the current module
        pkg_name = __package__
        if not pkg_name:
            # Fallback: use the script name if executed as a script
            import os, sys
            script_name = os.path.basename(sys.argv[0])
            pkg_name = os.path.splitext(script_name)[0]
        return version(pkg_name)
    except Exception:
        # If any error occurs (module not found, import error, etc.), return a default value
        return 'unknown'

