            raise TypeError("commands must be a string or a sequence of strings")
    if args:
        if isinstance(args, str):
            import shlex
            arg_parts = shlex.split(args)
        elif isinstance(args, (list, tuple)):
            arg_parts = list(args)
        else:
            raise TypeError("args must be a string or a sequence of strings")
        cmd_parts.extend(arg_parts)

    if verbose:
        print("Running command:", ' '.join(cmd_parts))

    # Prepare subprocess arguments
    kwargs = {
        'cwd': cwd,
        'env': env,
        'stdout': subprocess.PIPE,
        'stderr': subprocess.DEVNULL if hide_stderr else subprocess.PIPE
    }

    try:
        proc = subprocess.Popen(cmd_parts, **kwargs)
        stdout, stderr = proc.communicate()
        if proc.returncode != 0:
            raise subprocess.CalledProcessError(
                proc.returncode,
                cmd_parts,
                output=stdout,
                stderr=stderr
            )
        # Return decoded output; empty if nothing was printed
        return stdout.decode('utf-8')
    except OSError as e:
        raise RuntimeError(f"Failed to run command {cmd_parts!r}: {e}")

