    except Exception as exc:
        raise RuntimeError("Failed to instantiate VersioneerConfig: %s" % exc)
    # Set a set of sane defaults.  These match the typical attributes used by Versioneer.
    defaults = {
        'versionfile_source': 'src/__init__.py',
        'versionfile_build': 'src/__init__.py',
        'tag_prefix': '',
        'parentdir_prefix_version': '',
        'style': 'pep440',
        'search_parent_directories': True,
    }
    for key, value in defaults.items():
        # Only set defaults for attributes that do not already exist.
        if not hasattr(config, key):
            setattr(config, key, value)
    # Attempt to override defaults with values specified in a local configuration file.
    # The file is expected to be named 'versioneer.cfg' and located in the same directory
    # as this module.  The file format is INI; the relevant section is [versioneer].
    config_file = Path(__file__).parent / 'versioneer.cfg'
    if config_file.is_file():
        parser = configparser.ConfigParser()
        try:
            with config_file.open('r', encoding='utf-8') as f:
                parser.read_file(f)
        except (OSError, configparser.ParsingError):
            # If reading or parsing fails, silently fall back to defaults.
            pass
        else:
            if parser.has_section('versioneer'):
                for key, raw_value in parser.items('versioneer'):
                    # Convert boolean strings to actual booleans where appropriate.
                    true_values = {'true', 'yes', '1', 'on'}
                    false_values = {'false', 'no', '0', 'off'}
                    if key == 'search_parent_directories':
                        value = raw_value.lower() in true_values
                    else:
