def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        tuple: (num_objects, good_objects) where num_objects is the total
        number of objects that were inspected and good_objects is the
        number of objects found to be valid.  Objects which failed
        validation are counted in the difference.
    """
    # Collect all objects in the hierarchy.  The implementation assumes
    # that the hierarchy is made up of nodes that optionally expose a
    # ``children`` attribute which is an iterable of child nodes.
    def _flatten(node):
        """Generator that yields a node and then all of its descendants."""
        try:
            yield node
        except Exception:
            # If we cannot iterate over node itself, just return
            return
        try:
            children = getattr(node, 'children', None)
        except Exception:
            children = None
        if children and isinstance(children, (list, tuple)):
            for child in children:
                yield from _flatten(child)
        elif children:
            # Fall back to using an iterator if possible
            try:
                for child in iter(children):
                    yield from _flatten(child)
            except Exception:
                pass

    # Determine the root node.  If the current object defines a ``root``
    # attribute use it; otherwise we try to use ``self`` itself.
    try:
        root = getattr(self, 'root', None)
    except Exception:
        root = None
    if root is None:
        root = self

    num_objects = 0
    good_objects = 0

    # Helper functions for validation
    def validate_object(obj):
        """Validate a single object using a user defined method if
        available, otherwise default to True."""
        if hasattr(self, '_validate_object'):
            try:
                return bool(self._validate_object(obj))
            except Exception:
                if show_warnings:
                    print(f"Warning: _validate_object raised an exception for {obj!r}")
                return False
        return True

    def check_digest(obj):
        """Check the digest of an object if possible.  The object is
        considered valid if it has a ``data`` attribute or a
        ``content`` attribute that can be hashed with sha256.  If the
        object defines a ``digest`` attribute this is compared with
        the computed one."""
        try:
            if hasattr(obj, 'digest'):
                expected = getattr(obj, 'digest')
                # Try to read the data that should be hashed
                data = getattr(obj, 'data', None)
                if data is None:
                    data = getattr(obj, 'content', None)
                if data is None:
                    # Fall back to the object's __dict__ representation
                    data = str(obj.__dict__).encode('utf-8')
                else:
                    if isinstance(data, str):
                        data = data.encode('utf-8')
                    elif isinstance(data, (bytes, bytearray)):
                        data = bytes(data)
                import hashlib
                actual_hash = hashlib.sha256(data).hexdigest()
                return expected == actual_hash
            else:
                # No digest defined, consider it valid
                return True
        except Exception:
            if show_warnings:
                print(f"Warning: could not verify digest for {obj!r}")
            return False

    try:
        for node in _flatten(root):
            num_objects += 1
            valid = True
            if validate_objects:
                valid = validate_object(node)
            if valid and check_digests:
                valid = check_digest(node)
            if valid:
                good_objects += 1
    except Exception as err:
        if show_warnings:
            print(f"Error during hierarchy validation: {err!r}")
        # Even if the traversal failed, return what we counted so far
        return num_objects, good_objects

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    import os
    import hashlib

    # Helper to compute the SHA-256 digest of a file
    def _calculate_digest(file_path):
        sha256 = hashlib.sha256()
        try:
            with open(file_path, "rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    sha256.update(chunk)
        except Exception as e:
            raise IOError(f"Cannot calculate digest for {file_path}: {e}")
        return sha256.hexdigest()

    # Validate that the root directory attribute is defined and exists
    if not hasattr(self, "root_dir"):
        raise AttributeError("The instance must provide a 'root_dir' attribute pointing to the hierarchy base directory.")
    root_dir = self.root_dir
    if not isinstance(root_dir, str):
        raise TypeError(f"root_dir must be a string, got {type(root_dir).__name__}.")
    if not os.path.isdir(root_dir):
        raise ValueError(f"root_dir '{root_dir}' does not point to a valid directory.")

    num_objects = 0
    good_objects = 0

    for dirpath, dirnames, filenames in os.walk(root_dir):
        # Skip special UTF-8 BOM directories or system directories if needed
        # We only consider regular files as objects
        for fname in filenames:
            # Optionally skip digest files themselves from counting
            if check_digests and fname.endswith(".sha256"):
                continue

            file_path = os.path.join(dirpath, fname)
            num_objects += 1
            valid = True

            try:
                # Basic object validation: readable and non-empty if requested
                if validate_objects:
                    with open(file_path, "rb") as f:
                        first_byte = f.read(1)
                    if not first_byte:
                        valid = False
                        if show_warnings:
                            print(f"File is empty: {file_path}")

                # Digest validation if required
                if check_digests:
                    digest_path = file_path + ".sha256"
                    if os.path.isfile(digest_path):
                        try:
                            with open(digest_path, "r", encoding="utf-8") as df:
                                expected_digest = df.read().strip()
                        except Exception as e:
                            valid = False
                            if show_warnings:
                                print(f"Could not read digest file '{digest_path}': {e}")
                            expected_digest = None

                        if expected_digest is not None:
                            actual_digest = _calculate_digest(file_path)
                            if actual_digest != expected_digest:
                                valid = False
                                if show_warnings:
                                    print(f"Digest mismatch for {file_path}: expected {expected_digest}, got {actual_digest}")

            except Exception as e:
                valid = False
                if show_warnings:
                    print(f"Error processing {file_path}: {e}")

            if valid:
                good_objects += 1

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Ensure the root attribute exists and is a directory
    if not hasattr(self, "root"):
        raise AttributeError("Instance missing 'root' attribute which should be a path to the hierarchy root.")
    root_path = self.root
    try:
        from pathlib import Path
    except Exception as exc:
        raise RuntimeError(f"Required module pathlib is unavailable: {exc}") from exc

    root = Path(root_path)
    if not root.is_dir():
        raise FileNotFoundError(f"The root path '{root_path}' does not exist or is not a directory.")

    num_objects = 0
    good_objects = 0

    # Helper to compute file digest, only for small files
    def _compute_digest(file_path):
        try:
            import hashlib
            h = hashlib.sha256()
            with file_path.open("rb") as f:
                for chunk in iter(lambda: f.read(8192), b""):
                    h.update(chunk)
            return h.hexdigest()
        except Exception as err:
            if show_warnings:
                print(f"Warning: Unable to compute digest for {file_path}: {err}")
            return None

    # Helper to perform validation on a file
    def _validate_file(fp):
        # Basic validation: the file must be readable
        if not fp.is_file():
            return False
        if validate_objects:
            try:
                fp.open("rb").close()
            except Exception as e:
                if show_warnings:
                    print(f"Warning: File {fp} is not readable: {e}")
                return False
        if check_digests:
            # Optional: check that the digest computed is non-empty
            digest = _compute_digest(fp)
            if digest is None:
                return False
        return True

    # Traverse the hierarchy
    for child in root.rglob("*"):
        num_objects += 1
        try:
            if child.is_file():
                if _validate_file(child):
                    good_objects += 1
            else:  # treat directories and others as objects that are always valid
                good_objects += 1
        except Exception as e:
            if show_warnings:
                print(f"Warning: Error validating object {child}: {e}")

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    # Validate input types
    if not isinstance(validate_objects, bool):
        raise TypeError('validate_objects must be a bool.')
    if not isinstance(check_digests, bool):
        raise TypeError('check_digests must be a bool.')
    if not isinstance(show_warnings, bool):
        raise TypeError('show_warnings must be a bool.')

    # Ensure required traversal method exists
    if not hasattr(self, '_get_all_objects'):
        raise AttributeError('_get_all_objects method is required to traverse the hierarchy.')

    num_objects = 0
    good_objects = 0

    try:
        objects = self._get_all_objects()
    except Exception as e:
        raise RuntimeError(f'Failed to retrieve objects from hierarchy: {e}')

    for obj in objects:
        num_objects += 1
        is_valid = True
        messages = []

        # Validate object content if requested
        if validate_objects:
            try:
                if hasattr(self, '_validate_object'):
                    self._validate_object(obj)
                else:
                    # If no validation method, assume valid
                    pass
            except Exception as e:
                is_valid = False
                messages.append(f'Object validation failed: {e}')

        # Check digest if requested
        if check_digests:
            try:
                if hasattr(self, '_check_digest'):
                    self._check_digest(obj)
                else:
                    # If no digest method, assume valid
                    pass
            except Exception as e:
                is_valid = False
                messages.append(f'Digest check failed: {e}')

        if is_valid:
            good_objects += 1
        elif show_warnings:
            # Attempt to identify the object for clarity
            obj_id = getattr(obj, 'id', getattr(obj, 'name', str(obj)))
            warning_msg = f'Hierarchy object {obj_id} invalid: {"; ".join(messages)}'
            try:
                # Prefer logging if available
                import logging
                logging.warning(warning_msg)
            except Exception:
                print(warning_msg)

    return num_objects, good_objects

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        tuple(num_objects, good_objects) – number of objects checked and number of objects checked that were found to be valid.
    """
    # Attempt to obtain an iterable of objects.
    try:
        objects_iter = self.iterate_objects()
    except AttributeError:
        # Fallback to common attributes that might hold the objects.
        objs = getattr(self, 'objects', None) or getattr(self, '_objects', None)
        if objs is None:
            raise RuntimeError(
                "No method or attribute found to iterate over hierarchy objects."
            )
        if isinstance(objs, dict):
            objects_iter = objs.values()
        else:
            try:
                objects_iter = iter(objs)
            except TypeError:
                raise RuntimeError("Objects attribute is not iterable.")
    # Convert to list to allow multiple passes if needed.
    try:
        objects = list(objects_iter)
    except Exception as exc:
        raise RuntimeError(f"Failed to iterate over objects: {exc}") from exc

    num_objects = 0
    good_objects = 0
    warnings = []

    for obj in objects:
        num_objects += 1
        is_valid = True

        # Validate object itself if requested.
        if validate_objects:
            try:
                validate_method = getattr(obj, "validate", None)
                if callable(validate_method):
                    is_valid = bool(validate_method())
                else:
                    # If no validate method, assume object is valid.
                    is_valid = True
            except Exception as exc:
                is_valid = False
                warnings.append(f"Validation failed for {obj!r}: {exc}")

        # Check digest if requested and object is still considered valid.
        if is_valid and check_digests:
            try:
                digest_method = getattr(obj, "digest", None)
                expected_method = getattr(obj, "expected_digest", None)
                if callable(digest_method) and callable(expected_method):
                    actual = digest_method()
                    expected = expected_method()
                    if actual != expected:
                        is_valid = False
                        warnings.append(
                            f"Digest mismatch for {obj!r}: expected {expected!r}, got {actual!r}"
                        )
                else:
                    # If digest methods are absent, skip digest validation.
                    pass
            except Exception as exc:
                is_valid = False
                warnings.append(f"Digest check failed for {obj!r}: {exc}")

        if is_valid:
            good_objects += 1

    if show_warnings:
        for w in warnings:
            print(f"[WARNING] {w}")

    return num_objects, good_objects

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Resolve the desired root directory
    try:
        root_path = getattr(self, "root_path", None)
        if root_path is None:
            # Fall back to any stored attribute that may hold the path
            root_path = getattr(self, "path", None)
        if root_path is None:
            raise ValueError("No root path specified for OCFL storage.")
        from pathlib import Path
        root = Path(root_path).expanduser().resolve()
    except Exception as exc:
        raise ValueError(f"Unable to resolve root path: {exc}") from exc

    # Ensure we don't overwrite an existing OCFL root
    marker = root / ".ocfl_root"
    if root.exists():
        if marker.is_file():
            raise ValueError(f"An OCFL root already exists at '{root}'.")
        raise ValueError(f"Path '{root}' already exists and is not empty.")

    # Attempt to create the root directory structure
    try:
        root.mkdir(parents=True, exist_ok=False)
    except OSError as exc:
        raise ValueError(f"Could not create root directory '{root}': {exc}") from exc

    # Create the OCFL metadata file with the current version
    ocfl_version = "1.0"
    try:
        with marker.open("w", encoding="utf-8") as fp:
            fp.write(f'{{"ocfl_version":"{ocfl_version}"}}\n')
    except OSError as exc:
        raise ValueError(f"Could not write OCFL marker file at '{marker}': {exc}") from exc

    # Create a default subdirectory for objects (recommended but not required by spec)
    objects_dir = root / "objects"
    try:
        objects_dir.mkdir(exist_ok=False)
    except OSError as exc:
        # Not fatal – if the directory already exists we ignore it
        if exc.errno != 17:  # 17 = File exists
            raise ValueError(f"Could not create objects directory '{objects_dir}': {exc}") from exc

    # Store the resolved root in the instance for later reference
    setattr(self, "_ocfl_root", root)
    return self

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    # Ensure the root path has been set
    root_path = getattr(self, "root_path", None)
    if not root_path:
        raise ValueError("Attribute 'root_path' must be set before calling initialize.")
    root = pathlib.Path(root_path)

    # If root exists, verify it is a directory
    if root.exists():
        if not root.is_dir():
            raise ValueError(f"Root path {root} already exists and is not a directory.")
        # Check for existing OCFL root indicator
        if (root / ".ocfl-core").exists():
            raise RuntimeError(f"Storage root {root} is already initialized.")
    else:
        # Try to create the root directory
        try:
            root.mkdir(parents=True, exist_ok=False)
        except OSError as exc:
            raise RuntimeError(f"Failed to create root directory {root}: {exc}") from exc

    # Create the objects subdirectory
    objects_dir = root / "objects"
    try:
        objects_dir.mkdir(exist_ok=True)
    except OSError as exc:
        raise RuntimeError(f"Failed to create objects directory {objects_dir}: {exc}") from exc

    # Create the OCFL core descriptor file if missing
    descriptor_file = root / ".ocfl-core"
    if not descriptor_file.exists():
        try:
            descriptor_file.write_text("OCFL 1.0\n")
        except OSError as exc:
            raise RuntimeError(f"Failed to write descriptor file {descriptor_file}: {exc}") from exc

    # Return the path to the initialized root for convenience
    return root

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import pathlib
    # Determine where the root should be created.
    root_path = getattr(self, "root_dir", None)
    if root_path is None:
        raise AttributeError("Instance missing 'root_dir' attribute")

    root = pathlib.Path(root_path).expanduser().resolve()

    # Ensure the path does not already exist
    if root.exists():
        raise FileExistsError(f"Cannot initialize OCFL root; directory already exists: {root}")

    try:
        # Create the root directory and required OCFL subdirectories
        root.mkdir(parents=True, exist_ok=False)
        (root / "objects").mkdir()
        (root / "base_versions").mkdir()
        (root / "current").mkdir()

        # Create a minimal JSON configuration file for the OCFL root
        config_file = root / ".ocfl_root_config.json"
        config_file.write_text(
            '{"ocflVersion":"1.0","layout":"vdir","root":"objects"}',
            encoding="utf-8",
        )
    except Exception as exc:
        # Clean up any partially created structure
        if root.exists():
            try:
                for child in root.rglob("*"):
                    if child.is_file():
                        child.unlink()
                    else:
                        child.rmdir()
                root.rmdir()
            except Exception:
                pass
        raise RuntimeError(f"Failed to initialize OCFL root at {root!s}: {exc}") from exc
    # No value to return; initialization is complete.

