            raise ValueError(f"Existing path {root_path!r} is not a directory")
        if os.listdir(root_path):
            raise ValueError(f"Directory {root_path!r} already contains files; OCFL root must be empty")
    else:
        # Create the root directory (and parents if missing)
        try:
            os.makedirs(root_path, mode=0o755, exist_ok=True)
        except OSError as exc:
            raise OSError(f"Could not create OCFL root directory {root_path!r}: {exc}") from exc

    # Create standard OCFL subdirectories
    objects_dir = os.path.join(root_path, "objects")
    try:
        os.makedirs(objects_dir, mode=0o755, exist_ok=True)
    except OSError as exc:
        raise OSError(f"Could not create objects directory {objects_dir!r}: {exc}") from exc

    # Write the OCFL version file if it does not already exist
    version_file = os.path.join(root_path, ".ocfl_version")
    if not os.path.exists(version_file):
        try:
            with open(version_file, "w", encoding="utf-8") as fp:
                fp.write("1.0\n")
        except OSError as exc:
            raise OSError(f"Could not write OCFL version file {version_file!r}: {exc}") from exc

    # Store the resolved path on the instance for future use
    self.root_path = root_path
    return root_path

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if not isinstance(version, str):
            version = str(version)
        version = version.strip()
        if not version:
            return ""
    except Exception:
        return ""

    parts = version.split('.')
    if not parts:
        return version
    last = parts[-1]
    # Preserve leading zeros if present
    zero_len = len(last) - len(last.lstrip('0'))
    if zero_len < 1:
        try:
            num = int(last)
        except ValueError:
            return version
        new_last = str(num + 1)
    else:
        try:
            num = int(last.lstrip('0') or '0')
        except ValueError:
            return version
        new_num_str = str(num + 1)
        # Pad with zeros to maintain original width
        new_last = new_num_str.rjust(zero_len + len(new_num_str), '0')
    parts[-1] = new_last
    return '.'.join(parts)

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not version:
        return ""
    parts = version.split(".")
    widths = [len(p) for p in parts]
    nums = []
    for p in parts:
        if not p.isdigit():
            return version  # return unchanged if non-numeric part encountered
        nums.append(int(p))
    # Determine maximum values per part based on original width
    max_vals = [10 ** w - 1 for w in widths]
    # Increment from the last component
    carry = 1
    for i in range(len(nums) - 1, -1, -1):
        if carry == 0:
            break
        nums[i] += carry
        if nums[i] > max_vals[i]:
            nums[i] = 0
            carry = 1
        else:
            carry = 0
    if carry == 1:
        # Overflow beyond the first component, prepend a new component
        nums.insert(0, 1)
        widths.insert(0, 1)  # no leading zeros for the new component
    # Format each part with its original width, preserving leading zeros
    new_parts = []
    for num, w in zip(nums, widths):
        new_parts.append(str(num).zfill(w))
    return ".".join(new_parts)

def next_version(version):
    """Next version identifier following existing pattern.
    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    try:
        if version is None:
            return ""
        # Convert any non-string input to string and strip whitespace
        v_str = str(version).strip()
        if not v_str or not v_str.isdigit():
            return ""
        original_len = len(v_str)
        next_num = int(v_str) + 1
        next_str = str(next_num)
        # Preserve leading zeros if any were present
        if len(next_str) < original_len:
            next_str = next_str.zfill(original_len)
        return next_str
    except Exception:
        return ""

def next_version(version):
    """Next version identifier following existing pattern.

    Must deal with both zero-prefixed and non-zero prefixed versions.
    """
    if not isinstance(version, str):
        return ""
    version = version.strip()
    if not version:
        return ""
    parts = version.split('.')
    if not all(p.isdigit() for p in parts):
        # If not a simple numeric dotted version, return as is
        return version
    last = parts[-1]
    incremented = str(int(last) + 1)
    # Preserve leading zeros if length is unchanged, otherwise new length
    if len(incremented) < len(last):
        incremented = incremented.zfill(len(last))
    parts[-1] = incremented
    return '.'.join(parts)

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Ensure we have a root inventory to compare against.
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise ValueError("Root inventory not available or not a dictionary")

    self.different_digests = {}  # key: item, value: list of (version, digest) tuples

    for dir_name in version_dirs:
        # Construct the path to the inventory file for this version.
        inv_path = os.path.join(self.base_dir, dir_name, "inventory.json")

        # The inventory file must exist.
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file for version directory '{dir_name}'")

        # Load the inventory; it should be a mapping of item -> digest.
        try:
            with open(inv_path, "r", encoding="utf-8") as fh:
                inventory = json.load(fh)
        except Exception as exc:
            raise ValueError(f"Failed to read inventory from '{inv_path}': {exc}") from exc

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory at '{inv_path}' is not a dictionary")

        # Ensure the inventory contains all items from the root inventory.
        missing_items = set(self.root_inventory.keys()) - set(inventory.keys())
        if missing_items:
            raise ValueError(
                f"Inventory '{inv_path}' is missing items {sorted(missing_items)}"
            )

        # Check for digest mismatches and record them.
        for item, root_digest in self.root_inventory.items():
            version_digest = inventory.get(item)
            if version_digest is None:
                # This shouldn't happen because of the previous check, but guard anyway.
                continue
            if version_digest != root_digest:
                self.different_digests.setdefault(item, []).append(
                    (dir_name, version_digest)
                )

    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os, json

    # Basic validation of input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        # Nothing to validate, still record an empty diff
        self.inventory_differences = {}
        return

    # The root inventory should already be loaded at self.root_inventory.
    if not hasattr(self, "root_inventory") or not isinstance(self.root_inventory, dict):
        raise AttributeError("root_inventory attribute missing or not a dict")

    differences = {}
    cumulative = {}

    for ver_dir in version_dirs:
        inv_path = os.path.join(ver_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            raise FileNotFoundError(f"Missing inventory file in version directory '{ver_dir}'")

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inventory = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory from '{inv_path}': {exc}")

        if not isinstance(inventory, dict):
            raise ValueError(f"Inventory in '{ver_dir}' must be a mapping of file -> digest")

        # Ensure that the current inventory is cumulative up to this point
        missing_keys = set(cumulative) - set(inventory)
        if missing_keys:
            raise ValueError(
                f"Inventory in '{ver_dir}' is missing keys from previous versions: "
                f"{sorted(missing_keys)}"
            )
        cumulative.update(inventory)

        # Record any digest that differs from the root inventory
        for file_path, digest in inventory.items():
            root_digest = self.root_inventory.get(file_path)
            if root_digest is not None and root_digest != digest:
                differences.setdefault(file_path, set()).add(digest)

    self.inventory_differences = differences
    # For convenience, we can also store a summary of cumulative inventory
    self.cumulative_inventory = cumulative
    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    import os

    # Basic input validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")
    if not version_dirs:
        # Nothing to verify
        return self

    # Helper to parse an inventory file (simple key:hash per line)
    def _parse_inventory(path):
        inv = {}
        with open(path, encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith("#"):
                    continue
                if ":" not in line:
                    continue
                key, val = line.split(":", 1)
                inv[key.strip()] = val.strip()
        return inv

    # Ensure root inventory exists, it should be in self.root_inventory or read from file
    if getattr(self, "root_inventory", None) is None:
        root_inv_path = os.path.join(self.base_dir, "inventory.txt")
        if not os.path.isfile(root_inv_path):
            raise FileNotFoundError(f"Root inventory file missing at {root_inv_path}")
        self.root_inventory = _parse_inventory(root_inv_path)

    root_inventory = self.root_inventory

    # Will store tuples of (version_dir, key, expected_digest, actual_digest)
    self._different_digests = []

    for idx, dir_name in enumerate(version_dirs, start=1):
        ver_path = os.path.join(self.base_dir, dir_name)
        if not os.path.isdir(ver_path):
            raise FileNotFoundError(f"Version directory '{dir_name}' does not exist at {ver_path}")

        inv_file = os.path.join(ver_path, "inventory.txt")
        if not os.path.isfile(inv_file):
            raise FileNotFoundError(f"Missing inventory in version directory '{dir_name}'")

        try:
            inv = _parse_inventory(inv_file)
        except Exception as e:
            raise ValueError(f"Failed to parse inventory in '{dir_name}': {e}") from e

        # Each version must contain at least all items up to this point
        # (i.e., all from the root inventory)
        missing = set(root_inventory) - set(inv)
        if missing:
            raise ValueError(f"Inventory in '{dir_name}' is missing entries: {', '.join(sorted(missing))}")

        # Record any digest mismatches for later validation
        for key, root_hash in root_inventory.items():
            if key in inv and inv[key] != root_hash:
                self._different_digests.append((dir_name, key, root_hash, inv[key]))

        # Also store the parsed inventory for potential future use
        setattr(self, f"_inventory_{dir_name}", inv)

    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic type validation
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError('`version_dirs` must be a list or tuple of directory names')
    # Ensure we have something to compare against
    root_inv = getattr(self, 'root_inventory', None)
    if root_inv is None or not isinstance(root_inv, dict):
        raise AttributeError('`self.root_inventory` must be a dict containing the expected digests')

    # Prepare container for differing digest records
    self.inventory_differences = {}

    for ver_dir in version_dirs:
        if not isinstance(ver_dir, str):
            raise TypeError('each entry in `version_dirs` must be a string representing a directory name')
        inv_path = os.path.join(ver_dir, 'inventory.json')
        if not os.path.exists(inv_path):
            raise ValueError(f'Inventory file missing for version directory "{ver_dir}"')
        try:
            with open(inv_path, 'r', encoding='utf-8') as fp:
                inv = json.load(fp)
        except Exception as exc:
            raise ValueError(f'Failed to load JSON inventory from "{inv_path}": {exc}') from exc
        if not isinstance(inv, dict):
            raise ValueError(f'Inventory in "{inv_path}" must be a JSON object (dict)')

        # Record any digests that differ from the root inventory
        diff = {}
        for path, digest in inv.items():
            root_digest = root_inv.get(path)
            if root_digest is None:
                diff[path] = ('<missing in root>', digest)
            elif root_digest != digest:
                diff[path] = (root_digest, digest)
        if diff:
            self.inventory_differences[ver_dir] = diff

    return self

def validate_version_inventories(self, version_dirs):
    """Each version SHOULD have an inventory up to that point.

    Also keep a record of any content digests different from those in the root inventory
    so that we can also check them when validating the content.

    version_dirs is an array of version directory names and is assumed to be in
    version sequence (1, 2, 3...).
    """
    # Basic validation of input
    if not isinstance(version_dirs, (list, tuple)):
        raise TypeError("version_dirs must be a list or tuple of directory names")

    # Prepare containers for tracking state
    self._missing_inventories = []
    # Map of component -> dict of {version: {'root_digest':..., 'current_digest':...}}
    self._differing_digests = {}

    # Load the root inventory once if available
    root_inventory = None
    root_path = getattr(self, 'root_inventory_path', None)
    if root_path and isinstance(root_path, str):
        try:
            with open(root_path, "r", encoding="utf-8") as f:
                root_inventory = json.load(f)
        except Exception:
            # If root inventory cannot be read, leave as None; differing check will skip
            root_inventory = None

    for idx, ver_dir in enumerate(version_dirs):
        # The inventory file is expected to be `inventory.json` inside each version dir
        inv_path = os.path.join(ver_dir, "inventory.json")
        if not os.path.isfile(inv_path):
            self._missing_inventories.append(ver_dir)
            continue

        try:
            with open(inv_path, "r", encoding="utf-8") as f:
                inv = json.load(f)
        except Exception as exc:
            raise ValueError(f"Failed to load inventory at {inv_path}: {exc}") from exc

        # Ensure the inventory contains a components mapping
        components = inv.get("components")
        if not isinstance(components, dict):
            raise ValueError(
                f"Inventory at {inv_path} must contain a 'components' dict"
            )

        # Compare each component's digest with the root inventory (if available)
        if root_inventory:
            root_components = root_inventory.get("components", {})
            for comp_name, comp_meta in components.items():
                if not isinstance(comp_meta, dict):
                    continue  # Skip malformed entries
                curr_digest = comp_meta.get("digest")
                if curr_digest is None:
                    continue
                root_meta = root_components.get(comp_name)
                if not root_meta:
                    continue
                root_digest = root_meta.get("digest")
                if root_digest and root_digest != curr_digest:
                    diff = self._differing_digests.setdefault(comp_name, {})
                    diff.setdefault(
                        ver_dir,
                        {"root_digest": root_digest, "current_digest": curr_digest},
                    )

    if self._missing_inventories:
        missing = ", ".join(self._missing_inventories)
        raise ValueError(f"Missing inventory files in version directories: {missing}")

    # Return self to allow chaining if desired
    return self

def find_path_type(path):
    """Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    # Validate path existence
    try:
        if not os.path.exists(path):
            return f'path does not exist: {path}'
    except OSError as exc:
        return f'cannot access path: {path}. Error: {exc}'

    # File case
    try:
        if os.path.isfile(path):
            return 'file'
    except OSError as exc:
        return f'cannot determine if file: {path}. Error: {exc}'

    # Directory case
    try:
        if os.path.isdir(path):
            # List entries once
            try:
                entries = os.listdir(path)
            except PermissionError as exc:
                return f'permission denied listing {path}: {exc}'
            except OSError as exc:
                return f'error listing {path}: {exc}'

            # Check for namaste files in the current directory
            namaste_in_dir = False
            for entry in entries:
                full = os.path.join(path, entry)
                if os.path.isfile(full) and entry.startswith('0='):
                    namaste_in_dir = True
                    break

            # Check for subdirectories that contain a namaste file
            subdirs_containing_namaste = []
            for entry in entries:
                full = os.path.join(path, entry)
                if os.path.isdir(full):
                    # Quick scan; only look one level deep
                    try:
                        sub_entries = os.listdir(full)
                    except PermissionError:
                        continue
                    except OSError:
                        continue
                    for sub_entry in sub_entries:
                        sub_full = os.path.join(full, sub_entry)
                        if os.path.isfile(sub_full) and sub_entry.startswith('0='):
                            subdirs_containing_namaste.append(entry)
                            break

            # Determine type
            if namaste_in_dir and not subdirs_containing_namaste:
                return 'object'
            if subdirs_containing_namaste:
                return 'root'

            return 'unknown directory type'
    except OSError as exc:
        return f'error processing {path}. Error: {exc}'

    return f'unknown path type: {path}'

def find_path_type(path):
    """
    Return a string indicating the type of thing at the given path.

    Return values:
        'root'   - looks like an OCFL Storage Root
        'object' - looks like an OCFL Object
        'file'   - a file, might be an inventory
        other string explains error description

    Looks only at "0=*" Namaste files to determine the directory type.
    """
    import os
    if not os.path.exists(path):
        return 'path does not exist'

    if os.path.isfile(path):
        return 'file'

    if os.path.isdir(path):
        try:
            entries = os.listdir(path)
        except Exception as e:
            return f'error accessing directory: {e}'

        # Look for Namaste files that start with "0="
        for name in entries:
            if name.startswith('0='):
                return 'root'

        # Heuristic for an object: presence of inventory or revisions folder
        if 'inventory.json' in entries or 'inventory' in entries:
            return 'object'
        if 'revisions' in entries:
            return 'object'
        if 'objects' in entries:
            return 'object'

        return 'unknown directory type'

    return 'path is neither file nor directory'

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if not isinstance(bug_ids, (list, tuple, set)):
        raise TypeError("bug_ids must be a list, tuple or set")
    if not bug_ids:
        return params
    try:
        ids_str = ",".join(str(int(bid)) for bid in bug_ids)
    except Exception as exc:
        raise ValueError("All bug_ids must be convertible to integers") from exc
    updated = dict(params)
    updated["ids"] = ids_str
    return updated

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    # Ensure params is a dictionary
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise ValueError("params must be a dict")

    # If no IDs were supplied, nothing to amend
    if bug_ids is None:
        return params

    # Normalize bug_ids to an iterable of stringification-aware elements
    if isinstance(bug_ids, (list, tuple)):
        ids_iter = bug_ids
    elif isinstance(bug_ids, str):
        # Allow a comma‑separated string of IDs
        ids_iter = [i.strip() for i in bug_ids.split(',') if i.strip()]
    else:
        # Treat single element (int, str, etc.) as a list
        ids_iter = [bug_ids]

    try:
        id_list = [str(i) for i in ids_iter]
    except Exception as exc:
        raise ValueError("bug_ids must contain items that can be converted to strings") from exc

    # Join into comma separated list expected by Bugzilla
    params['id'] = ','.join(id_list) if id_list else None
    return params

def amend_bzparams(self, params, bug_ids):
    """Amend the Bugzilla params"""
    if params is None:
        params = {}
    if not isinstance(params, dict):
        raise TypeError("params must be a dictionary")
    if bug_ids is None:
        return params
    # Create a list of string representations for the ids
    if isinstance(bug_ids, int):
        id_list = [str(bug_ids)]
    elif isinstance(bug_ids, str):
        id_list = [bug_ids]
    else:
        try:
            id_list = [str(b) for b in bug_ids if b is not None]
        except Exception as exc:
            raise TypeError("bug_ids must be an int, str, or iterable of ids") from exc
    id_str = ','.join(id_list)
    if id_str:
        params['ids'] = id_str
    return params

def deep_merge_nodes(nodes):
    '''
    Given a nested borgmatic configuration data structure as a list of tuples in the form of:

        (
            ruamel.yaml.nodes.ScalarNode as a key,
            ruamel.yaml.nodes.MappingNode or other Node as a value,
        ),

    ... deep merge any node values corresponding to duplicate keys and return the result. If
    there are colliding keys with non-MappingNode values (e.g., integers or strings), the last
    of the values wins.

    For instance, given node values of:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='7')
                    ),
                ]),
            ),
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    ... the returned result would be:

        [
            (
                ScalarNode(tag='tag:yaml.org,2002:str', value='retention'),
                MappingNode(tag='tag:yaml.org,2002:map', value=[
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_hourly'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='24')
                    ),
                    (
                        ScalarNode(tag='tag:yaml.org,2002:str', value='keep_daily'),
                        ScalarNode(tag='tag:yaml.org,2002:int', value='5')
                    ),
                ]),
            ),
        ]

    The purpose of deep merging like this is to support, for instance, merging one borgmatic
    configuration file into another for reuse, such that a configuration section ("retention",
    etc.) does not completely replace the corresponding section in a merged file.
    '''
    # Helper to merge two MappingNode values
    def _merge_mapping_nodes(node1, node2):
        """Recursively merge two MappingNode objects."""
        # Merge the list of key/value pair tuples in node1 and node2
        merged_pairs = deep_merge_nodes(node1.value + node2.value)
        return MappingNode(node1.tag, merged_pairs)

    result_map = {}
    order_keys = []
    key_obj_map = {}

    for key, val in nodes:
        try:
            key_id = key.value
        except AttributeError:
            key_id = str(key)

        if key_id not in key_obj_map:
            key_obj_map[key_id] = key
            order_keys.append(key_id)

        if key_id in result_map:
            existing_val = result_map[key_id]
            # If both values are MappingNode, deep merge
            if isinstance(existing_val, MappingNode) and isinstance(val, MappingNode):
                merged_val = _merge_mapping_nodes(existing_val, val)
                result_map[key_id] = merged_val
            else:
                # For non-mapping or mismatched types, the last value wins
                result_map[key_id] = val
        else:
            result_map[key_id] = val

    # Reconstruct list preserving original first-occurrence order
