    The script is generated by introspecting the borgmatic Click
    command tree. If Click's built‑in completion helper is not
    available, a simple fallback script is returned.
    '''
    import importlib
    import click

    # Try to load the top‑level borgmatic command
    try:
        borg_mod = importlib.import_module('borgmatic')
    except ImportError:
        try:
