    unknown_sets = []

    for name, parser in subparsers.items():
        try:
            namespace, unknown = parser.parse_known_args(args_list)
            parsed_results[name] = namespace
            unknown_sets.append(set(unknown))
        except Exception:
            # If parsing fails for this subparser, treat it as consuming nothing
            parsed_results[name] = None
            unknown_sets.append(set())

