    seen.discard(cls)
    return seen

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class (type), got {type(cls)!r}")
    seen = set()
    queue = {cls}
    while queue:
        current = queue.pop()
        seen.add(current)
        for sub in current.__subclasses__():
            if sub not in seen:
                queue.add(sub)
    seen.discard(cls)
    return seen

