        cmd = ["unzip", "-q", str(archive), "-d", str(dest_dir)]
    else:
        raise ValueError(f"Unsupported archive type for file {archive_path}")

    try:
        subprocess.run(cmd, check=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
    except subprocess.CalledProcessError as exc:
        raise RuntimeError(f"Extraction failed for {archive_path}: {exc.stderr.decode().strip()}") from exc

    # Return file:// URL to the extracted repository
    return dest_dir.resolve().as_uri()

def prepare_repository_from_archive(
    archive_path: str,
    filename: Optional[str] = None,
    tmp_path: Union[PosixPath, str] = "/tmp",
) -> str:
    """Given an existing archive_path, uncompress it.
    Returns a file repo url which can be used as origin url.

    This does not deal with the case where the archive passed along does not exist.
    """
    # Ensure the archive exists
    if not os.path.exists(archive_path):
        raise FileNotFoundError(f"Archive {archive_path!r} does not exist")

    # Convert tmp_path to string if it is a Path
    if isinstance(tmp_path, PosixPath):
        tmp_path = str(tmp_path)

    # Determine extraction directory
    if filename:
        extract_dir = os.path.join(tmp_path, filename)
    else:
        # Strip common archive extensions
        base = os.path.basename(archive_path)
        for ext in ('.tar.gz', '.tgz', '.tar.bz2', '.tbz2', '.zip', '.tar'):
            if base.endswith(ext):
                base = base[: -len(ext)]
                break
        else:
            # fallback: remove last extension
            base = os.path.splitext(base)[0]
        extract_dir = os.path.join(tmp_path, base)

    # Create the extraction directory
    try:
        os.makedirs(extract_dir, exist_ok=True)
    except OSError as e:
        raise RuntimeError(f"Could not create extraction directory {extract_dir!r}: {e}") from e

    # Decide extraction command based on file extension
    lower_path = archive_path.lower()
    if lower_path.endswith('.zip'):
        cmd = ['unzip', '-q', archive_path, '-d', extract_dir]
    elif lower_path.endswith(('.tar.gz', '.tgz', '.tar.bz2', '.tbz2')):
        # use tar with appropriate flags
        if lower_path.endswith(('.tar.gz', '.tgz')):
            flag = 'zxf'
        else:
            flag = 'jxf'
        cmd = ['tar', f'-{flag}', archive_path, '-C', extract_dir]
    elif lower_path.endswith('.tar'):
        cmd = ['tar', '-xf', archive_path, '-C', extract_dir]
    else:
        raise ValueError(f"Unsupported archive format for {archive_path!r}")

    # Run extraction
    try:
        result = subprocess.run(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, check=True, text=True)
    except subprocess.CalledProcessError as e:
        raise RuntimeError(f"Extraction failed: {e.stderr.strip()}") from e

    # Return the file URL
    return f"file://{extract_dir}"

