def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    # Handle None or "always"
    if frequency is None:
        return None
    if not isinstance(frequency, str):
        raise ValueError('Frequency must be a string or None')
    freq = frequency.strip()
    if freq.lower() == 'always':
        return None

    # Split into two parts: number and unit
    parts = freq.split()
    if len(parts) != 2:
        raise ValueError(f"Invalid frequency format: '{frequency}'")

    num_part, unit_part = parts
    if not num_part.isdigit():
        raise ValueError(f"Frequency number is not an integer: '{num_part}'")
    number = int(num_part)
    unit = unit_part.lower()

    # Map unit to timedelta keyword
    if unit in ('week', 'weeks'):
        return datetime.timedelta(weeks=number)
    elif unit in ('day', 'days'):
        return datetime.timedelta(days=number)
    elif unit in ('hour', 'hours'):
        return datetime.timedelta(hours=number)
    elif unit in ('minute', 'minutes'):
        return datetime.timedelta(minutes=number)
    elif unit in ('second', 'seconds'):
        return datetime.timedelta(seconds=number)
    elif unit in ('month', 'months'):
        # Approximate a month as 30 days
        return datetime.timedelta(days=number * 30)
    elif unit in ('year', 'years'):
        # Approximate a year as 365 days
        return datetime.timedelta(days=number * 365)

    raise ValueError(f"Unsupported time unit: '{unit}'")

def parse_frequency(frequency):
    """
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    """
    if frequency is None:
        return None
    if isinstance(frequency, str):
        freq_str = frequency.strip()
    else:
        raise ValueError("frequency must be a string, None, or 'always'")
    if not freq_str:
        raise ValueError("empty frequency string")
    if freq_str.lower() == "always":
        return None

    import re

    match = re.match(r"^\s*(?P<num>\d+)\s*(?P<unit>\w+)\s*$", freq_str, re.IGNORECASE)
    if not match:
        raise ValueError(f"Cannot parse frequency string: '{frequency}'")
    num_str = match.group("num")
    unit_str = match.group("unit").lower()

    try:
        value = int(num_str)
    except Exception as exc:
        raise ValueError(f"Invalid numeric value in frequency string: '{num_str}'") from exc

    unit_map = {
        "second": "seconds",
        "seconds": "seconds",
        "minute": "minutes",
        "minutes": "minutes",
        "hour": "hours",
        "hours": "hours",
        "day": "days",
        "days": "days",
        "week": "weeks",
        "weeks": "weeks",
    }

    if unit_str not in unit_map:
        raise ValueError(f"Unsupported time unit '{unit_str}' in frequency string")

    kwargs = {unit_map[unit_str]: value}
    return datetime.timedelta(**kwargs)

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False
    host = host.strip()
    try:
        for family, socktype, proto, canonname, sockaddr in socket.getaddrinfo(host, None):
            if family == socket.AF_INET:
                ip = sockaddr[0]
                # IPv4 loopback starts with 127.
                if ip.startswith("127."):
                    return True
            elif family == socket.AF_INET6:
                ip = sockaddr[0]
                # Remove zone index if present
                if "%" in ip:
                    ip = ip.split("%", 1)[0]
                if ip == "::1":
                    return True
    except socket.gaierror:
        return False
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Quick check for common localhost identifiers
    if host is None:
        return False
    host_str = str(host).strip()
    if host_str in ("localhost", "127.0.0.1", "::1"):
        return True

    try:
        # Resolve the host to all addresses (IPv4 and IPv6)
        addrs = socket.getaddrinfo(host_str, None, 0, 0, socket.IPPROTO_TCP)
    except socket.gaierror:
        # If the name cannot be resolved, it's not localhost
        return False

    # Check each resolved address; if any is loopback, return True
    for entry in addrs:
        try:
            addr = entry[4][0]
            if addr in ("127.0.0.1", "::1"):
                return True
        except Exception:
            continue

    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    if not host:
        return False

    try:
        # Resolve the host to addresses; use AF_UNSPEC to get any
        addresses = socket.getaddrinfo(host, 0, 0, 0, 0, 0)
    except socket.gaierror:
        # If the host cannot be resolved, assume it is not localhost
        return False
    except Exception:
        # Catch any unexpected errors but still err on the side of safety
        return False

    for family, _, _, _, sockaddr in addresses:
        # sockaddr[0] holds the IP address as a string
        ip = sockaddr[0]
        if family == socket.AF_INET:
            # IPv4 loopback: any address in the 127.0.0.0/8 block
            if ip.startswith("127.") and ip != "0.0.0.0":
                return True
        elif family == socket.AF_INET6:
            # IPv6 loopback: ::1 (may include zone index, strip it)
            ip = ip.split("%")[0]  # remove zone index if present
            if ip == "::1":
                return True
    # No loopback addresses were found
    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    try:
        # Resolve the host to get all related addresses
        infos = socket.getaddrinfo(host, None)
    except socket.gaierror:
        # Host cannot be resolved; not local
        return False

    for info in infos:
        family, _socktype, _proto, _canonname, sockaddr = info
        ip = sockaddr[0]

        if family == socket.AF_INET:
            try:
                # IPv4: loopback is 127.0.0.0/8
                if socket.inet_aton(ip)[0] == 127:
                    return True
            except OSError:
                # invalid IPv4 string, skip
                continue
        elif family == socket.AF_INET6:
            # IPv6 loopback is ::1
            try:
                if socket.inet_pton(socket.AF_INET6, ip) == socket.inet_pton(socket.AF_INET6, "::1"):
                    return True
            except AttributeError:
                # Fallback for systems without inet_pton
                if ip == "::1":
                    return True
            except OSError:
                continue

    return False

def is_local(host):
    """
    Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    import socket
    try:
        import ipaddress
    except ImportError:
        # ipaddress is part of the standard library on Python 3.3+, but fall back
        # if not available by checking loopback ranges manually.
        ipaddress = None

    try:
        addrs = socket.getaddrinfo(host, None)
    except socket.gaierror:
        return False

    for family, _, _, _, sockaddr in addrs:
        ip = sockaddr[0]
        try:
            if ipaddress:
                if ipaddress.ip_address(ip).is_loopback:
                    return True
            else:
                # Manual check for IPv4 and IPv6 loopback
                if family == socket.AF_INET:
                    if ip.startswith("127."):
                        return True
                elif family == socket.AF_INET6:
                    if ip == "::1":
                        return True
        except Exception:
            # Ignore invalid IP parsing
            continue
    return False

def is_gitbash():
    """
    returns True if you run in a Windows gitbash

    :return: True if gitbash
    """
    try:
        # Windows platform check
        if os.name != 'nt':
            return False
        # Git Bash sets the MSYSTEM environment variable on Windows
        msystem = os.environ.get('MSYSTEM', '')
        if msystem.upper().startswith(('MINGW', 'MSYS')):
            # Additional sanity: typical Git Bash also has 'OSTYPE' containing 'msys'
            if os.environ.get('OSTYPE', '').lower().startswith('msys'):
                return True
        return False
    except Exception:
        return False

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    # Validate input types
    if not isinstance(config_filename, str):
        raise TypeError("config_filename must be a string")
    if not isinstance(rendered_config, str):
        rendered_config = str(rendered_config)
    if not isinstance(mode, int):
        raise TypeError("mode must be an integer")
    if not isinstance(overwrite, bool):
        raise TypeError("overwrite must be a boolean")

    config_path = os.path.expanduser(config_filename)

    # Abort if file exists and overwrite not requested
    if os.path.isfile(config_path) and not overwrite:
        return

    try:
        dir_name = os.path.dirname(config_path)
        if dir_name:
            os.makedirs(dir_name, exist_ok=True)

        with open(config_path, "w", encoding="utf-8") as f:
            f.write(rendered_config)

        os.chmod(config_path, mode)
    except OSError as exc:
        # Re-raise to allow caller to handle detailed exceptions
        raise OSError(f"Failed to write configuration to '{config_path}': {exc}") from exc

def write_configuration(config_filename, rendered_config, mode=0o600, overwrite=False):
    '''
    Given a target config filename and rendered config YAML, write it out to file. Create any
    containing directories as needed. But if the file already exists and overwrite is False,
    abort before writing anything.
    '''
    config_path = os.path.expanduser(config_filename)
    if not overwrite and os.path.isfile(config_path):
        return
    dir_name = os.path.dirname(config_path)
    if dir_name and not os.path.isdir(dir_name):
        try:
            os.makedirs(dir_name, exist_ok=True)
        except Exception:
            if not os.path.isdir(dir_name):
                raise
    with open(config_path, 'w') as f:
        f.write(rendered_config)
    os.chmod(config_path, mode)

def oneline(script, seperator=" && "):
    """
    converts a script to one line command.
    THis is useful to run a single ssh command and pass a one line script.

    :param script:
    :return:
    """
    if script is None:
        return ''
    if isinstance(script, list):
        script = '\n'.join(script)
    elif not isinstance(script, str):
        raise TypeError('script must be a string or a list of strings')
    # Dedent multiline script and strip outer whitespace
    script = textwrap.dedent(script).strip()
    if not script:
        return ''
    lines = []
    for line in script.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        lines.append(line)
    if not lines:
        return ''
    sep = str(seperator)
    return sep.join(lines)

def _resolve_string(matcher):
    '''Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.'''
    # Retrieve the variable name from the matcher
    try:
        name = matcher.name
    except AttributeError:
        raise ValueError("Matcher object must have a 'name' attribute") from None

    # If the variable exists in the environment, return its value
    if name in os.environ:
        return os.environ[name]

    # If the matcher has a default value defined, use that
    if hasattr(matcher, 'default'):
        default = matcher.default
        if default is not None:
            return default

    # No value found and no default provided – raise an error
    raise KeyError(f"Environment variable '{name}' not found and no default provided")

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern"""
    if pattern is None:
        return None
    # Already compiled pattern
    if isinstance(pattern, re.Pattern):
        return pattern
    if hasattr(pattern, "pattern"):
        return pattern
    if isinstance(pattern, (bytes, bytearray)):
        try:
            return re.compile(pattern)
        except re.error as e:
            raise ValueError(f"Invalid regex pattern: {pattern}") from e
    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        try:
            return re.compile(pattern)
        except re.error as e:
            raise ValueError(f"Invalid regex pattern: {pattern}") from e
    raise TypeError(f"Unsupported pattern type: {type(pattern).__name__}")

def get_pattern(pattern, strip=True):
    """
    This method converts the given string to regex pattern
    """
    # Handle None input
    if pattern is None:
        return None

    # Already a compiled pattern (Python 3.7+)
    if isinstance(pattern, re.Pattern):
        return pattern

    # For older Python versions, the compiled type is re._pattern_type
    if hasattr(re, "_pattern_type") and isinstance(pattern, re._pattern_type):
        return pattern

    # Ensure input is a string
    if not isinstance(pattern, str):
        raise TypeError("pattern must be a string or a compiled regex object")

    # Optionally strip surrounding whitespace
    if strip:
        pattern = pattern.strip()

    # Compile the string into a regex pattern
    try:
        return re.compile(pattern)
    except re.error as exc:
        raise ValueError(f"Invalid regex pattern: {exc}") from exc

def get_pattern(pattern, strip=True):
    """This method converts the given string to regex pattern.

    If ``pattern`` is a string it will be stripped of leading/trailing whitespace
    (if ``strip=True``) and compiled into a :class:`re.Pattern` object.  If
    ``pattern`` is already a compiled regex the object is returned unchanged.
    Other types raise a :class:`TypeError`.  ``None`` is returned unchanged.
    """
    if pattern is None:
        return None

    if isinstance(pattern, str):
        if strip:
            pattern = pattern.strip()
        return re.compile(pattern)

    # Determine the regex pattern type in a version‑agnostic way
    try:
        pattern_type = re.Pattern  # Python 3.7+
    except AttributeError:
        pattern_type = type(re.compile(''))

    if isinstance(pattern, pattern_type):
        return pattern

    raise TypeError(f"Invalid pattern type: {type(pattern).__name__}")

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Normalize inputs
    if not isinstance(commands, (list, str)):
        raise TypeError("commands must be a list or string")
    if isinstance(commands, str):
        commands = [commands]
    else:
        commands = list(commands)  # copy to avoid modifying caller list

    if isinstance(args, str):
        args = [args]
    elif not isinstance(args, list):
        raise TypeError("args must be a list or string")
    else:
        args = list(args)

    # Validate that each command is a string
    for cmd in commands:
        if not isinstance(cmd, str):
            raise TypeError(f"each command must be a string, got {type(cmd).__name__}")

    # Build stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else None

    results = []
    for cmd in commands:
        full_cmd = [cmd] + args
        if verbose:
            print("Running command:", " ".join(full_cmd))
        try:
            result = subprocess.run(
                full_cmd,
                cwd=cwd,
                env=env,
                stderr=stderr_target,
                stdout=None,  # Let subprocess inherit stdout
                check=True
            )
            results.append(result)
        except subprocess.CalledProcessError as exc:
            # Enrich the error message with the command that failed
            err_msg = f"Command '{cmd}' failed with exit code {exc.returncode}"
            raise RuntimeError(err_msg) from exc

    return results

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""

    # Validate and normalize commands
    if isinstance(commands, str):
        commands_list = [commands]
    else:
        if not isinstance(commands, list):
            raise TypeError("commands must be a list of strings or a single string")
        if any(not isinstance(c, str) for c in commands):
            raise TypeError("all elements of commands must be strings")
        commands_list = commands

    # Validate and normalize args
    if args is None:
        args_list = []
    elif isinstance(args, str):
        args_list = [args]
    elif isinstance(args, list):
        if any(not isinstance(a, str) for a in args):
            raise TypeError("all elements of args must be strings")
        args_list = args
    else:
        raise TypeError("args must be a list of strings, a single string, or None")

    # Build full command
    full_cmd = commands_list + args_list
    if not full_cmd:
        raise ValueError("no command specified")

    # Verify cwd exists if given
    if cwd is not None:
        import os
        if not os.path.isdir(cwd):
            raise FileNotFoundError(f"cwd path does not exist: {cwd}")

    # Run the command
    try:
        stdout_option = subprocess.PIPE
        stderr_option = subprocess.DEVNULL if hide_stderr else subprocess.PIPE
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=stdout_option,
            stderr=stderr_option,
            text=True,
            check=True
        )
    except subprocess.CalledProcessError as e:
        msg = f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}"
        if e.stdout:
            msg += f"\nstdout:\n{e.stdout}"
        if e.stderr and not hide_stderr:
            msg += f"\nstderr:\n{e.stderr}"
        raise RuntimeError(msg) from e
    except OSError as e:
        raise RuntimeError(f"Failed to execute command '{' '.join(full_cmd)}': {e}") from e

    # Verbose output
    if verbose:
        print(f"Executed command: {' '.join(full_cmd)}")
        print(f"Return code: {result.returncode}")
        if result.stdout:
            print("Standard Output:")
            print(result.stdout)
        if result.stderr and not hide_stderr:
            print("Standard Error:")
            print(result.stderr)

    return result

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    if not commands:
        raise ValueError("commands parameter cannot be empty")
    # Normalize commands to a list of strings
    if isinstance(commands, str):
        cmd_list = [commands]
    else:
        cmd_list = [str(c) for c in commands]
    # Append any additional arguments
    if args:
        if isinstance(args, (list, tuple)):
            cmd_list += [str(a) for a in args]
        else:
            cmd_list.append(str(args))
    # Verbose output
    if verbose:
        print(f"Running command: {' '.join(cmd_list)}")
    # Determine stderr handling
    stderr_option = subprocess.DEVNULL if hide_stderr else None
    try:
        result = subprocess.run(
            cmd_list,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_option,
            check=False,
            text=True
        )
        return result.stdout
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command: {e}") from e

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    # Build the command list
    if isinstance(commands, str):
        # Split the command string respecting quotes
        from shlex import split as shlex_split
        command_list = shlex_split(commands.strip())
    elif isinstance(commands, (list, tuple)):
        command_list = list(commands)
    else:
        raise TypeError("commands must be a string, list, or tuple")

    if args is None:
        args = []
    if not isinstance(args, (list, tuple)):
        raise TypeError("args must be a list or tuple")

    full_cmd = command_list + list(args)

    if verbose:
        print(f"[run_command] Executing: {' '.join(full_cmd)}")

    # Determine stderr handling
    stderr_target = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            env=env,
            stdout=subprocess.PIPE,
            stderr=stderr_target,
            text=True,
            check=True
        )
        return result
    except subprocess.CalledProcessError as e:
        raise RuntimeError(
            f"Command '{' '.join(full_cmd)}' failed with exit code {e.returncode}"
        ) from e
    except Exception as e:
        raise RuntimeError(
            f"Error running command '{' '.join(full_cmd)}': {e}"
        ) from e

