def gaussian(x):
    """
    Gaussian centered around 0.2 with a sigma of 0.1.
    """
    try:
        arr = np.asarray(x)
    except Exception as exc:
        raise TypeError(f"Input {x} could not be converted to a NumPy array: {exc}") from exc

    mean = 0.2
    sigma = 0.1

    if sigma <= 0:
        raise ValueError(f"Standard deviation sigma must be positive; got {sigma}")

    coeff = 1.0 / (sigma * np.sqrt(2 * np.pi))
    exponent = np.exp(-((arr - mean) ** 2) / (2 * sigma ** 2))
    result = coeff * exponent

    # Preserve the original data type if possible
    if np.isscalar(x):
        return result.item()
    return result

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    """
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return a tuple of:
        - dict of configuration filename to corresponding parsed configuration,
        - sequence of logging.LogRecord instances containing any parse errors.
    """
    if overrides is None:
        overrides = {}

    import os
    import logging

    def _resolve_env(value):
        """Recursively replace ${VAR} placeholders with environment variables."""
        import re
        if isinstance(value, dict):
            return {k: _resolve_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_resolve_env(v) for v in value]
        elif isinstance(value, str):
            pattern = r'\$\{([^}]+)\}'
            def repl(match):
                return os.getenv(match.group(1), match.group(0))
            return re.sub(pattern, repl, value)
        return value

    configs = {}
    errors = []

    for fname in config_filenames:
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
            _, ext = os.path.splitext(fname)
            ext = ext.lower()
            parsed = None
            if ext in ('.yaml', '.yml'):
                import yaml
                parsed = yaml.safe_load(raw) or {}
            elif ext == '.json':
                import json
                parsed = json.loads(raw)
            elif ext == '.toml':
                import toml
                parsed = toml.loads(raw)
            elif ext == '.ini':
                import configparser
                from io import StringIO
                cp = configparser.ConfigParser()
                cp.read_file(StringIO(raw))
                parsed = {s: dict(cp.items(s)) for s in cp.sections()}
            else:
                raise ValueError(f"Unsupported file extension: {ext}")

            if resolve_env:
                parsed = _resolve_env(parsed)

            # Apply overrides, with overrides taking precedence
            merged = parsed.copy()
            merged.update(overrides)
            configs[fname] = merged

        except Exception as exc:
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f"Failed to parse config '{fname}': {exc}",
                args=(),
                exc_info=None
            )
            errors.append(record)

    return configs, errors

def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import os
    import sys
    configs = {}
