    def _expand_env(val):
        if isinstance(val, str):
            try:
                return os.path.expandvars(val)
            except Exception as e:
                # Log expansion error and return original
                record = logging.LogRecord(
                    name=logger.name,
                    level=logging.WARNING,
                    pathname=__file__,
                    lineno=0,
                    msg=f'Error expanding env vars in value "{val}": {e}',
                    args=(),
                    exc_info=None
                )
                error_records.append(record)
                return val
        elif isinstance(val, dict):
            return {k: _expand_env(v) for k, v in val.items()}
        elif isinstance(val, list):
            return [_expand_env(v) for v in val]
        else:
            return val

    for fname in config_filenames:
        if not os.path.exists(fname):
            record = logging.LogRecord(
                name=logger.name,
                level=logging.WARNING,
                pathname=__file__,
                lineno=0,
                msg=f'Configuration file not found: {fname}',
                args=(),
                exc_info=None
            )
            error_records.append(record)
            continue
        try:
            with open(fname, 'r') as f:
                raw = f.read()
            if fname.lower().endswith(('.toml', '.tml')):
                try:
                    import toml
                    config = toml.loads(raw)
                except Exception as e:
                    raise RuntimeError(f'Toml parsing error: {e}')
            elif fname.lower().endswith(('.yaml', '.yml')):
                try:
                    import yaml
                    config = yaml.safe_load(raw)
                except Exception as e:
                    raise RuntimeError(f'Yaml parsing error: {e}')
            elif fname.lower().endswith('.json'):
                import json
                config = json.loads(raw)
            else:
                # Assume ini-like
                import configparser
                parser = configparser.ConfigParser()
                parser.read_string(raw)
                config = {section: dict(parser.items(section)) for section in parser.sections()}
            # Apply overrides
            if overrides:
                if isinstance(config, dict):
                    config.update(overrides)
                else:
                    raise RuntimeError('Overrides provided but configuration is not a dict.')
            # Expand environment variables
            if resolve_env:
                config = _expand_env(config)
            configs[fname] = config
        except Exception as e:
            # Capture parse errors as LogRecord
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=__file__,
                lineno=0,
                msg=f'Failed to parse configuration file "{fname}": {e}',
                args=(),
                exc_info=None
            )
