def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os
    try:
        import yaml
    except Exception:
        yaml = None

    configs = {}
    error_records = []
    logger = logging.getLogger('load_configurations')

    def _expand_env(value):
        if isinstance(value, str):
            return os.path.expandvars(value)
        elif isinstance(value, dict):
            return {k: _expand_env(v) for k, v in value.items()}
        elif isinstance(value, list):
            return [_expand_env(v) for v in value]
        else:
            return value

    for filename in config_filenames:
        parsed = None
        try:
            with open(filename, 'r', encoding='utf-8') as f:
                content = f.read()
            # Attempt JSON parsing first
            try:
                parsed = json.loads(content)
            except json.JSONDecodeError:
                if yaml:
                    try:
                        parsed = yaml.safe_load(content)
                    except Exception as e:
                        # YAML parse error
                        raise ValueError(f"YAML parse error in {filename}: {e}") from e
                else:
                    raise ValueError(f"Cannot parse {filename}: unknown format and no YAML support")
        except Exception as e:
            # Record parse error as LogRecord
            record = logger.makeRecord(
                logger.name,
                logging.ERROR,
                filename,
                0,
                f"Failed to load configuration file '{filename}': {e}",
                None,
                None
            )
            error_records.append(record)
            configs[filename] = None
            continue

        # Apply overrides if any
        if overrides and filename in overrides and isinstance(parsed, dict):
            if isinstance(overrides[filename], dict):
                parsed.update(overrides[filename])
            else:
                # override value not dict; cannot merge
                pass

        # Resolve environment variables if requested
        if resolve_env and isinstance(parsed, dict):
            parsed = _expand_env(parsed)

        configs[filename] = parsed

    return configs, error_records

