def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    parsed_configs = {}
    errors = []

    def expand_env(obj):
        if isinstance(obj, dict):
            return {k: expand_env(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [expand_env(v) for v in obj]
        elif isinstance(obj, str) and resolve_env:
            return os.path.expandvars(obj)
        else:
            return obj

    for fname in config_filenames:
        try:
            if not os.path.isfile(fname):
                raise FileNotFoundError(f"Configuration file not found: {fname}")
            ext = os.path.splitext(fname)[1].lower()
            with open(fname, 'r', encoding='utf-8') as f:
                raw = f.read()
                if ext in ['.yaml', '.yml']:
                    conf = yaml.safe_load(raw) or {}
                elif ext == '.toml':
                    conf = toml.loads(raw) or {}
                elif ext == '.json':
                    conf = json.loads(raw) or {}
                else:
                    raise ValueError(f"Unsupported config file extension: {ext}")
            if isinstance(conf, dict) and overrides:
                # shallow merge: overrides take precedence
                conf = {**conf, **overrides}
            conf = expand_env(conf)
            parsed_configs[fname] = conf
        except Exception as exc:
            # Create a LogRecord with the exception details
            err_msg = f"Failed to load configuration '{fname}': {exc}"
            record = logging.LogRecord(
                name='config_loader',
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=err_msg,
                args=None,
                exc_info=exc
            )
            errors.append(record)

    return parsed_configs, errors

