@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        if protocol_version is not None and not isinstance(protocol_version, tuple):
            raise TypeError("protocol_version must be a tuple of integers or None")

        # Aggregate handlers from the class and all its bases
        handlers = {}
        for base in reversed(cls.__mro__):
            base_handlers = getattr(base, "_bolt_handlers", {})
            if isinstance(base_handlers, dict):
                handlers.update(base_handlers)

        if protocol_version is not None:
            # Return only the specific handler if it exists
            if protocol_version in handlers:
                return {protocol_version: handlers[protocol_version]}
            return {}

        # Return a shallow copy to prevent accidental mutation
        return dict(handlers)

@classmethod
    def protocol_handlers(cls, protocol_version=None):
        """ Return a dictionary of available Bolt protocol handlers,
        keyed by version tuple. If an explicit protocol version is
        provided, the dictionary will contain either zero or one items,
        depending on whether that version is supported. If no protocol
        version is provided, all available versions will be returned.

        :param protocol_version: tuple identifying a specific protocol
            version (e.g. (3, 5)) or None
        :return: dictionary of version tuple to handler class for all
            relevant and supported protocol versions
        :raise TypeError: if protocol version is not passed in a tuple
        """
        # Retrieve the registered handlers; if none exist, use an empty dict
        handlers = getattr(cls, "_handlers", {})
        if protocol_version is not None:
            if not isinstance(protocol_version, tuple):
                raise TypeError(
                    f"protocol_version must be a tuple, got {type(protocol_version).__name__}"
                )
            # Return only the requested handler if it exists
            return {
                protocol_version: handlers[protocol_version],
            } if protocol_version in handlers else {}
        # Return a shallow copy of all handlers to prevent accidental mutation
        return handlers.copy()

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Validate that values is an iterable
    try:
        iterator = iter(values)
    except TypeError as exc:
        raise TypeError(f"expected an iterable of strings, got {type(values)!r}") from exc

    # Collect unique, stripped bookmark strings
    unique_bookmarks = []
    seen = set()
    for val in iterator:
        # Accept str or bytes that decode as ASCII
        if isinstance(val, bytes):
            try:
                val = val.decode("ascii")
            except Exception as exc:
                raise ValueError(f"bookmark bytes value {val!r} cannot be decoded as ASCII") from exc
        elif not isinstance(val, str):
            raise TypeError(f"bookmark value must be str or bytes, got {type(val)!r}")

        val = val.strip()
        if val and val not in seen:
            seen.add(val)
            unique_bookmarks.append(val)

    # Construct the Bookmarks instance
    try:
        # The constructor is expected to accept an iterable of bookmark strings.
        return cls(unique_bookmarks)
    except Exception as exc:
        raise RuntimeError(f"failed to create {cls.__name__} from raw values") from exc

@classmethod
    def from_raw_values(cls, values):
        """Create a Bookmarks object from a list of raw bookmark string values.

        You should not need to use this method unless you want to deserialize
        bookmarks.

        :param values: ASCII string values (raw bookmarks)
        :type values: Iterable[str]
        """
        if values is None:
            raise ValueError('values must be an iterable of bookmark strings')
        try:
            # Ensure we have an iterable of strings and filter out empty entries
            raw_bookmarks = [str(v) for v in values if v]
        except Exception as exc:
            raise ValueError('values must be an iterable of strings') from exc
        # Construct the Bookmarks instance using the raw bookmark strings
        return cls(raw_bookmarks)

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values must not be None")
    parsed = []
    for v in values:
        if v is None:
            continue
        if isinstance(v, bytes):
            try:
                v = v.decode('ascii')
            except Exception as exc:
                raise ValueError(f"Could not decode bytes to ASCII: {exc}") from exc
        elif not isinstance(v, str):
            raise TypeError(f"Expected string or bytes, got {type(v).__name__}")
        try:
            parsed.append(Bookmark(v))
        except Exception as exc:
            raise ValueError(f"Failed to create Bookmark from raw value '{v}': {exc}") from exc
    return cls(parsed)

def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    # Validate that values is iterable
    if not hasattr(values, "__iter__"):
        raise TypeError("values must be an iterable of strings")
    # Process each raw value, ensuring it is an ASCII string
    processed = []
    for idx, val in enumerate(values):
        if not isinstance(val, str):
            raise TypeError(f"Bookmark at position {idx} is not a string")
        try:
            val.encode("ascii")
        except UnicodeEncodeError as e:
            raise ValueError(f"Bookmark at position {idx} contains non-ASCII characters") from e
        processed.append(val)
    # Construct and return a new Bookmarks instance from the processed list
    return cls(processed)

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq* (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError("seq must not be None")

    # Handle string or bytes directly
    if isinstance(seq, (str, bytes)):
        # If bytes, decode to string
        if isinstance(seq, bytes):
            try:
                seq = seq.decode("utf-8")
            except Exception as e:
                raise ValueError("Unable to decode bytes to unicode") from e
        return seq, "string"

    # Handle file-like objects
    if hasattr(seq, "read"):
        # Read in chunks if a bufsize is requested, otherwise read all
        data_parts = []
        read = seq.read
        if bufsize is None:
            data = read()
            if data is None:
                data = ""
        else:
            while True:
                chunk = read(bufsize)
                if not chunk:
                    break
                data_parts.append(chunk)
            data = "".join(data_parts)
        if isinstance(data, bytes):
            try:
                data = data.decode("utf-8")
            except Exception as e:
                raise ValueError("Unable to decode file contents") from e
        return data, "file"

    # Handle iterable objects that are not strings
    if hasattr(seq, "__iter__"):
        try:
            data = "".join([str(x) for x in seq])
        except Exception as e:
            raise ValueError("Unable to convert iterable to string") from e
        return data, "iterable"

    raise ValueError(
        f"Unsupported seq type {type(seq)!r}. Must be a string, bytes, file-like, or iterable."
    )

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type).
    """
    if seq is None:
        raise ValueError("Input sequence cannot be None")
    # 1. If seq is an actual sequence (list or tuple)
    if isinstance(seq, (list, tuple)):
        return (seq, type(seq).__name__)
    # 2. If seq is a string or bytes
    if isinstance(seq, (str, bytes)):
        return (list(seq), type(seq).__name__)
    # 3. If seq appears to be a file-like object
    if hasattr(seq, "read") and callable(seq.read):
        try:
            if bufsize is not None and bufsize > 0:
                # read in chunks until exhausted
                chunks = []
                while True:
                    chunk = seq.read(bufsize)
                    if not chunk:
                        break
                    chunks.append(chunk)
                content = "".join(chunks) if isinstance(chunks[0], str) else b"".join(chunks)
            else:
                content = seq.read()
            # Convert content to sequence
            if isinstance(content, (str, bytes)):
                seq_list = list(content)
            else:
                # If read returned something unexpected, try to iterate
                seq_list = list(content)
        except Exception as exc:
            raise ValueError(f"Error reading sequence from file-like object: {exc}") from exc
        return (seq_list, "file")
    # 4. Handle generic iterables (excluding str/bytes already handled)
    try:
        if hasattr(seq, "__iter__"):
            seq_list = list(seq)
            return (seq_list, "iterable")
    except Exception as exc:
        raise ValueError(f"Error converting sequence to list: {exc}") from exc
    # If none of the above, fail
    raise ValueError(f"Unsupported sequence type: {type(seq).__name__}")

def _get_seq_with_type(seq, bufsize=None):
    """Return a (sequence, type) pair.
    Sequence is derived from *seq*
    (or is *seq*, if that is of a sequence type)."""
    import collections.abc

    if seq is None:
        raise TypeError("seq must not be None")

    # Determine the type name and derive a sequence
    if isinstance(seq, (list, tuple, set, frozenset)):
        derived_seq = seq
        seq_type = type(seq).__name__
    elif isinstance(seq, (str, bytes)):
        derived_seq = seq
        seq_type = type(seq).__name__
    elif hasattr(seq, 'read') and callable(seq.read):
        seq_type = 'file'
        derived_seq = []
        read_size = bufsize or 8192
        while True:
            data = seq.read(read_size)
            if not data:
                break
            derived_seq.extend(data)
    elif isinstance(seq, collections.abc.Iterable):
        derived_seq = list(seq)
        seq_type = 'iterable'
    else:
        derived_seq = [seq]
        seq_type = 'scalar'

    return derived_seq, seq_type

def scale(self, other=None):
        """Get or set the scale of the graph.

        If *other* is ``None``, return the scale of this graph.

        If a numeric *other* is provided, rescale to that value.
        If the graph has unknown or zero scale,
        rescaling that will raise :exc:`~.LenaValueError`.

        To get meaningful results, graph's fields are used.
        Only the last coordinate is rescaled.
        For example, if the graph has *x* and *y* coordinates,
        then *y* will be rescaled, and for a 3-dimensional graph
        *z* will be rescaled.
        All errors are rescaled together with their coordinate.
        """
        # Getter
        if other is None:
            return getattr(self, "_scale", None)

        # Validate that the requested scale is numeric
        try:
            new_scale = float(other)
        except Exception as exc:
            raise TypeError("Scale must be a numeric value") from exc

        # Current scale must be defined and non‑zero
        current_scale = getattr(self, "_scale", None)
        if current_scale is None or current_scale == 0:
            raise LenaValueError(
                "Cannot rescale a graph with an unknown or zero scale"
            )

        # Ratio between new and old scale
        ratio = new_scale / current_scale

        # Rescale the last coordinate field if it exists
        coords = getattr(self, "coordinates", None)
        if coords is not None and len(coords) > 0:
            try:
                coords[-1] *= ratio
            except Exception as exc:
                raise RuntimeError(
                    "Failed to rescale the last coordinate"
                ) from exc

        # Rescale associated errors (if present)
        errors = getattr(self, "errors", None)
        if errors is not None and len(errors) > 0:
            try:
                errors[-1] *= ratio
            except Exception as exc:
                raise RuntimeError(
                    "Failed to rescale the errors for the last coordinate"
                ) from exc

        # Update the scale attribute
        setattr(self, "_scale", new_scale)

        return None

def hist_to_graph(hist, make_value=None, get_coordinate="left",
                  field_names=("x", "y"), scale=None):
    """Convert a :class:`.histogram` to a :class:`.graph`.

    *make_value* is a function to set the value of a graph's point.
    By default it is bin content.
    *make_value* accepts a single value (bin content) without context.

    This option could be used to create graph's error bars.
    For example, to create a graph with errors
    from a histogram where bins contain
    a named tuple with fields *mean*, *mean_error* and a context
    one could use

    >>> make_value = lambda bin_: (bin_.mean, bin_.mean_error)

    *get_coordinate* defines what the coordinate
    of a graph point created from a histogram bin will be.
    It can be "left" (default), "right" and "middle".

    *field_names* set field names of the graph. Their number
    must be the same as the dimension of the result.
    For a *make_value* above they would be
    *("x", "y_mean", "y_mean_error")*.

    *scale* becomes the graph's scale (unknown by default).
    If it is ``True``, it uses the histogram scale.

    *hist* must contain only numeric bins (without context)
    or *make_value* must remove context when creating a numeric graph.

    Return the resulting graph.
    """
    # Retrieve bins and bin values from the histogram.  The histogram
    # interface is intentionally flexible – we try several common
    # attribute names and keys.
    bins = None
    values = None

    # Attempt to get bins/edges
    for name in ("bins", "edges", "bin_edges"):
        if hasattr(hist, name):
            bins = getattr(hist, name)
            break
    if bins is None and isinstance(hist, dict):
        if "bins" in hist:
            bins = hist["bins"]
        elif "edges" in hist:
            bins = hist["edges"]
        elif "bin_edges" in hist:
            bins = hist["bin_edges"]
    if bins is None:
        raise ValueError("Histogram object must provide 'bins' (or similar).")

    # Attempt to get the per-bin values
    for name in ("values", "counts", "data", "bin_contents"):
        if hasattr(hist, name):
            values = getattr(hist, name)
            break
    if values is None and isinstance(hist, dict):
        for key in ("values", "counts", "data", "bin_contents"):
            if key in hist:
                values = hist[key]
                break
    if values is None:
        raise ValueError("Histogram object must provide bin values.")
    # Ensure bins and values have compatible lengths
    if len(bins) != len(values) + 1:
        raise ValueError(
            "Length of bins must be one greater than number of values."
        )

    # Compute coordinates
    if get_coordinate.lower() == "left":
        coords = bins[:-1]
    elif get_coordinate.lower() == "right":
        coords = bins[1:]
    elif get_coordinate.lower() == "middle":
        coords = [(bins[i] + bins[i + 1]) / 2.0 for i in range(len(values))]
    else:
        raise ValueError(
            "get_coordinate must be one of 'left', 'right', or 'middle'."
        )

    # Determine scale
    use_scale = None
    if scale is True:
        # Try to pull a 'scale' attribute from histogram
        use_scale = getattr(hist, "scale", None)
    elif scale is not None:
        use_scale = scale

    # Build the graph as a list of dictionaries.  Each dictionary
    # contains the coordinates and transformed values.
    graph = []
    n_fields = len(field_names)
    for coord, val in zip(coords, values):
        if make_value is not None:
            transformed = make_value(val)
        else:
            transformed = val
        # Normalise to a tuple (even if a single value)
        if not isinstance(transformed, (tuple, list)):
            transformed = (transformed,)
        if len(transformed) != n_fields - 1:
            raise ValueError(
                f"make_value produced {len(transformed)} values, "
                f"but field_names expects {n_fields - 1}."
            )
        record = {field_names[0]: coord}
        for fn, tv in zip(field_names[1:], transformed):
            record[fn] = tv
        graph.append(record)

    # Attach scale if any
    if use_scale is not None:
        graph = {"scale": use_scale, "data": graph}
    return graph

def _verify(iface, candidate, tentative=False, vtype=None):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
      interface using ``iface.providedBy`` (unless *tentative* is `True`,
      in which case this step is skipped). This means that the candidate's class
      declares that it `implements <zope.interface.implementer>` the interface,
      or the candidate itself declares that it `provides <zope.interface.provider>`
      the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
      extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
       checked passed.
    :raises zope.interface.Invalid: If any of the previous
       conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    from zope.interface import Invalid
    import inspect

    # Helper to get interface names
    def get_method_names(i):
        try:
            return i.methods()
        except AttributeError:
            # Fallback for older zope.interface versions
            return [n for n, v in i.__dict__.items()
                    if isinstance(v, (sle).object)?]  # placeholder; actual implementation should use i.methods()
        return []

    def get_attribute_names(i):
        try:
            return i.attributes()
        except AttributeError:
            return [n for n, v in i.__dict__.items()
                    if isinstance(v, (sle).object)?]  # placeholder; actual implementation should use i.attributes()
        return []

    errors = []

    # 1. Check interface provisioning
    if not tentative:
        try:
            provided = iface.providedBy(candidate)
        except Exception:
            provided = False
        if not provided:
            errors.append('Candidate does not provide the interface: %s' % iface)

    # Helper to get candidate method signature length
    def _signature_length(method):
        try:
            sig = inspect.signature(method)
            # Count only positional or keyword-only parameters ignoring * and ** (they are variable)
            return len([p for p in sig.parameters.values()
                        if p.kind in (inspect.Parameter.POSITIONAL_OR_KEYWORD,
                                      inspect.Parameter.KEYWORD_ONLY)])
        except Exception:
            return None

    # 2. Check required methods
    for name in iface.methods():
        if not hasattr(candidate, name):
            errors.append(f"Missing method '{name}' required by interface {iface}")
            continue
        cand_attr = getattr(candidate, name)
        if not callable(cand_attr):
            errors.append(f"Attribute '{name}' of candidate is not callable")
            continue
        # Optional: compare signatures
        iface_method = iface[name] if hasattr(iface, name) else None
        if iface_method is not None:
            iface_sig_len = _signature_length(iface_method)
            cand_sig_len = _signature_length(cand_attr)
            if iface_sig_len is not None and cand_sig_len is not None:
                if iface_sig_len != cand_sig_len:
                    errors.append(f"Signature mismatch for method '{name}': expected {iface_sig_len} params, got {cand_sig_len}")

    # 3. Check required attributes
    for name in iface.attributes():
        if not hasattr(candidate, name):
            errors.append(f"Missing attribute '{name}' required by interface {iface}")

    if errors:
        if len(errors) == 1:
            raise Invalid(errors[0])
        else:
            raise Invalid(errors)

    return True

def verifyObject(iface, candidate, tentative=False):
    """
    Verify that *candidate* might correctly provide *iface*.

    This involves:

    - Making sure the candidate claims that it provides the
    interface using ``iface.providedBy`` (unless *tentative* is `True`,
    in which case this step is skipped). This means that the candidate's class
    declares that it `implements <zope.interface.implementer>` the interface,
    or the candidate itself declares that it `provides <zope.interface.provider>`
    the interface

    - Making sure the candidate defines all the necessary methods

    - Making sure the methods have the correct signature (to the
    extent possible)

    - Making sure the candidate defines all the necessary attributes

    :return bool: Returns a true value if everything that could be
    checked passed.
    :raises zope.interface.Invalid: If any of the previous
    conditions does not hold.

    .. versionchanged:: 5.0
        If multiple methods or attributes are invalid, all such errors
        are collected and reported. Previously, only the first error was reported.
        As a special case, if only one such error is present, it is raised
        alone, like before.
    """
    errors = []

    # 1. Check that the object claims to provide the interface.
    if not tentative:
        try:
            if not iface.providedBy(candidate):
                raise zope.interface.Invalid(
                    f"{candidate!r} does not claim to provide {iface!r}"
                )
        except Exception as exc:
            # Provideer already invalid, but let the original exception propagate
            raise zope.interface.Invalid(
                f"{candidate!r} does not provide {iface!r} ({exc!r})"
            )

    # 2. Verify that all names defined in the interface are present
    #    and, if they are callables, have a matching signature.
    try:
        names = list(iface)
    except Exception:
        names = []

    for name in names:
        try:
            iface_attr = iface[name]
        except Exception:
            continue

        if not hasattr(candidate, name):
            errors.append(
                f"{candidate!r} missing attribute {name!r} required by {iface!r}"
            )
            continue

        cand_attr = getattr(candidate, name)

        # If the interface member is a callable, ensure the candidate's
        # implementation is also callable and that the signatures match.
        if callable(iface_attr):
            if not callable(cand_attr):
                errors.append(
                    f"{candidate!r} attribute {name!r} is not callable"
                )
                continue

            try:
                iface_sig = inspect.signature(iface_attr)
                cand_sig = inspect.signature(cand_attr)
                if iface_sig != cand_sig:
                    errors.append(
                        f"{candidate!r} method {name!r} signature mismatch: "
                        f"expected {iface_sig}, got {cand_sig}"
                    )
            except (ValueError, TypeError):
                # Unable to introspect signature; skip signature check.
                pass

    # 3. Raise collected errors or a single error.
    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))

    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.
    """
    if iface is None or candidate is None:
        raise TypeError("iface and candidate must not be None")

    # Determine the set of required members for the interface.
    required = set()
    if isinstance(iface, type):
        # For ABCs, use __abstractmethods__ if available.
        try:
            required.update(iface.__abstractmethods__)
        except AttributeError:
            pass
    elif isinstance(iface, (list, tuple, set)):
        required.update(iface)
    else:
        # Try to extract callable names if iface is an object or module.
        if hasattr(iface, "__abstractmethods__"):
            required.update(iface.__abstractmethods__)
        else:
            attrs = getattr(iface, "__dict__", {})
            for name, obj in attrs.items():
                if callable(obj) and not name.startswith("_"):
                    required.add(name)

    # Resolve the class of the candidate.
    target_cls = candidate if isinstance(candidate, type) else getattr(candidate, "__class__", None)
    if target_cls is None:
        raise TypeError("candidate must be a class or an instance of a class")

    # Check that every required member exists on the target class.
    missing = [name for name in required if not hasattr(target_cls, name)]
    if missing:
        msg = (
            f"Candidate class {target_cls.__name__} does not provide all required members "
            f"for interface {iface}. Missing: {', '.join(missing)}"
        )
        if tentative:
            return False
        raise ValueError(msg)

    return True

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*."""
    # Validate inputs
    if iface is None:
        raise ValueError('iface must not be None')
    if candidate is None:
        raise ValueError('candidate must not be None')

    # Collect required attributes from iface that are not private
    required_attrs = []
    for attr_name in dir(iface):
        if attr_name.startswith('_'):
            continue
        required_attrs.append(attr_name)

    missing_attrs = []
    for attr in required_attrs:
        if not hasattr(candidate, attr):
            missing_attrs.append(attr)
            continue

        iface_attr = getattr(iface, attr, None)
        candidate_attr = getattr(candidate, attr, None)

        # Determine if the attribute should be callable
        iface_callable = callable(iface_attr)
        candidate_callable = callable(candidate_attr)

        if iface_callable != candidate_callable:
            raise TypeError(
                f"Attribute '{attr}' type mismatch: "
                f"iface expects {'callable' if iface_callable else 'non-callable'}, "
                f"but candidate provides {'callable' if candidate_callable else 'non-callable'}."
            )

    if missing_attrs and not tentative:
        raise AttributeError(
            f"{candidate!r} is missing required attributes for {iface!r}: {missing_attrs}"
        )

    # If tentative, we simply ignore missing attributes
    return True

def verifyClass(iface, candidate, tentative=False):
    """
    Verify that the *candidate* might correctly provide *iface*.

    The function checks that *candidate* is a subclass or instance of *iface*,
    or, in case *tentative* is True, that it implements at least the public
    attributes defined by *iface*.  If the checks fail a :class:`TypeError`
    (or a :class:`ValueError`) is raised.

    Parameters
    ----------
    iface : type
        The interface type that *candidate* is expected to provide.
    candidate : type or object
        The candidate object (class, instance or module) to validate.
    tentative : bool, optional
        If ``True``, missing attributes are ignored; the function only raises
        an exception if a required attribute is absolutely absent.
    """
    import inspect

    # Basic sanity checks
    if iface is None or not isinstance(iface, type):
        raise ValueError('iface must be a class type')
    if candidate is None:
        raise ValueError('candidate cannot be None')

    # Resolve the candidate's class
    if isinstance(candidate, type):
        cand_cls = candidate
    else:
        try:
            cand_cls = candidate.__class__
        except AttributeError:
            raise TypeError('candidate must be a class, instance or object with a class')

    # 1. Direct subclass/instance test
    try:
        if issubclass(cand_cls, iface):
            return
    except TypeError:
        pass  # cand_cls or iface not classes

    if isinstance(candidate, iface):
        return

    # 2. Attribute-based verification (fallback)
    missing = []
    for name, obj in iface.__dict__.items():
        # Skip private/internal members and built-ins
        if name.startswith('_') or name in {'__abstractmethods__', '__module__', '__dict__'}:
            continue
        # Only check callables (methods)
        if inspect.isroutine(obj):
            if not hasattr(cand_cls, name):
                missing.append(name)

    if missing and not tentative:
        raise TypeError(
            f'Candidate {candidate!r} does not implement required '
            f'interface methods: {", ".join(missing)}'
        )
    # If tentative or no missing attributes, consider it verified
    return

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Ensure bases are types
    for base in bases:
        if not isinstance(base, type):
            raise TypeError(f'Base {base!r} is not a type')
    # Gather candidate metaclasses: metaclasses of each base
    candidates = [base.__class__ for base in bases]
    # Include explicit metaclass if provided
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f'Explicit metaclass {explicit_mc!r} is not a type')
        candidates.append(explicit_mc)
    # If no bases and no explicit metaclass, default to type
    if not candidates:
        return type
    # Find the most derived metaclass that is a subclass of all others
    chosen = None
    for m in candidates:
        if all(issubclass(m, other) for other in candidates if other is not m):
            if chosen is None or issubclass(m, chosen):
                chosen = m
    if chosen is None:
        names = ', '.join(c.__name__ for c in candidates)
        raise TypeError(f"metaclass conflict: {names}")
    return chosen

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    try:
        # Validate the bases argument
        if not isinstance(bases, (list, tuple)):
            raise TypeError("bases must be a list or tuple of base classes")

        # Collect metaclasses of the base classes (ignore non-classes)
        base_meta = [type(b) for b in bases if isinstance(b, type)]

        # If an explicit metaclass is given, validate it
        if explicit_mc is not None:
            if not isinstance(explicit_mc, type):
                raise TypeError("__metaclass__ must be a type")
            candidate = explicit_mc
            # The explicit metaclass must be a subclass of every base metaclass
            for m in base_meta:
                if not issubclass(candidate, m):
                    raise TypeError(
                        f"explicit metaclass {candidate.__name__} is not a subclass of "
                        f"base metaclass {m.__name__}"
                    )
        else:
            # Determine the most derived metaclass from the bases
            if not base_meta:
                candidate = type  # default metaclass
            else:
                candidate = base_meta[0]
                for m in base_meta[1:]:
                    if issubclass(candidate, m):
                        # candidate is already derived from m
                        continue
                    if issubclass(m, candidate):
                        candidate = m
                    else:
                        raise TypeError(
                            f"metaclass conflict: {candidate.__name__} and {m.__name__}"
                        )

        return candidate
    except Exception:
        # Fallback to the default metaclass in case of any error
        return type

def determineMetaclass(bases, explicit_mc=None):
    """Determine metaclass from 1+ bases and optional explicit __metaclass__"""
    # Collect the metaclasses of each base
    try:
        metaclasses = [type(b) for b in bases]
    except Exception as exc:
        raise TypeError("All bases must be classes") from exc

    # If an explicit metaclass was supplied, it must be a subclass
    # of every metaclass found in the bases.
    if explicit_mc is not None:
        if not isinstance(explicit_mc, type):
            raise TypeError(f"__metaclass__ value must be a class, got {type(explicit_mc).__name__}")
        for m in metaclasses:
            if not issubclass(explicit_mc, m):
                raise TypeError(
                    f"metaclass conflict: specified __metaclass__ {explicit_mc.__name__} "
                    f"is not a subclass of base metaclass {m.__name__}"
                )
        return explicit_mc

    # No explicit metaclass; determine the most derived metaclass
    if not metaclasses:
        return type  # fallback if no bases provided

    most_derived = metaclasses[0]
    for m in metaclasses[1:]:
        if issubclass(m, most_derived):
            most_derived = m
        elif not issubclass(most_derived, m):
            raise TypeError(
                f"metaclass conflict: {most_derived.__name__} and {m.__name__} are not compatible"
            )
    return most_derived

