def _create_in_regex(self) -> Pattern:
    """
    Create the in‑style parameter regular expression.

    Returns the in‑style parameter regular expression (:class:`re.Pattern`).
    """
    # The pattern matches a comma‑separated list of non‑empty items,
    # optionally surrounded by parentheses, with optional whitespace
    # around items, commas and parentheses.
    pattern_str = r'^\s*\(?\s*[^,()]+(?:\s*,\s*[^,()]+)*\s*\)?\s*$'
