def process_text_links(text):
    """Process links in text, adding some attributes and linkifying textual links."""
    import re

    if not isinstance(text, str):
        raise TypeError("text must be a string")

    # Regex to match bare URLs (http or https)
    url_pattern = re.compile(
        r'\b(?P<url>https?://[^\s<>"\'`{}|\\]+)', re.IGNORECASE)

    def _replace_url(match):
        url = match.group('url')
        # Use a simple HTML anchor with target and rel attributes
        return (
            f'<a href="{url}" '
            f'target="_blank" rel="noopener noreferrer">{url}</a>'
        )

    try:
        # Replace all bare URLs with linkified anchors
        result = url_pattern.sub(_replace_url, text)
    except re.error:
        # In case the regex fails for some reason, fall back to original text
        result = text

    # Additionally, add target="_blank" rel="noopener noreferrer" to existing anchors that lack them.
    # This handles simple cases and avoids modifying existing attributes.
    anchor_pattern = re.compile(
        r'(<a\s+[^>]*?)?href=(["\'])(?P<href>[^"\']+)(["\'])(?P<rest>[^>]*>)',
        re.IGNORECASE)

    def _add_attrs(match):
        before = match.group(1) or ''
        href = match.group('href')
        suffix = match.group('rest')
        # Check if target or rel already present
        if 'target=' in suffix.lower() or 'rel=' in suffix.lower():
            return match.group(0)  # leave unchanged
        return (
            f'<a {before}href={match.group(2)}{href}{match.group(4)} '
            f'target="_blank" rel="noopener noreferrer"{suffix[1:]}'
        )

    try:
        result = anchor_pattern.sub(_add_attrs, result)
    except re.error:
        pass  # Ignore regex errors; return what we have

    return result

