def fetch_content_type(url: str) -> Optional[str]:
    """Fetch the HEAD of the remote url to determine the content type."""
    try:
        import urllib.request, urllib.parse, urllib.error
    except Exception:
        return None

    try:
        parsed = urllib.parse.urlsplit(url)
        scheme = parsed.scheme.lower()
        if scheme not in ("http", "https", "ftp", "ftps"):
            return None

        # Create a HEAD request
        request = urllib.request.Request(url, method="HEAD")
        # Force the Host header to match the netloc (sometimes required)
        request.add_header("Host", parsed.netloc)

        with urllib.request.urlopen(request, timeout=10) as response:
            # For HTTP(S), only accept 200-299 status codes
            if scheme in ("http", "https"):
                status = getattr(response, "status", None)
                if status is None:
                    status = response.getcode()
                if not (200 <= status <= 299):
                    return None
            # Retrieve the Content-Type header if present
            return response.headers.get("Content-Type")
    except (urllib.error.URLError, urllib.error.HTTPError, ValueError, Exception):
        # Any error (network, parsing, timeouts) results in None
        return None

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    from urllib.parse import urlparse
    from urllib.request import Request, urlopen
    from urllib.error import URLError, HTTPError

    # Validate URL scheme
    try:
        parsed = urlparse(url)
    except Exception:
        return None
    if parsed.scheme.lower() not in ("http", "https"):
        # Unsupported scheme
        return None

    # Build a HEAD request
    req = Request(url, method="HEAD")
    try:
        resp = urlopen(req, timeout=10)
    except (HTTPError, URLError):
        return None
    except Exception:
        # catch any other network-related error
        return None

    try:
        # Try to get the content‑type header
        content_type = resp.headers.get("Content-Type")
        if content_type:
            # Normalize as a single string
            return content_type.split(";")[0].strip()
        return None
    finally:
        # Ensure the response stream is closed
        try:
            resp.close()
        except Exception:
            pass

