def dict_insert(dic, val, key, *keys):
    """
    Insert a value of a nested key into a dictionary.

    All ancestor keys should be provided as method arguments.  The first
    argument after the dictionary and the value is treated as the first key
    in the chain.  Any remaining keys are passed either as separate
    positional arguments or as a single iterable.  Intermediate dictionaries
    are created automatically if they do not exist.

    Example:
        # Using separate key arguments
        d = {}
        dict_insert(d, 'val', 'key1', 'key2')
        assert d['key1']['key2'] == 'val'

        # Using a single iterable
        d = {}
        dict_insert(d, 'val', ['key1', 'key2'])
        assert d['key1']['key2'] == 'val'
    """
    # Validate input
    if not isinstance(dic, dict):
        raise TypeError(f"Expected a dict for `dic`, got {type(dic).__name__}")

    # Resolve the key chain
    if keys == ():
        # No additional keys; key may itself be a list/tuple of keys
        if isinstance(key, (list, tuple)):
            all_keys = list(key)
        else:
            all_keys = [key]
    else:
        all_keys = [key] + list(keys)

    if not all_keys:
        raise ValueError("At least one key must be provided")

    # Navigate/create intermediate dictionaries
    current = dic
    for k in all_keys[:-1]:
        if not isinstance(current, dict):
            raise ValueError(f"Intermediate key '{k}' does not point to a dict")
        if k not in current or not isinstance(current[k], dict):
            current[k] = {}
        current = current[k]

    # Insert the value at the final key
    current[all_keys[-1]] = val

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type
    """
    import os, fnmatch
    try:
        files = []
        if not isinstance(settings_dirs, (list, tuple)):
            settings_dirs = [settings_dirs]
        for directory in settings_dirs:
            if not os.path.isdir(directory):
                continue
            for fname in os.listdir(directory):
                # Skip directories
                full_path = os.path.join(directory, fname)
                if os.path.isdir(full_path):
                    continue
                # If spec_option is given, use it as a glob pattern, otherwise accept all files
                if spec_option:
                    try:
                        if fnmatch.fnmatch(fname, spec_option):
                            files.append(full_path)
                    except Exception:
                        # If spec_option is not a valid pattern, skip filtering
                        files.append(full_path)
                else:
                    files.append(full_path)
        return sorted(files)
    except Exception:
        return []

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type"""
    try:
        # Accept a single directory string or an iterable of directories
        dirs = [settings_dirs] if isinstance(settings_dirs, (str, bytes)) else list(settings_dirs)
        found_files = set()
        for directory in dirs:
            if not os.path.isdir(directory):
                continue
            # If spec_option looks like a glob pattern (contains *, ?, or [])
            if spec_option and ('*' in spec_option or '?' in spec_option or '[' in spec_option):
                pattern = os.path.join(directory, spec_option)
                for match in glob.glob(pattern, recursive=True):
                    if os.path.isfile(match):
                        found_files.add(match)
            else:
                # Treat spec_option as a simple suffix or skip filtering if None/empty
                for fname in os.listdir(directory):
                    if not os.path.isfile(os.path.join(directory, fname)):
                        continue
                    if spec_option:
                        if fname.endswith(spec_option):
                            found_files.add(os.path.join(directory, fname))
                    else:
                        found_files.add(os.path.join(directory, fname))
        return sorted(found_files)
    except Exception:
        return []

def list_of_file_names(settings_dirs, spec_option):
    """Create a new IniType complex type

    Returns a sorted list of fully qualified file paths from the provided
    directories that match the given pattern or extension.

    Parameters
    ----------
    settings_dirs : str or Iterable[str]
        A directory path or an iterable of directory paths to search.
    spec_option : str, optional
        A glob pattern or file extension to filter the files.
        Defaults to '*.ini' if not provided.

    Returns
    -------
    list[str]
        Sorted list of absolute file paths matching the pattern.
    """
    results = []

    # Normalize settings_dirs to an iterable of paths
    if isinstance(settings_dirs, (str, os.PathLike)):
        dir_list = [settings_dirs]
    else:
        try:
            dir_list = list(settings_dirs)
        except TypeError:
            # If it's not iterable
            dir_list = [settings_dirs]

    # Default pattern for ini files
    pattern = spec_option if spec_option else '*.ini'

    for d in dir_list:
        try:
            # Build full glob pattern
            full_pattern = os.path.join(d, pattern)
            for file_path in glob.glob(full_pattern):
                try:
                    if os.path.isfile(file_path):
                        results.append(os.path.abspath(file_path))
                except OSError:
                    # Skip file if we cannot access it
                    continue
        except (OSError, FileNotFoundError, PermissionError):
            # Skip directories we cannot access
            continue

    return sorted(results)

