            raise IRValidatorException(f'Failed to parse YAML content: {exc}')

        # YAML load may return None if file is empty
        if data is None:
            raise IRValidatorException('YAML content could not be parsed into a document')
        if not isinstance(data, dict):
            raise IRValidatorException('Spec content must be a YAML mapping (dictionary) at the top level')

        # Validate required fields if defined on the class
        required_fields = getattr(cls, 'REQUIRED_FIELDS', [])
        for field in required_fields:
            if field not in data:
                raise IRValidatorException(f'Missing required field "{field}" in spec')

        return data

