def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    visited = set()

    def _resolve(d):
        if id(d) in visited:
            raise RuntimeError("Circular include detected in spec files")
        visited.add(id(d))
        if not isinstance(d, dict):
            return d
        # If an 'include' key is present, merge its content into the current dict
        include = d.pop('include', None)
        if include is not None:
            if not isinstance(include, dict):
                raise ValueError("'include' value must be a dict")
            _resolve(include)
            for k, v in include.items():
                if k not in d:
                    d[k] = v
                else:
                    # Merge nested dicts, otherwise overwrite
                    if isinstance(d[k], dict) and isinstance(v, dict):
                        _resolve(d[k])
                        _resolve(v)
                        d[k].update(v)
                    else:
                        d[k] = v
        # Recursively resolve any nested includes
        for key, value in list(d.items()):
            if isinstance(value, dict):
                _resolve(value)
        return d

    return _resolve(parser_dict)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise TypeError(f"_include_groups expects a dict, got {type(parser_dict)}")

    def _merge(target, inc):
        for k, v in inc.items():
            if k in target and isinstance(target[k], dict) and isinstance(v, dict):
                _merge(target[k], v)
            else:
                target[k] = v

    def _process(d):
        keys = list(d.keys())
        for key in keys:
            val = d[key]
            if isinstance(val, dict):
                # Handle include directive if present
                if 'include' in val:
                    inc_val = val.pop('include')
                    if isinstance(inc_val, dict):
                        _merge(val, inc_val)
                    elif isinstance(inc_val, list):
                        for inc_item in inc_val:
                            if isinstance(inc_item, dict):
                                _merge(val, inc_item)
                # Recursively process nested groups
                _process(val)

    _process(parser_dict)
    return parser_dict

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    Parameters
    ----------
    parser_dict : dict
        Mapping of group names to parser specification dictionaries. Each
        specification may optionally include an ``include`` key whose value
        specifies other groups or inline dictionaries that should be merged
        into the current specification. The merge is performed recursively
        and a :class:`RecursionError` is raised if a cyclic include is
        detected. Keys defined in the current specification override any
        keys from the included ones.

    Returns
    -------
    dict
        A new dictionary with all includes recursively resolved.
    """
    def _merge_dicts(dest, src):
        """Recursively merge src into dest. List values are concatenated."""
        for key, val in src.items():
            if key in dest:
                if isinstance(dest[key], dict) and isinstance(val, dict):
                    _merge_dicts(dest[key], val)
                elif isinstance(dest[key], list) and isinstance(val, list):
                    dest[key] += val
                else:
                    dest[key] = val
            else:
                dest[key] = val

    def _resolve(name, seen):
        """Resolve a single group name."""
        if name in seen:
            cycle = ' -> '.join(list(seen) + [name])
            raise RecursionError(f'Circular include detected: {cycle}')
        if name not in parser_dict:
            raise KeyError(f"Missing parser spec for included group '{name}'")
        seen.add(name)
        spec = parser_dict[name]
        result = {}

        # Handle include directive
        includes = spec.get('include')
        if includes is not None:
            # Normalise to a list of inclusion specs
            incl_specs = []
            if isinstance(includes, (list, tuple)):
                incl_specs.extend(includes)
            elif isinstance(includes, dict):
                incl_specs.extend(includes.values())
            elif isinstance(includes, str):
                incl_specs.append(includes)
            else:
                raise TypeError(f"Unsupported include format for group '{name}': {type(includes).__name__}")

            for inc in incl_specs:
                if isinstance(inc, str):
                    inc_resolved = _resolve(inc, seen.copy())
                    _merge_dicts(result, inc_resolved)
                elif isinstance(inc, dict):
                    _merge_dicts(result, inc)
                else:
                    raise TypeError(f"Unsupported include item type for group '{name}': {type(inc).__name__}")

        # Merge the current spec last so that it overrides included values
        curr_spec = {k: v for k, v in spec.items() if k != 'include'}
        _merge_dicts(result, curr_spec)

        return result

    resolved = {}
    for grp in parser_dict:
        resolved[grp] = _resolve(grp, set())

    return resolved

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    def _resolve(obj):
        if isinstance(obj, dict):
            if 'include' in obj:
                inc = obj.pop('include')
                if not isinstance(inc, dict):
                    raise ValueError("'include' value must be a dict")
                for key, val in inc.items():
                    if (
                        key in obj
                        and isinstance(obj[key], dict)
                        and isinstance(val, dict)
                    ):
                        obj[key] = _resolve({**obj[key], **val})
                    else:
                        obj[key] = _resolve(val)
                return _resolve(obj)
            else:
                for k, v in list(obj.items()):
                    obj[k] = _resolve(v)
                return obj
        elif isinstance(obj, list):
            return [_resolve(item) for item in obj]
        return obj

    return _resolve(parser_dict)

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files.

    The method looks for keys named ``include`` or ``__include__`` inside
    each group in *parser_dict*.  If found, the value is interpreted as a
    dictionary or a list that describes other groups to merge into the
    current group.  The merge is performed in-place and the resulting
    dictionary is returned.

    Parameters
    ----------
    parser_dict : dict
        Mapping of group names to a dictionary of argument definitions.

    Returns
    -------
    dict
        The same *parser_dict* instance with include directives resolved.
    """
    # Ensure we are working with a dict
    if not isinstance(parser_dict, dict):
        return parser_dict

    # Continue resolving includes until no more directives remain
    unresolved = True
    while unresolved:
        unresolved = False
        # Make a copy of keys to avoid runtime dictionary changes
        for group_name, group_cfg in list(parser_dict.items()):
            if not isinstance(group_cfg, dict):
                continue
            for key in ('include', '__include__'):
                if key not in group_cfg:
                    continue
                unresolved = True
                # Remove the include key to prevent reprocessing
                include_val = group_cfg.pop(key)

                # Handle include values that are dictionaries
                if isinstance(include_val, dict):
                    for inc_key, inc_val in include_val.items():
                        if isinstance(inc_val, dict):
                            group_cfg.update(inc_val)
                        elif isinstance(inc_val, str):
                            # Treat the string as a reference to another group
                            referenced = parser_dict.get(inc_val)
                            if isinstance(referenced, dict):
                                group_cfg.update(referenced)
                # Handle include values that are lists of group names
                elif isinstance(include_val, list):
                    for inc_name in include_val:
                        referenced = parser_dict.get(inc_name)
                        if isinstance(referenced, dict):
                            group_cfg.update(referenced)
                # If the value is a string, use it as a reference to another group
                elif isinstance(include_val, str):
                    referenced = parser_dict.get(include_val)
                    if isinstance(referenced, dict):
                        group_cfg.update(referenced)
                # Any other types are ignored to maintain robustness
    return parser_dict

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Ensure we have a spec to pull from
    spec = getattr(self, "spec", None)
    if spec is None:
        raise AttributeError("The object does not have a 'spec' attribute.")
    # Iterate over all arguments defined in the scheme
    for arg in getattr(self, "args", []):
        # Skip items that are not option objects
        if not hasattr(arg, "name"):
            continue
        # Attempt to fetch the value from the spec
        try:
            if isinstance(spec, dict):
                value = spec.get(arg.name)
            else:
                value = getattr(spec, arg.name, None)
        except Exception:
            value = None
        # If no value in spec, fall back to the option's default
        if value is None:
            default_val = getattr(arg, "default", None)
            if default_val is None:
                # Guard against sentinel NoDefault if used in the framework
                try:
                    from .markers import NoDefault  # pragma: no cover
                except Exception:
                    NoDefault = object  # Fallback placeholder
                if isinstance(default_val, NoDefault):
                    default_val = None
            value = default_val
        # Handle nested dict options by merging defaults recursively
        try:
            from .option_types import DictOption  # pragma: no cover
        except Exception:
            DictOption = None
        if DictOption and isinstance(arg, DictOption) and isinstance(value, dict):
            # If the option has an associated scheme, merge its defaults
            scheme = getattr(arg, "scheme", None)
            if scheme and hasattr(scheme, "get_spec_defaults"):
                try:
                    sub_defaults = scheme.get_spec_defaults()
                    for sub_key, sub_val in sub_defaults.items():
                        # Only add if the key is missing or None
                        if sub_key not in value or value.get(sub_key) is None:
                            value[sub_key] = sub_val
                except Exception:
                    # Silently ignore any errors while merging sub defaults
                    pass
        defaults[arg.name] = value
    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Get the spec; it might be a dict, a custom object with `get`, or missing
    spec = getattr(self, 'spec', None)

    for arg in getattr(self, 'args', []):
        # Skip items that are not options
        if not hasattr(arg, 'name'):
            continue

        # Attempt to obtain a value from the spec, handling various spec types
        try:
            value = spec.get(arg.name, None) if hasattr(spec, 'get') else spec[arg.name] if isinstance(spec, dict) else None
        except Exception:
            # If any error occurs retrieving from spec, treat as missing
            value = None

        # If the spec didn't provide a value, fall back to the option's default
        if value is None and not isinstance(getattr(arg, 'default', NoDefault), NoDefault):
            value = getattr(arg, 'default')

        # For nested dictionary options, recursively gather defaults from their scheme
        if isinstance(arg, DictOption) and arg.scheme:
            try:
                nested = arg.scheme.get_spec_defaults()
                if nested:
                    value = nested
            except Exception:
                # If scheme processing fails, ignore and keep current value
                pass

        if value is not None:
            defaults[arg.name] = value

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    # Collect defaults from the instance's spec, falling back to
    # class-level defaults if the instance spec is not set.
    defaults = {}

    # Helper that extracts a mapping from a spec object.
    def _spec_to_dict(spec_obj):
        if isinstance(spec_obj, dict):
            return spec_obj
        # Prefer a to_dict method if present.
        if hasattr(spec_obj, "to_dict") and callable(spec_obj.to_dict):
            try:
                return spec_obj.to_dict()
            except Exception:
                # Ignore failures from a custom to_dict implementation.
                return {}
        # As a last resort use the object's __dict__.
        if hasattr(spec_obj, "__dict__"):
            return dict(spec_obj.__dict__)
        return {}

    # Retrieve the spec from the instance or, if missing, from the class.
    try:
        spec_obj = getattr(self, "spec", None) or getattr(self.__class__, "spec", None)
    except Exception:
        spec_obj = None

    if spec_obj is not None:
        defaults.update(_spec_to_dict(spec_obj))

    # Merge class-level _default_spec, if it exists.
    try:
        class_default = getattr(self.__class__, "_default_spec", None)
    except Exception:
        class_default = None

    if class_default is not None:
        if isinstance(class_default, dict):
            defaults = {**class_default, **defaults}
        elif hasattr(class_default, "to_dict") and callable(class_default.to_dict):
            try:
                defaults = {**class_default.to_dict(), **defaults}
            except Exception:
                # If the class default conversion fails, ignore it.
                pass

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    # Retrieve spec and default_spec if they exist
    spec = getattr(self, 'spec', None)
    default_spec = getattr(self, '_default_spec', None)

    # Get the iterable of argument definitions
    args = getattr(self, 'args', [])
    if not isinstance(args, (list, tuple)):
        raise ValueError("Attribute 'args' must be a list or tuple of argument definitions")

    for arg in args:
        if arg is None:
            continue

        # Determine the argument name
        name = getattr(arg, 'name', None)
        if not name:
            continue

        value = None

        # 1. Try to get value from the spec
        if spec is not None:
            if isinstance(spec, dict):
                value = spec.get(name)
            elif hasattr(spec, name):
                try:
                    value = getattr(spec, name)
                except Exception:
                    value = None

        # 2. If no value yet, fall back to the argument's default
        if value is None:
            # Some argument objects may use a sentinel for no default (e.g., NoDefault)
            default = getattr(arg, 'default', None)
            if default is not None:
                value = default

        # 3. If still no value, try the default_spec
        if value is None and default_spec is not None:
            if isinstance(default_spec, dict):
                value = default_spec.get(name)
            elif hasattr(default_spec, name):
                try:
                    value = getattr(default_spec, name)
                except Exception:
                    value = None

        # 4. If a value is found, store it
        if value is not None:
            defaults[name] = value

    return defaults

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources."""
    defaults = {}
    # Attempt to obtain a mapping of default values from the spec.
    try:
        spec = self.spec
    except AttributeError:
        spec = {}
    # Helper to get a value from the spec with fall‑back to a provided default.
    def _from_spec(name, default):
        if isinstance(spec, dict):
            return spec.get(name, default)
        if hasattr(spec, "get"):
            try:
                return spec.get(name, default)
            except Exception:
                pass
        return default
    # Iterate over all arguments that are defined by the scheme.
    for arg in getattr(self, "args", []):
        # Skip unknown objects quietly.
        try:
            name = arg.name
        except Exception:
            continue
        # Retrieve the value: spec value if available, otherwise the argument's own default.
        val = _from_spec(name, arg.default)
        # If the argument is itself a dictionary option with a nested scheme,
        # merge its defaults on top of any existing dict value.
        if hasattr(arg, "scheme") and arg.scheme:
            try:
                nested_defaults = arg.scheme.build_defaults()
                if isinstance(val, dict):
                    # Merge nested defaults into existing dictionary.
                    merged = dict(val)
                    merged.update(nested_defaults)
                else:
                    merged = nested_defaults
                val = merged
            except Exception:
                # If the nested defaults cannot be built, ignore silently.
                pass
        defaults[name] = val
    return defaults

