                    f"Length constraint for argument '{name}' must be an integer, got {type(max_len).__name__}"
                )
        if max_len < 0:
            raise ValueError(
                f"Length constraint for argument '{name}' cannot be negative, got {max_len}"
            )

        # Check if the value has a length
        try:
            actual_len = len(value)
        except TypeError:
            continue  # value has no length; skip

        if actual_len > max_len:
            raise ValueError(
                f"Argument '{name}' length {actual_len} exceeds maximum allowed {max_len}"
            )

def validate_choices_args(self, args):
        """Check if value of choice arguments is one of the available choices.

        :param args: The received arguments.
        """
        # The argument definitions are expected to be stored in self.parsed_yaml['args']
        arg_definitions = self.parsed_yaml.get('args', {})
        if not isinstance(arg_definitions, dict):
            # In case the YAML parser returned something else, skip validation
            return

        for arg_name, arg_attrs in arg_definitions.items():
            # Ensure we are dealing with a dictionary that may contain 'choices'
            if not isinstance(arg_attrs, dict) or 'choices' not in arg_attrs:
                continue
            choices = arg_attrs.get('choices')
            # We expect choices to be an iterable of allowed values
            if choices is None:
                continue
            if not isinstance(choices, (list, tuple, set)):
                # Invalid configuration; skip or raise a warning
                continue

            # If the argument was supplied, validate its value
            if arg_name in args:
                value = args[arg_name]
                if value not in choices:
                    allowed = ", ".join(map(str, choices))
                    raise ValueError(
                        f"Argument '{arg_name}' has invalid value '{value}'. "
                        f"Allowed values: {allowed}"
                    )

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    if not isinstance(args, dict):
        raise TypeError("args must be a mapping of argument names to values")
    # Retrieve mapping of argument name to allowed choices.  The attribute
    # name may vary; common choices are `_choices` or `choices`.
    choices_def = getattr(self, "_choices", None) or getattr(self, "choices", {})
    if not isinstance(choices_def, dict):
        # If no explicit choices definition, nothing to validate
        return
    for arg_name, value in args.items():
        if arg_name not in choices_def:
            continue
        allowed = choices_def[arg_name]
        # Ensure allowed is an iterable of permissible values
        if not hasattr(allowed, "__contains__"):
            raise TypeError(f"Choices for argument '{arg_name}' must be an iterable of allowed values")
        # Determine if the argument value is a collection of choices or a single choice
        if isinstance(value, (list, tuple, set)):
            for v in value:
                if v not in allowed:
                    raise ValueError(
                        f"Invalid value for argument '{arg_name}': {v!r}. "
                        f"Expected one of {tuple(allowed)}"
                    )
        else:
            if value not in allowed:
                raise ValueError(
                    f"Invalid value for argument '{arg_name}': {value!r}. "
                    f"Expected one of {tuple(allowed)}"
                )

def validate_choices_args(self, args):
