def validate_choices_args(self, args):
    """
    Check if value of choice arguments is one of the available choices.

    Args
    ----
    args : dict
        Mapping of argument names to their provided values.  Each value
        may be a scalar or an iterable of scalars.
    """
    # obtain the known argument definitions
    arg_defs = getattr(self, "parsed_yaml", {}).get("args", {})
    for arg_name, arg_value in args.items():
        # skip arguments that are not defined in the spec
        if arg_name not in arg_defs:
            continue

        # Grab the argument attributes from the spec
        attrs = arg_defs[arg_name]
        # The spec can be a dict; otherwise we treat it as no choices
        if isinstance(attrs, dict):
            choices = attrs.get("choices")
        else:
            choices = None

        if not choices:
            continue  # no restrictions for this argument

        # If the value itself is a collection of values (list, tuple, set, or
        # any other iterable that is not a string), validate each member.
        # Strings are considered scalars.
        try:
            is_iter = hasattr(arg_value, "__iter__") and not isinstance(arg_value, (str, bytes))
        except Exception:
            is_iter = False

        if is_iter:
            invalid_items = [v for v in arg_value if v not in choices]
            if invalid_items:
                msg = (
                    f"Invalid value(s) for argument '{arg_name}': {invalid_items}. "
                    f"Expected one of {choices}."
                )
                raise ValueError(msg)
        else:
            if arg_value not in choices:
                msg = (
                    f"Invalid value for argument '{arg_name}': {arg_value}. "
                    f"Expected one of {choices}."
                )
                raise ValueError(msg)

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    try:
        arg_defs = self.parsed_yaml.get('args', {})
    except AttributeError:
        # No argument definitions available; nothing to validate
        return

    # Normalize arg_defs to list of tuples (arg_name, arg_attrs)
    arg_def_items = []

    if isinstance(arg_defs, dict):
        for name, attrs in arg_defs.items():
            if isinstance(attrs, dict):
                arg_def_items.append((name, attrs))
    elif isinstance(arg_defs, list):
        for item in arg_defs:
            if isinstance(item, dict) and len(item) == 1:
                name, attrs = next(iter(item.items()))
                if isinstance(attrs, dict):
                    arg_def_items.append((name, attrs))

    for arg_name, arg_attrs in arg_def_items:
        if 'choices' not in arg_attrs:
            continue

        expected = arg_attrs['choices']
        if not isinstance(expected, (list, tuple)):
            # If choices is not a list-like, skip validation
            continue

        # Get the actual value supplied for this argument
        value = args.get(arg_name)
        if value is None:
            continue

        # Value may be a list/tuple of selections
        if isinstance(value, (list, tuple)):
            for v in value:
                if v not in expected:
                    raise ValueError(
                        f"Invalid choice for argument '{arg_name}': {v}. "
                        f"Expected one of {expected}"
                    )
        else:
            if value not in expected:
                raise ValueError(
                    f"Invalid choice for argument '{arg_name}': {value}. "
                    f"Expected one of {expected}"
                )
    return None

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Ensure args is a sequence (but avoid treating strings as a sequence of chars)
    if not isinstance(args, (list, tuple)):
        raise TypeError(f"args must be a sequence, got {type(args).__name__}")

    # Retrieve minimum and maximum bounds from the instance.  They may be
    # named ``min_``/``max_`` or ``min``/``max`` – fall back to None if not
    # defined.
    min_val = getattr(self, "min_", None)
    max_val = getattr(self, "max_", None)
    if min_val is None:
        min_val = getattr(self, "min", None)
    if max_val is None:
        max_val = getattr(self, "max", None)

    # At least one of minimum or maximum must be provided; otherwise we cannot
    # validate anything meaningful.
    if min_val is None and max_val is None:
        raise AttributeError(
            "Neither 'min/' 'min_' nor 'max/' 'max_' attributes are defined on the instance"
        )

    for idx, value in enumerate(args):
        # Skip None values – they are considered missing arguments and are
        # allowed to pass validation.  Adjust behaviour if a different policy
        # is required.
        if value is None:
            continue

        # Comparisons must be supported; if not, raise a clear TypeError.
        try:
            if min_val is not None and value < min_val:
                raise ValueError(
                    f"Argument at position {idx} ({value}) is less than the minimum "
                    f"allowed value {min_val}"
                )
            if max_val is not None and value > max_val:
                raise ValueError(
                    f"Argument at position {idx} ({value}) exceeds the maximum "
                    f"allowed value {max_val}"
                )
        except TypeError as exc:
            raise TypeError(
                f"Cannot compare argument at position {idx} ({value}) "
                f"with boundary values (min={min_val}, max={max_val})"
            ) from exc

    return args

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments. ``args`` can be an iterable of
        values (in which case the instance must provide ``self.min`` and
        ``self.max`` attributes) or a mapping/sequence of ``(name, value)``
        tuples for which min and max are expected to be stored as
        ``{name}_min`` and ``{name}_max`` attributes on the instance.
    """
    # Helper to raise a readable error
    def _raise(name, value, mn, mx):
        raise ValueError(
            f"Argument '{name}' with value {value} out of "
            f"range [{mn!r}, {mx!r}]"
        )

    # Case 1: simple iterable of values, instance provides min and max
    if hasattr(self, "min") and hasattr(self, "max"):
        min_val, max_val = getattr(self, "min"), getattr(self, "max")
        if min_val is None or max_val is None:
            # If default min or max is missing, we treat it as unbounded
            empty_default = True
        else:
            empty_default = False
        for i, v in enumerate(args):
            # Skip None values
            if v is None:
                continue
            try:
                if not empty_default:
                    if v < min_val:
                        _raise(f"arg{i}", v, min_val, max_val)
                    if v > max_val:
                        _raise(f"arg{i}", v, min_val, max_val)
                # If empty_default is True we don't enforce bounds
            except TypeError as exc:
                raise TypeError(
                    f"Argument 'arg{i}' value {v!r} is not comparable to the "
                    f"default bounds {min_val!r}/{max_val!r} ({exc})"
                ) from exc
        return

    # Case 2: args is a mapping or iterable of (name, value)
    # Normalise into items
    if isinstance(args, dict):
        items = args.items()
    else:
        # attempt to iterate expecting pairs
        try:
            items = iter(args)
        except Exception as exc:
            raise TypeError(
                "args must be a mapping or an iterable of (name, value) pairs"
            ) from exc

    for name, value in items:
        if value is None:
            continue
        min_attr = f"{name}_min"
        max_attr = f"{name}_max"
        if not hasattr(self, min_attr) or not hasattr(self, max_attr):
            # No explicit bounds defined for this argument; skip validation
            continue
        mn, mx = getattr(self, min_attr), getattr(self, max_attr)
        if mn is None or mx is None:
            # Treat as unbounded if either bound is None
            continue
        try:
            if value < mn:
                _raise(name, value, mn, mx)
            if value > mx:
                _raise(name, value, mn, mx)
        except TypeError as exc:
            raise TypeError(
                f"Argument '{name}' value {value!r} is not comparable to "
                f"the bounds {mn!r}/{mx!r} ({exc})"
            ) from exc
    # No return needed – validation errors will raise; otherwise success
    return

def validate_min_max_args(self, args):
    """Check if value of arguments is between minimum and maximum values.

    :param args: The received arguments.
    """
    # Determine the structure of args: either dict-like or a sequence
    try:
        if isinstance(args, dict):
            # Handle typical keys and common aliases
            value = args.get('value', args.get('val'))
            minimum = args.get('min', args.get('minimum'))
            maximum = args.get('max', args.get('maximum'))

            if value is None:
                raise ValueError("Missing 'value' in arguments")
            if minimum is None or maximum is None:
                raise ValueError("Missing 'min'/'maximum' in arguments")
        else:
            # Assume args is iterable: value, min, max
            items = tuple(args)
            if len(items) < 3:
                raise ValueError("Argument sequence must contain at least value, min, and max")
            value, minimum, maximum = items[0], items[1], items[2]
    except Exception as exc:
        raise ValueError(f"Invalid arguments format: {exc}") from exc

    # Validate that minimum and maximum are comparable numbers
    try:
        if not all(isinstance(v, (int, float)) for v in (minimum, maximum)):
            raise TypeError("Minimum and maximum must be numeric types")
        if minimum > maximum:
            raise ValueError("Minimum value cannot be greater than maximum")
    except Exception as exc:
        raise ValueError(f"Invalid min/max values: {exc}") from exc

    # Validate that value is numeric
    if not isinstance(value, (int, float)):
        raise TypeError("Value must be a numeric type")

    # Check range
    if not (minimum <= value <= maximum):
        raise ValueError(
            f"Value {value!r} not in range [{minimum!r}, {maximum!r}]")

    return args

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                 spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic validation of inputs
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, dict):
        raise TypeError("spec_option must be a dict")

    # Prefer an explicit factory callable if provided
    factory = spec_option.get("factory")
    if callable(factory):
        try:
            return factory(subcommand, type_name, option_name, **spec_option)
        except Exception as exc:
            raise RuntimeError(
                f"Factory callable failed for '{type_name}' on "
                f"subcommand '{subcommand}'") from exc

    # Fallback to creating a class instance by fully–qualified path
    class_path = spec_option.get("class")
    if class_path and isinstance(class_path, str):
        try:
            import importlib
            module_path, attr_name = class_path.rsplit(".", 1)
            module = importlib.import_module(module_path)
            cls = getattr(module, attr_name)
            if not isinstance(cls, type):
                raise TypeError(f"Attribute '{attr_name}' is not a class")
            return cls(subcommand, type_name, option_name, **spec_option)
        except Exception as exc:
            raise RuntimeError(
                f"Could not load class '{class_path}' for complex argument "
                f"'{type_name}'") from exc

    # If nothing else works, construct a simple container object
    try:
        attributes = {
            "subcommand": subcommand,
            "type_name": type_name,
            "option_name": option_name,
        }
        attributes.update(spec_option)
        # Dynamically create a minimal class to hold the attributes
        ComplexArgType = type(
            type_name,
            (object,),
            {"__slots__": attributes.keys()},
        )
        instance = ComplexArgType()
        for key, value in attributes.items():
            setattr(instance, key, value)
        return instance
    except Exception as exc:
        raise RuntimeError(
            f"Failed to construct complex argument type '{type_name}'") from exc

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Defensive handling of various input types
    if args is None:
        return {}, {}

    # Convert a list of (key, value) tuples to a flat dict
    if isinstance(args, list):
        try:
            flat_args = {k: v for k, v in args}
        except Exception:
            raise ValueError("args as list must contain (key, value) tuples")
    elif isinstance(args, dict):
        flat_args = args.copy()
    else:
        raise TypeError("args must be a dict or a list of (key, value) tuples")

    # Define a set of keys that are considered control arguments.
    # These typically control the processor itself rather than being
    # passed down to the Ansible playbooks.  The set can be extended
    # by subclasses or overridden if necessary.
    control_keys = {
        'action', 'destroy', 'config', 'subcommand', 'help',
        'debug', 'verbose', 'dry_run', 'output', 'plan',
        'infra', 'environment', 'name'
    }

    control_args = {}
    nested_args = {}

    for key, value in flat_args.items():
        if key in control_keys or key.startswith('control_'):
            control_args[key] = value
        else:
            nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    # Handle None or non-dict input gracefully
    if not args:
        return {}, {}
    if not isinstance(args, dict):
        raise ValueError("args must be a dictionary of argument key/value pairs")

    control_args = {}
    nested_args = {}

    for key, value in args.items():
        if isinstance(key, str):
            # Identify control arguments by prefix 'control_' (case‑insensitive)
            if key.lower().startswith('control_'):
                control_args[key] = value
                continue
            # Identify custom arguments by prefix 'custom_' and map to nested key
            if key.lower().startswith('custom_'):
                # Use the custom key as is in nested_args (the caller can decide how to use it)
                nested_args[key] = value
                continue
        # All other keys are treated as nested
        nested_args[key] = value

    return control_args, nested_args

def get_nested_custom_and_control_args(self, args):
    """Split input arguments to control nested and custom.

    Controls arguments: control the IR behavior. These arguments
        will not be put into the spec yml file
    Nested arguments: are used by the Ansible playbooks and will be put
        into the spec yml file.
    Custom arguments: Custom ansible variables to be used instead of the
        normal nested usage.

    :param args: the collected list of args.
    :return: (dict, dict): flat dicts (control_args, nested_args)
    """
    control_args = {}
    nested_args = {}

    # Normalize args to a dict of key/value pairs.
    if isinstance(args, dict):
        data = args
    else:
        try:
            data = dict(args)
        except Exception as exc:
            raise ValueError(f"args must be a dict or an iterable of (key, value) tuples, got {type(args)}") from exc

    for key, value in data.items():
        # Ensure key is string; skip non-string keys.
        try:
            key_str = str(key)
        except Exception:
            continue

        # Control arguments are prefixed with 'control_'.
        if key_str.startswith('control_'):
            control_args[key_str] = value
        else:
            nested_args[key_str] = value

    return control_args, nested_args

@staticmethod
def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    if not isinstance(vars_dict, dict):
        raise TypeError("vars_dict must be a dictionary")
    if not extra_vars:
        return vars_dict
    # Support a single dictionary
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict
    # Support an iterable of dictionaries (typically a list)
    try:
        iterator = iter(extra_vars)
    except TypeError:
        raise TypeError("extra_vars must be a dict, list, or iterable of dicts")
    for item in iterator:
        if not isinstance(item, dict):
            raise TypeError("All items in extra_vars must be dictionaries")
        vars_dict.update(item)
    return vars_dict

