        if vars_dict is None:
            vars_dict = {}
        elif not isinstance(vars_dict, dict):
            raise TypeError(f"vars_dict must be a dict, got {type(vars_dict).__name__}")

        # No extra_vars to merge
        if not extra_vars:
            return vars_dict

        # If a single dict is provided instead of a list, wrap it
        if isinstance(extra_vars, dict):
            extra_vars = [extra_vars]

        # Validate that extra_vars is an iterable of dictionaries
        if not isinstance(extra_vars, (list, tuple)):
            raise TypeError(f"extra_vars must be a list or tuple of dicts, got {type(extra_vars).__name__}")

        # Merge each dict into the result
        merged = dict(vars_dict)
        for idx, ev in enumerate(extra_vars):
            if not isinstance(ev, dict):
                raise TypeError(f"extra_vars[{idx}] must be a dict, got {type(ev).__name__}")
            merged.update(ev)

        return merged

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
