    """
    # Ensure vars_dict is a dictionary; if not, raise an informative error
    if not isinstance(vars_dict, dict):
        raise ValueError("vars_dict must be a dictionary")

    # If there are no extra variables, return the original dictionary unchanged
    if not extra_vars:
        return vars_dict

    # Normalise extra_vars: if a single dictionary, wrap it in a list; otherwise iterate
    if isinstance(extra_vars, dict):
        extra_list = [extra_vars]
    else:
        try:
            extra_list = list(extra_vars)
        except TypeError:
            raise ValueError("extra_vars must be a dict or iterable of dicts/tuples")

    # Create a copy to avoid mutating the input dictionary, then merge in order
    merged = dict(vars_dict)
    for item in extra_list:
        if isinstance(item, dict):
            merged.update(item)
        elif isinstance(item, (tuple, list)) and len(item) == 2:
            key, value = item
            merged[key] = value
        else:
            # Unsupported format: skip or raise an error
            # For safety, we skip silently
            continue

    return merged

def merge_extra_vars(vars_dict, extra_vars=None):
    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
