        raise TypeError("vars_dict must be a dict")

    # If no extra vars provided, simply return a copy of the original dictionary
    if extra_vars is None:
        return vars_dict.copy()

    # Handle the case where extra_vars is itself a dictionary
    if isinstance(extra_vars, dict):
        merged = vars_dict.copy()
        merged.update(extra_vars)
        return merged

    # If extra_vars is a list or tuple, iterate over its items
    if not isinstance(extra_vars, (list, tuple)):
        raise TypeError("extra_vars must be a dict, list, or tuple")

    merged = vars_dict.copy()
    for item in extra_vars:
        if isinstance(item, dict):
            # Merge each key/value pair
            merged.update(item)
        elif isinstance(item, str):
            # Treat a string like "key=value" or just a key
            if "=" in item:
                key, value = item.split("=", 1)
                merged[key] = value
            else:
                merged[item] = None
        else:
            # Unsupported item type; ignore to keep function robust
            continue
    return merged

@staticmethod
