    """Extend ``vars_dict`` with ``extra-vars``

    :param vars_dict: Dictionary to merge extra-vars into
    :param extra_vars: List of extra-vars
    """
    # Ensure we have a dictionary to work with
    if vars_dict is None:
        vars_dict = {}
    # If no extra vars provided, return the original dictionary
    if not extra_vars:
        return vars_dict

    # If extra_vars is a dict, update directly
    if isinstance(extra_vars, dict):
        vars_dict.update(extra_vars)
        return vars_dict

    # If extra_vars is an iterable (list or tuple), process each element
    if isinstance(extra_vars, (list, tuple)):
        for item in extra_vars:
            if isinstance(item, dict):
                # Merge key/value pairs
                vars_dict.update(item)
            elif isinstance(item, str):
                # Expecting "key=value" format
                if "=" in item:
                    key, _, value = item.partition("=")
                    vars_dict[key] = value
                else:
                    # Treat a bare string as a flag with value True
                    vars_dict[item] = True
            else:
                # Unsupported item type; ignore or you may raise an exception
                continue
        return vars_dict

    # If extra_vars is some other type, simply return the dictionary unchanged
    return vars_dict

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     workspace
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    # Validate the playbook path
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if not os.path.isfile(playbook_path):
        raise FileNotFoundError(f"Playbook not found: {playbook_path}")

    # Base command
    command = ["ansible-playbook", playbook_path]

    # Add verbosity if specified
    if verbose is not None:
        try:
            level = int(verbose)
            if level > 0:
                command.append('-' + 'v' * level)
        except Exception:
            pass  # ignore invalid verbosity and keep default

    # Normalize ansible_args
    if ansible_args is None:
        ansible_args = {}
    for key, value in ansible_args.items():
        if not isinstance(key, str):
            continue
        arg = key
        if not arg.startswith("--"):
            arg = "--" + arg.lstrip("-")
        if value is None:
            continue
        if isinstance(value, bool):
            if value:
                command.append(arg)
        else:
            command.extend([arg, str(value)])

    # Add extra_vars if supplied
    if extra_vars:
        command.extend(["--extra-vars", json.dumps(extra_vars)])

    # Execute the playbook
    result = subprocess.run(command, stdout=subprocess.PIPE,
                            stderr=subprocess.STDOUT, text=True)

    if result.returncode != 0:
        raise RuntimeError(
            f"ansible-playbook failed with exit code {result.returncode}\n{result.stdout}"
        )

    return result.stdout

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import subprocess
    import logging
    import os

    logger = logging.getLogger(__name__)

    # Resolve playbook path relative to the workspace, if necessary
    if not os.path.isabs(playbook_path):
        playbook_path = os.path.join(ir_workspace.path, playbook_path)

    # Build verbosity flag
    if verbose is None:
        verbosity = "-v"
    else:
        try:
            level = int(verbose)
            if level <= 0:
                verbosity = "-v"
            elif level >= 5:
                verbosity = "-vvvvv"
            else:
                verbosity = "-" + "v" * level
        except Exception:
            verbosity = "-v"

    # Base command
    cmd = ["ansible-playbook", verbosity, playbook_path]

    # Append custom ansible arguments
    if ansible_args:
        for key, value in ansible_args.items():
            # Ensure key starts with '--'
            if not key.startswith("--"):
                key = f"--{key}"
            if isinstance(value, bool):
                if value:
                    cmd.append(key)
            else:
                cmd.append(f"{key}={value}")

    # Pass extra variables as a single string
    if extra_vars:
        ev_str = " ".join(f"{k}={v}" for k, v in extra_vars.items())
        cmd.extend(["--extra-vars", ev_str])

    logger.debug("Executing ansible command: %s", " ".join(cmd))
    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=False)
    except FileNotFoundError as e:
        raise RuntimeError("ansible-playbook executable not found") from e
    except Exception as e:
        raise RuntimeError(f"Error executing ansible-playbook: {e}") from e

    if result.returncode != 0:
        err_msg = (
            f"ansible-playbook returned non-zero exit status {result.returncode}\n"
            f"STDOUT:\n{result.stdout}\n"
            f"STDERR:\n{result.stderr}"
        )
        raise RuntimeError(err_msg)

    return result.stdout.splitlines() if result.stdout else []

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
