    # Construct the base command
    cmd = ["ansible-playbook"]

    # Handle verbosity
    if verbose is not None:
        try:
            ver = int(verbose)
        except Exception:
            raise ValueError("verbose must be an integer or None") from None
        if ver < 0 or ver > 5:
            raise ValueError("verbose must be between 0 and 5")
        if ver > 0:
            cmd.append("-" + "v" * ver)

    # Append custom ansible-playbook arguments
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict or None")
        for key, value in ansible_args.items():
            if isinstance(value, bool):
                if value:
                    cmd.append(f"--{key}")
            else:
                cmd.append(f"--{key}")
                cmd.append(str(value))

    # Pass extra variables in a safe JSON format
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict or None")
        # Convert dict to JSON string – ansible accepts a JSON string for --extra-vars
        cmd.extend(["--extra-vars", json.dumps(extra_vars)])

    # Add the playbook file
    cmd.append(playbook_path)

    # Prepare environment: carry over the workspace path if present
    env = os.environ.copy()
    if hasattr(ir_workspace, "path"):
        env["IR_WORKSPACE"] = ir_workspace.path
    elif hasattr(ir_workspace, "name"):
        env["IR_WORKSPACE"] = ir_workspace.name

    # Log the command for debugging purposes
    try:
        logger = getattr(ir_plugin, "logger", None) or __import__("logging").getLogger(__name__)
    except Exception:
        logger = __import__("logging").getLogger(__name__)
    logger.debug("Executing ansible-playbook: %s", " ".join(cmd))

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            env=env,
            capture_output=True,
            text=True,
            check=False,
        )
    except FileNotFoundError:
        raise RuntimeError("ansible-playbook executable not found. Ensure it is installed and in PATH")
    except Exception as exc:
        raise RuntimeError(f"Failed to run ansible-playbook: {exc}") from exc

    # If the playbook failed, raise an informative error
    if result.returncode != 0:
