def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An InfraredPlugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os, json, subprocess, logging

    logger = logging.getLogger(__name__)

    # Resolve the absolute path to the playbook
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if not playbook_path.startswith('/') and ir_workspace and hasattr(ir_workspace, 'root'):
        playbook_abs = os.path.join(ir_workspace.root, playbook_path)
    else:
        playbook_abs = playbook_path

    if not os.path.isfile(playbook_abs):
        raise FileNotFoundError(f"Playbook not found: {playbook_abs}")

    # Base command
    cmd = ["ansible-playbook"]

    # Verbosity handling
    if verbose is None:
        # default verbosity: one level
        cmd.append("-v")
    else:
        try:
            level = int(verbose)
            if level < 0:
                level = 0
        except Exception:
            level = 1
        verb = '-' + 'v' * level
        cmd.append(verb)

    # Add ansible_args from dict
    if ansible_args:
        if not isinstance(ansible_args, dict):
            raise TypeError("ansible_args must be a dict")
        for key, value in ansible_args.items():
            # Normalize key to start with '--'
            if not key.startswith('--'):
                key = f"--{key}"
            cmd.append(key)
            # If value is not None and not bool True, append it
            if value is not None and value is not True:
                cmd.append(str(value))

    # Extra vars handling
    if extra_vars:
        if not isinstance(extra_vars, dict):
            raise TypeError("extra_vars must be a dict")
        try:
            ev_str = json.dumps(extra_vars, ensure_ascii=False)
        except Exception as e:
            raise ValueError(f"Failed to serialize extra_vars: {e}")
        cmd.extend(["--extra-vars", ev_str])

    # Append the playbook path
    cmd.append(playbook_abs)

    logger.debug("Executing ansible command: %s", " ".join(cmd))

    try:
        result = subprocess.run(cmd, capture_output=True, text=True, check=False)
    except FileNotFoundError as e:
        raise RuntimeError(f"ansible-playbook executable not found: {e}") from e
    except Exception as e:
        raise RuntimeError(f"Failed to execute ansible-playbook: {e}") from e

    if result.returncode != 0:
        err_msg = (f"Ansible playbook '{playbook_abs}' failed with return code "
                   f"{result.returncode}\nstdout: {result.stdout}\n"
                   f"stderr: {result.stderr}")
        raise RuntimeError(err_msg)

    return result.stdout

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dictionary")

    # Determine the list of option objects for the given parser.
    options = None
    if hasattr(self, "parsers"):
        options = self.parsers.get(parser_name) if isinstance(self.parsers, dict) else None
    if options is None:
        # Try to look up an attribute with the parser name directly.
        options = getattr(self, parser_name, None)

    if options is None:
        raise ValueError(f"Unknown parser name: {parser_name}")

    # Ensure options is iterable.
    try:
        iterable = iter(options)
    except TypeError:
        iterable = [options]

    for opt in iterable:
        # Prefer a `name` attribute; fallback to key 'name'.
        name = getattr(opt, "name", None)
        if name is None and isinstance(opt, dict):
            name = opt.get("name")
        if not name:
            continue  # skip options without a recognizable name

        if name not in values_dict:
            continue  # nothing to convert for missing value

        # Resolve the converter; if none provided, keep string as-is.
        converter = getattr(opt, "convert", None)
        if converter is None and isinstance(opt, dict):
            converter = opt.get("convert")
        if not callable(converter):
            converter = lambda x: x

        try:
            values_dict[name] = converter(values_dict[name])
        except Exception as exc:
            raise ValueError(f"Failed to convert argument '{name}' for parser '{parser_name}': {exc}") from exc

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    # Attempt to locate the parser for the given command name
    parser = None
    # `self.parsers` is assumed to hold a mapping of parser names to ArgumentParser objects
    if hasattr(self, 'parsers'):
        parser = self.parsers.get(parser_name)
    if parser is None:
        # If we cannot find the parser, nothing to convert
        return values_dict

    for action in getattr(parser, '_actions', []):
        dest = getattr(action, 'dest', None)
        if not dest or dest in ('help', argparse.SUPPRESS):
            continue

        if dest not in values_dict:
            continue

        raw_value = values_dict[dest]
        # Skip conversion if the value is already None
        if raw_value is None:
            continue

        # Determine the expected type
        expected_type = getattr(action, 'type', None)

        # Handle boolean flags specially: store_true/store_false
        if hasattr(action, 'const') and action.const in (True, False):
            try:
                # If the raw value is a string, interpret common truthy/falsy values
                if isinstance(raw_value, str):
                    lowered = raw_value.strip().lower()
                    if lowered in ('true', '1', 'yes', 'on'):
                        values_dict[dest] = True
                    elif lowered in ('false', '0', 'no', 'off'):
                        values_dict[dest] = False
                    else:
                        # Fall back to bool conversion of the string
                        values_dict[dest] = bool(raw_value)
                else:
                    values_dict[dest] = bool(raw_value)
            except Exception:
                # Leave the original value if conversion fails
                pass
            continue

        # If no specific type is defined, leave the value as is
        if expected_type is None:
            continue

        try:
            values_dict[dest] = expected_type(raw_value)
        except Exception:
            # If conversion fails, preserve the original string value
            pass

    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    :return: The modified values_dict with types converted where possible.
    """
    if not isinstance(values_dict, dict):
        raise TypeError("values_dict must be a dict")
    # Retrieve a mapping of argument names to conversion functions for the given parser.
    # The expected structure is: self.parser_arg_types[parser_name] = {arg_name: conversion_func}
    arg_type_map = getattr(self, "parser_arg_types", {}).get(parser_name, {})
    for key, convert in arg_type_map.items():
        if key in values_dict and values_dict[key] is not None:
            try:
                values_dict[key] = convert(values_dict[key])
            except Exception:
                # If conversion fails, leave the original string value unchanged.
                pass
    return values_dict

def _convert_non_cli_args(self, parser_name, values_dict):
    """
    Casts arguments to correct types by modifying values_dict param.
    By default all the values are strings.
    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """
    import ast

    # Optional type mapping that subclasses may provide.
    # Expected format: self._arg_types = { "parser_name": { "arg_name": type_callable } }
    type_map = getattr(self, "_arg_types", {}).get(parser_name, {})

    # Helper to convert a value according to a type
    def _convert(val, expected_type):
        if isinstance(val, expected_type):
            return val
        try:
            # Special handling for booleans: convert typical string forms
            if expected_type is bool:
                if isinstance(val, str):
                    lowered = val.lower()
                    if lowered in ("true", "1", "yes", "on"):
                        return True
                    if lowered in ("false", "0", "no", "off"):
                        return False
                    # fallback to literal_eval
                    return bool(ast.literal_eval(val))
                return bool(val)
            # Try straightforward cast
            return expected_type(val)
        except Exception:
            # Fallback to literal_eval if possible
            try:
                res = ast.literal_eval(val)
                if isinstance(res, expected_type):
                    return res
            except Exception:
                pass
            # If all fails, return original
            return val

    # First apply explicit mapping for known arguments
    for arg, expected in type_map.items():
        if arg in values_dict:
            values_dict[arg] = _convert(values_dict[arg], expected)

    # For remaining arguments, try generic literal evaluation if the value is a string
    for arg, val in list(values_dict.items()):
        if isinstance(val, str):
            try:
                converted = ast.literal_eval(val)
                values_dict[arg] = converted
            except Exception:
                # leave the original string if evaluation fails
                pass
    return values_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Find possible spec files
    spec_file = os.path.join(plugin_dir, "plugin.json")
    if not os.path.isfile(spec_file):
        # Try common alternatives
        candidates = [
            "plugin-spec.json",
            "spec.json",
            "plugin.yaml",
            "plugin.yml",
            "spec.yaml",
            "spec.yml",
        ]
        for name in candidates:
            path = os.path.join(plugin_dir, name)
            if os.path.isfile(path):
                spec_file = path
                break
        else:
            # No spec file found
            return {}

    try:
        with open(spec_file, "r", encoding="utf-8") as f:
            if spec_file.lower().endswith((".yaml", ".yml")):
                try:
                    import yaml
                except Exception:
                    # yaml is missing, cannot parse
                    return {}
                data = yaml.safe_load(f)
            else:
                data = json.load(f)
    except Exception:
        # Any error reading/parsing the spec results in an empty dict
        return {}

    def _flatten(obj, parent_key="", sep="."):
        items = {}
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_key = f"{parent_key}{sep}{k}" if parent_key else k
                items.update(_flatten(v, new_key, sep=sep))
        elif isinstance(obj, list):
            for idx, val in enumerate(obj):
                new_key = f"{parent_key}{sep}{idx}" if parent_key else str(idx)
                items.update(_flatten(val, new_key, sep=sep))
        else:
            items[parent_key] = obj
        return items

    return _flatten(data)

def get_plugin_spec_flatten_dict(plugin_dir):
    """
    Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import json
    from pathlib import Path

    # Determine the spec file inside the plugin directory
    spec_file_candidates = ["plugin_spec.json", "plugin_spec.yaml", "plugin_spec.yml"]
    plugin_path = Path(plugin_dir)
    if not plugin_path.is_dir():
        raise ValueError(f"'{plugin_dir}' is not a valid directory")

    spec_path = None
    for name in spec_file_candidates:
        candidate = plugin_path / name
        if candidate.is_file():
            spec_path = candidate
            break

    if spec_path is None:
        raise FileNotFoundError(
            f"No plugin spec file found in '{plugin_dir}'. "
            f"Expected one of {spec_file_candidates}"
        )

    # Load the spec (JSON or YAML)
    try:
        with spec_path.open("r", encoding="utf-8") as f:
            if spec_path.suffix.lower() == ".json":
                spec = json.load(f)
            else:
                try:
                    import yaml
                except ImportError as exc:
                    raise RuntimeError(
                        "YAML plugin spec found but pyyaml is not installed"
                    ) from exc
                spec = yaml.safe_load(f)
    except Exception as exc:  # pragma: no cover
        raise RuntimeError(f"Failed to load plugin spec from '{spec_path}': {exc}") from exc

    # Flatten nested dicts into a single flat dict
    flat_spec = {}

    def _flatten(prefix, obj):
        if isinstance(obj, dict):
            for key, value in obj.items():
                new_prefix = f"{prefix}.{key}" if prefix else key
                _flatten(new_prefix, value)
        else:
            flat_spec[prefix] = obj

    _flatten("", spec)
    return flat_spec

