    if spec_data is None:
        return flat_dict

    def _flatten(d, parent_key=""):
        for k, v in d.items():
            new_key = f"{parent_key}.{k}" if parent_key else k
            if isinstance(v, dict):
                _flatten(v, new_key)
            else:
                flat_dict[new_key] = v

    _flatten(spec_data)
    return flat_dict

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    if not os.path.isdir(plugin_dir):
        raise FileNotFoundError(f"Plugin directory not found: {plugin_dir}")

    # Helper to load YAML if possible
    _yaml = None
    spec_path = None
    for filename in ("plugin.yaml", "plugin.yml", "plugin.json"):
        path = os.path.join(plugin_dir, filename)
        if os.path.isfile(path):
            spec_path = path
            break

    if spec_path is None:
        # Try to find any yaml/yml/json file inside the directory
        for root, _, files in os.walk(plugin_dir):
            for f in files:
                if f.endswith((".yml", ".yaml", ".json")):
                    spec_path = os.path.join(root, f)
                    break
            if spec_path:
                break

    if spec_path is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    def _load_yaml(file_path):
        try:
            import yaml
            with open(file_path, "r", encoding="utf-8") as fh:
                return yaml.safe_load(fh)
        except Exception:
            return None

    if spec_path.endswith((".yaml", ".yml")):
        spec_dict = _load_yaml(spec_path)
        if spec_dict is None:
            # fallback to JSON parsing error
            raise ValueError(f"Failed to parse YAML spec: {spec_path}")
    else:
        with open(spec_path, "r", encoding="utf-8") as fh:
            try:
                spec_dict = json.load(fh)
            except json.JSONDecodeError as e:
                raise ValueError(f"Failed to parse JSON spec: {spec_path}") from e

    if not isinstance(spec_dict, dict):
        raise ValueError(f"Spec root should be a dictionary but got {type(spec_dict)}")

    flat = {}

    def _flatten(prefix, obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                new_prefix = f"{prefix}.{k}" if prefix else k
                _flatten(new_prefix, v)
        else:
            flat[prefix] = obj

    _flatten("", spec_dict)
    return flat

