def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    import os
    env_var = 'CONFIG_PATH'
    try:
        current = os.getenv(env_var)
        if not current:
            path = getattr(self, 'config_path', None)
            if path:
                os.environ[env_var] = str(path)
                if hasattr(self, 'logger'):
                    self.logger.debug('Set %s=%s', env_var, os.environ[env_var])
    except Exception:
        # Silently ignore environment related errors
        pass

