def extend_cli(self, root_subparsers):
    """
    Adds the spec cli options to to the main entry point.

    :param subparser: the subparser object to extend.
    """
    if not root_subparsers:
        # nothing to add
        return

    # Try to add a --spec option if the object behaves like argparse.ArgumentParser.
    try:
        root_subparsers.add_argument(
            '-s', '--spec',
            dest='spec',
            help='Target spec to operate on',
            metavar='SPEC'
        )
    except Exception:
        # Fall back: if root_subparsers appears to be a subparsers collection,
        # create a new subparser named 'spec' that accepts a single positional argument.
        try:
            spec_parser = root_subparsers.add_parser('spec', help='Spec command')
            spec_parser.add_argument(
                'spec',
                help='Target address spec'
            )
        except Exception as exc:
            # If even that fails, propagate the original exception with context
            raise RuntimeError(
                f"Failed to extend CLI with spec options: {exc}"
            ) from exc

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, (str, bytes)) or not isinstance(root, (str, bytes)):
        raise ValueError("Both path and root must be string-like objects")
    # Normalize paths
    norm_path = os.path.normpath(os.path.abspath(path))
    norm_root = os.path.normpath(os.path.abspath(root))
    try:
        rel_path = os.path.relpath(norm_path, norm_root)
    except Exception as exc:
        raise ValueError(f"Cannot compute relative path from '{root}' to '{path}': {exc}") from exc
    # If the resulting relative path starts with '..', the path is not under root
    if rel_path == os.curdir:
        # path is exactly the root
        return ''
    if rel_path.startswith('..'):
        raise ValueError(f"Path '{path}' is not under root '{root}'")
    return rel_path

def strip_root(path, root):
    """Remove root from path, throw exception on failure."""
    import os
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if not isinstance(root, str):
        raise TypeError("root must be a string")
    try:
        path_abs = os.path.abspath(os.path.normpath(path))
        root_abs = os.path.abspath(os.path.normpath(root))
    except Exception as e:
        raise ValueError(f"Invalid path or root: {e}")
    if path_abs == root_abs:
        return ''
    if not path_abs.startswith(root_abs + os.sep):
        raise ValueError(f"Path '{path}' does not start with root '{root}'")
    stripped = path_abs[len(root_abs):].lstrip(os.sep)
    return stripped
